INSERT INTO categories (id, name, creator_id, is_public, parent_id) VALUES (90000, 'Môn Tư tưởng Hồ Chí Minh', 9999, false, NULL);
INSERT INTO categories (id, name, creator_id, is_public, parent_id) VALUES (90001, 'Chương 1', 9999, false, 90000);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90000, 'Khái niệm “Tư tưởng Hồ Chí Minh” không bao gồm nội dung nào sau', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90000, 'Hệ thống các quan điểm lý luận, phản ánh những vấn đề có tính quy luật của cách mạng Việt Nam.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90001, 'Nguồn gốc tư tưởng, lý luận của tư tưởng Hồ Chí Minh: chủ nghĩa Mác – Lênin; giá trị văn hoá dân tộc, tinh hoa văn hoá nhân loại.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90002, 'Nội dung cơ bản nhất của tư tưởng Hồ Chí Minh, bao gồm những vấn đề có liên quan trực tiếp đến cách mạng Việt Nam. Tư tưởng Hồ Chí Minh soi đường thắng lợi cho cách mạng Việt Nam, tài sản tinh thần to lớn của Đảng và dân tộc.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90003, 'Bao gồm những vấn đề có liên quan đến cách mạng thế giới, tài sản tinh thần cho cách mạng thế giới', true, 90000);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90001, 'Điền vào chỗ trống trong Văn kiện Đại hội lần thứ VI của Đảng Cộng sản Việt Nam (1986): “Muốn đổi mới tư duy, Đảng phải nắm vững bản chất cách mạng và khoa học của chủ nghĩa Mác – Lênin, kế thừa di sản quý báu về ……. của Hồ Chí Minh”:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90004, 'Lý luận và đường lối chính trị.', false, 90001);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90005, 'Tư tưởng và đường lối chính trị.', false, 90001);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90006, 'Tư tưởng và lý luận cách mạng.', true, 90001);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90007, 'Lý luận và thực tiễn cách mạng.', false, 90001);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90002, 'Khái niệm “Tư tưởng Hồ Chí Minh” lần đầu tiên được Đảng Cộng sản Việt Nam đưa ra tại đại hội lần thứ mấy?', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90008, 'Đại hội lần thứ VI (1986).', false, 90002);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90009, 'Đại hội lần thứ VII (1991).', true, 90002);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90010, 'Đại hội lần thứ VIII (1996).', false, 90002);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90011, 'Đại hội lần thứ IX (2001).', false, 90002);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90003, 'Đảng Cộng sản Việt Nam khẳng định: Tư tưởng Hồ Chí Minh “là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của nhân dân ta giành thắng lợi” là tại Đại hội lần thứ mấy?', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90012, 'Đại hội Đảng lần thứ IX (2001).', false, 90003);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90013, 'Đại hội Đảng lần thứ VII (1991).', false, 90003);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90014, 'Đại hội Đảng lần thứ XI (2011).', true, 90003);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90015, 'Đại hội Đảng lần thứ VI (1986).', false, 90003);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90004, 'Đối tượng nghiên cứu của môn học tư tưởng Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90016, 'Nghiên cứu cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh.', false, 90004);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90017, 'Nghiên cứu hệ thống quan điểm, quan niệm, lý luận về cách mạng Việt Nam của Hồ Chí Minh.', true, 90004);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90018, 'Nghiên cứu kết quả vận dụng, phát triển sáng tạo tư tưởng Hồ Chí Minh của Đảng Cộng sản Việt Nam qua các giai đoạn cách mạng.', false, 90004);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90019, 'Nghiên cứu những đánh giá của các danh nhân trên thế giới về Hồ Chí Minh.', false, 90004);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90005, '“Tư tưởng Hồ Chí Minh là một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam”. Những vấn đề cơ bản của cách mạng Việt Nam là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90020, 'Lực lượng cách mạng.', false, 90005);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90021, 'Phương pháp cách mạng.', false, 90005);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90022, 'Mục tiêu, nhiệm vụ cách mạng.', false, 90005);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90023, 'Cả ba phương án kia đều đúng.', true, 90005);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90006, 'Năm 1970, Đảng Cộng sản Việt Nam đưa ra khẩu hiệu tuyên truyền, cổ động về tư tưởng, tấm gương đạo đức Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90024, 'Toàn Đảng hãy ra sức học tập đường lối chính trị, tác phong và đạo đức cách mạng của Hồ Chủ tịch.', false, 90006);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90025, 'Toàn Đảng, toàn dân thực hiện cần, kiệm, liêm, chính, chí công, vô tư theo tấm gương của Chủ tịch Hồ Chí Minh vĩ đại.', false, 90006);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90026, 'Sống và làm việc theo gương Bác Hồ vĩ đại.', false, 90006);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90027, 'Sống, chiến đấu, lao động và học tập theo gương Bác Hồ vĩ đại.', true, 90006);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90007, 'Tại Đại hội lần thứ VII (1991), Đảng Cộng sản Việt Nam đã khẳng định Tư tưởng Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90028, 'Tài sản tinh thần quý báu của Đảng.', false, 90007);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90029, 'Tài sản tinh thần quý báu của Đảng và của nhân dân ta.', false, 90007);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90030, 'Tài sản tinh thần quý báu của Đảng, dân tộc và nhân dân ta.', false, 90007);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90031, 'Tài sản tinh thần quý báu của Đảng và của dân tộc.', true, 90007);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90008, 'Phương pháp luận nghiên cứu tư tưởng Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90032, 'Thống nhất tính Đảng và tính khoa học.', false, 90008);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90033, 'Thống nhất lý luận và thực tiễn.', false, 90008);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90034, 'Quan điểm lịch sử - cụ thể; quan điểm toàn diện và hệ thống.', false, 90008);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90035, 'Cả ba phương án kia đều đúng.', true, 90008);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90009, 'Khái niệm “Tư tưởng Hồ Chí Minh là kết quả của sự vận dụng sáng tạo chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta và trong thực tế, tư tưởng Hồ Chí Minh đã trở thành một tài sản tinh thần quý báu của Đảng và của dân tộc” được nêu ra ở Đại hội lần thứ mấy của Đảng Cộng sản Việt Nam?', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
