INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90013, 'Nghị quyết số 24C/18.65 về Kỷ niệm 100 năm Ngày sinh của Chủ tịch Hồ Chí Minh của UNESCO đã ghi nhận Chủ tịch Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90051, '"Anh hùng giải phóng dân tộc và nhà văn hoá kiệt xuất của Việt Nam".', true, 90013);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90052, '"Anh hùng giải phóng dân tộc và nhà văn hoá kiệt xuất của thế giới".', false, 90013);
