INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90014, 'Ý nghĩa của việc học tập môn học Tư tưởng Hồ Chí Minh là:', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90055, 'Góp phần nâng cao năng lực tư duy lý luận.', false, 90014);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90056, 'Củng cố niềm tin khoa học gắn với trau dồi tình cảm cách mạng, bồi dưỡng lòng yêu nước.', false, 90014);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90057, 'Xây dựng, rèn luyện phương pháp và phong cách công tác.', false, 90014);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90058, 'Cả ba phương án kia đều đúng', true, 90014);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90015, 'Phương pháp luận nào của việc nghiên cứu tư tưởng Hồ Chí Minh đã yêu cầu, khi nghiên cứu tư tưởng Hồ Chí Minh phải luôn luôn quán triệt mối liên hệ qua lại của các yếu tố, các bộ phận khác nhau trong sự gắn kết tất yếu của hệ thống tư tưởng đó xung quanh hạt nhân cốt lõi là tư tưởng độc lập, tự do, dân chủ và chủ nghĩa xã hội?', 'SINGLE_CHOICE', 90001, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90059, 'Thống nhất lý luận và thực tiễn.', false, 90015);
