INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90076, 'Nguyên tắc phân phối theo lao động thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam được Hồ Chí Minh giải thích là:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
