INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90077, 'Trong tác phẩm “Thường thức chính trị”, khi nói về những đặc điểm lớn của chủ nghĩa xã hội, Hồ Chí Minh giải thích nguyên nhân khiến cho trong chủ nghĩa xã hội: “Không có sự đối lập giữa thành thị và thôn quê, giữa lao động chân tay và lao động trí óc” là vì:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90307, 'Vì đô thị hóa rất nhanh, công nghiệp hóa, hiện đại hóa đất nước rất mạnh.', false, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90308, 'Vì công nhân, nông dân nắm quyền lực chính trị.', false, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90309, 'Vì thôn quê ngày càng văn minh, công nông ngày càng thông thái.', true, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90310, 'Vì mọi vùng nông thôn đều trở thành thành thị.', false, 90077);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90078, '“Đồng bào Nam bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi!”. Câu nói trên của Hồ Chí Minh được trích ra từ văn kiện nào?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
