INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90079, '“Chúng ta cách mệnh thì cũng phải liên lạc tất cả những đảng cách mệnh trong thế giới để chống lại tư bản và đế quốc chủ nghĩa”. Luận điểm đó được Hồ Chí Minh viết trong tác phẩm nào?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
