INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90082, 'Quan điểm nào sau đây không phải của Hồ Chí Minh?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90327, 'Trong cuộc đấu tranh chống chủ nghĩa đế quốc, chủ nghĩa thực dân, cách mạng thuộc địa có tầm quan trọng đặc biệt.', true, 90082);
