INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90083, 'Trong “Thư kêu gọi tổng khởi nghĩa” (năm 1945), Hồ Chí Minh viết: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà…..”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
