INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90088, 'Theo Hồ Chí Minh, giải phóng dân tộc bằng:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90351, 'Đấu tranh nghị trường.', false, 90088);
