INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90354, 'Cả ba phương án kia đều đúng.', false, 90088);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90089, 'Chọn đáp án đúng ở chỗ trống trong câu sau của Hồ Chí Minh: “Toàn quốc đồng bào hãy đứng dậy ….. mà tự giải phóng cho ta”.', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90355, 'Đem sức ta.', true, 90089);
