INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90099, 'Trong cách mạng giải phóng dân tộc, Hồ Chí Minh xác định lực lượng nào là gốc của cách mạng?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
