INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90395, 'Nông dân, tư sản.', false, 90099);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90396, 'Công nhân, tiểu tư sản.', false, 90099);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90397, 'Công nhân, nông dân.', true, 90099);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90100, 'Trong bài “Cách mạng Tháng Mười vĩ đại mở ra con đường giải phóng cho các dân tộc” (năm 1967), Hồ Chí Minh nhận định: “Trong cuộc đấu tranh gian khổ chống kẻ thù của giai cấp và của dân tộc, cần dùng …. chống lại bạo lực phản cách mạng, giành lấy chính quyền và bảo vệ chính quyền”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90398, 'Đấu tranh nghị trường.', false, 90100);
