INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90401, 'Đấu tranh hòa bình.', false, 90100);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90101, 'Theo Hồ Chí Minh, điều kiện tiên quyết để tiến lên xây dựng chủ nghĩa xã hội là:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
