INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90417, 'Cả ba phương án đều đúng.', false, 90104);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90105, 'Theo Hồ Chí Minh, mục tiêu cao nhất của chủ nghĩa xã hội là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
