INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90108, 'Theo tư tưởng Hồ Chí Minh, động lực quan trọng và quyết định của của chủ nghĩa xã hội ở Việt Nam là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
