INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90433, 'Xóa đói giảm nghèo.', false, 90108);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90109, 'Quan điểm nào sau đây của Hồ Chí Minh?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90434, 'Sự tàn bạo của chủ nghĩa tư bản đã chuẩn bị đất rồi. Chủ nghĩa xã hội chỉ còn phải làm cái việc là gieo hạt giống của công cuộc giải phóng nữa thôi.', true, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90435, 'Xem xét lại chủ nghĩa Mác về cơ sở lịch sử của nó, củng cố nó bằng dân tộc học phương Đông.', false, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90436, 'Chủ nghĩa dân tộc là động lực lớn của đất nước.', false, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90437, 'Cả ba phương án kia đều đúng', false, 90109);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90110, 'Theo Hồ Chí Minh, kẻ thù hung ác của chủ nghĩa xã hội là ai?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90438, 'Giặc ngoại xâm.', false, 90110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90439, 'Chủ nghĩa tư bản.', false, 90110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90440, 'Chủ nghĩa đế quốc.', false, 90110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90441, 'Chủ nghĩa cá nhân.', true, 90110);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90111, 'Quan điểm của Hồ Chí Minh về động lực xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90442, 'Động lực bên trong.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90443, 'Động lực bên ngoài.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90444, 'Ngăn ngừa “giặc nội xâm” là tham ô, lãng phí, quan liêu, các yếu tố kìm hãm, triệt tiêu nguồn lực vốn có của chủ nghĩa xã hội.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90445, 'Cả ba phương án kia đều đúng.', true, 90111);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90112, 'Quan điểm của Hồ Chí Minh về động lực quan trọng và quyết định xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90446, 'Sức mạnh thời đại, của tinh thần đoàn kết quốc tế.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90447, 'Sức mạnh của các thành quả khoa học - kỹ thuật thế giới.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90448, 'Sức mạnh vật chất và tinh thần của con người, của nhân dân lao động mà nòng cốt là công - nông - trí thức.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90449, 'Cả ba phương án kia đều đúng.', true, 90112);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90113, 'Đặc điểm to nhất khi Việt Nam quá độ lên chủ nghĩa xã hội theo tư tưởng Hồ Chí Minh là:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90450, 'Từ một nước thuộc địa, nửa phong kiến, trình độ pháp luật còn kém', false, 90113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90451, 'Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không kinh qua giai đoạn phát triển tư bản chủ nghĩa.', true, 90113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90452, 'Từ một nước lạc hậu, yếu kém về mọi mặt.', false, 90113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90453, 'Từ một nước thuộc địa, nửa phong kiến, nông nghiệp lạc hậu.', false, 90113);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90114, 'Theo Hồ Chí Minh, động lực quan trọng nhất của cách mạng xã hội chủ nghĩa Việt Nam là:', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90454, 'Động lực kinh tế.', false, 90114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90455, 'Đảng – Nhà nước – Mặt trận dân tộc thống nhất.', true, 90114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90456, 'Con người.', false, 90114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90457, 'Động lực văn hóa. là gì? dân.', false, 90114);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90115, 'Theo Hồ Chí Minh, mâu thuẫn cơ bản của thời kỳ quá độ ở Việt Nam', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90458, 'Mâu thuẫn giữa nghèo đói sau chiến tranh và đòi hỏi nâng cao đời sống nhân', false, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90459, 'Mâu thuẫn giữa nhu cầu phát triển cao của đất nước theo xu hướng tiến bộ và thực trạng kinh tế - xã hội quá thấp kém của nước ta.', true, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90460, 'Mâu thuẫn giữa ổn định xã hội và sự phá hoại của các thế lực thù địch.', false, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90461, 'Mâu thuẫn giữa trình độ khoa học kỹ thuật của ta thấp kém và nhu cầu hội nhập kinh tế thế giới.', false, 90115);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90116, 'Ngày 24/4/1957, khi nói chuyện với cán bộ, công nhân nhà máy dệt Nam Định, Hồ Chí Minh cho rằng: “Chế độ làm khoán là một điều kiện của chủ nghĩa xã hội, nó khuyến khích người công nhân luôn luôn tiến bộ, cho nhà máy tiến bộ. Làm khoán là ……”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90462, 'Tạo điều kiện phát triển sản xuất.', false, 90116);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90463, 'Ích chung và lại lợi riêng.', false, 90116);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90464, 'Tăng năng xuất lao động.', false, 90116);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90465, 'Cả ba phương án kia đều đúng.', true, 90116);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90117, 'Theo Hồ Chí Minh, trong điều kiện của nước ta, biện pháp cơ bản, quyết định, lâu dài trong xây dựng chủ nghĩa xã hội là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90466, 'Đem tài dân, sức dân, của dân làm lợi cho dân dưới sự lãnh đạo của Đảng.', true, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90467, 'Tiến hành công nghiệp hóa.', false, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90468, 'Xây dựng đội ngũ lãnh đạo đủ đức và tài.', false, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90469, 'Phát triển khoa học kỹ thuật.', false, 90117);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90118, 'Theo Hồ Chí Minh, biện pháp để tiến hành xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'SINGLE_CHOICE', 90002, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90470, 'Thực hiện cải tạo xã hội cũ, xây dựng xã hội mới, kết hợp cải tạo với xây dựng, lấy xây dựng làm chính.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90471, 'Kết hợp xây dựng và bảo vệ, đồng thời tiến hành hai nhiệm vụ chiến lược ở hai miền Nam - Bắc khác nhau trong phạm vi một quốc gia.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90472, 'Biện pháp cơ bản, quyết định, lâu dài trong xây dựng chủ nghĩa xã hội là đem của dân, tài dân, sức dân, làm lợi cho dân dưới sự lãnh đạo của Đảng.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90473, 'Cả ba phương án kia đều đúng.', true, 90118);
