INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90120, 'Hồ Chí Minh nói tới văn kiện nào trong câu sau: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta”?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90478, 'Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của', true, 90120);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90479, 'Nghị quyết Đại hội V Quốc tế Cộng sản.', false, 90120);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90480, 'Nghị quyết Đại hội VII Quốc tế cộng sản.', false, 90120);
