INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90121, 'Xã hội có chế độ dân chủ là đặc trưng về mặt nào của xã hội xã hội chủ nghĩa theo tư tưởng Hồ Chí Minh?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
