INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90484, 'Văn hóa.', false, 90121);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90485, 'Xã hội.', false, 90121);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90122, 'Tư tưởng "Đem tài dân, sức dân, của dân làm lợi cho dân" là nói đến mặt nào trong đặc trưng xã hội xã hội chủ nghĩa của Hồ Chí Minh?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90486, 'Kinh tế.', false, 90122);
