INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90489, 'Chủ thể xây dựng chủ nghĩa xã hội.', true, 90122);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90123, 'Trong vận dụng kinh nghiệm thực tiễn thế giới vào xây dựng chủ nghĩa xã hội, Hồ Chí Minh đã yêu cầu phải chống khuynh hướng nào?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90490, '"Giáo điều" và "xét lại".', true, 90123);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90491, '"Giáo điều" và "máy móc".', false, 90123);
