INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90124, 'Kẻ địch bên trong của mỗi người cần phải chống trong xây dựng chủ nghĩa xã hội theo Hồ Chí Minh là:', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
