INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90125, 'Đại hội lần thứ mấy của Đảng Cộng sản Việt Nam đã đề ra Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90498, 'Đại hội lần thứ VI (1986).', false, 90125);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90499, 'Đại hội lần thứ VII (1991).', true, 90125);
