INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90501, 'Đại hội lần thứ X (2006).', false, 90125);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90126, 'Quan điểm sau đây về quy luật hình thành Đảng Cộng sản là của ai: “Đảng Cộng sản ra đời là sản phẩm của sự kết hợp giữa chủ nghĩa Mác với phong trào công nhân”.', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90502, 'Mác.', false, 90126);
