INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90504, 'V.I. Lênin.', true, 90126);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90505, 'Hồ Chí Minh.', false, 90126);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90127, 'Theo Hồ Chí Minh, cách mạng Việt Nam cần phải có Đảng để làm gì?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90506, 'Xác định đường lối cách mạng đúng đắn và phương pháp cách mạng thích hơp.', false, 90127);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90507, 'Tổ chức dân chúng thực hiện đường lối, cách mạng do Đảng đề ra.', false, 90127);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90508, 'Gắn cách mạng Việt Nam với cách mạng thế giới nhằm tạo sức mạnh tổng hợp cho cách mạng Việt Nam.', false, 90127);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90509, 'Cả ba phương án kia đều đúng.', true, 90127);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90128, 'Theo Hồ Chí Minh thì Đảng Lao động Việt Nam là Đảng của ai?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90510, 'Đảng Lao động Việt Nam là Đảng của giai cấp công nhân Việt Nam.', false, 90128);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90511, 'Đảng Lao động Việt Nam là Đảng của giai cấp nông dân Việt Nam.', false, 90128);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90512, 'Đảng Lao động Việt Nam là Đảng của công nhân và trí thức Việt Nam.', false, 90128);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90513, 'Đảng Lao động Việt Nam là Đảng của giai cấp công nhân và nhân dân lao động, cho nên nó phải là Đảng của dân tộc Việt Nam.', true, 90128);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90129, 'Hồ Chí Minh yêu cầu Đảng phải là đạo đức, là văn minh, mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, người đầy tớ thật trung thành của ai?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90514, 'Của giai cấp công nhân.', false, 90129);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90515, 'Của giai cấp công nhân và giai cấp nông dân.', false, 90129);
