INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90155, 'Hồ Chí Minh nêu lên những yêu cầu gì về việc xây dựng đội ngũ cán bộ, công chức nhà nước?', 'SINGLE_CHOICE', 90003, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90618, 'Tuyệt đối trung thành với cách mạng; Hăng hái, thành thạo công việc, giỏi chuyên môn, nghiệp vụ; Liên hệ mật thiết với nhân dân.', true, 90155);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90619, 'Dám phụ trách, dám quyết đoán, dám chịu trách nhiệm, nhất là trong những tình huống khó khăn, “thắng không kiêu, bại không nản”.', false, 90155);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90620, 'Phải thường xuyên tự phê bình và phê bình, luôn luôn có ý thức và hạnh động vì sự lớn mạnh, trong sạch của Nhà nước.', false, 90155);
