INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90171, 'Theo Hồ Chí Minh, nền tảng cơ bản nhất quyết định sự lãnh đạo tất yếu của Đảng Cộng sản Việt Nam đối với cách mạng Việt Nam là?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
