INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90172, 'Theo Hồ Chí Minh, nguyên tắc nào trong hoạt động của Đảng phải là việc làm thường xuyên, như “mỗi ngày phải rửa mặt”.', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
