INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90173, 'Theo Hồ Chí Minh, khi lợi ích chung của Đảng mâu thuẫn với lợi ích riêng của cá nhân thì người đảng viên phải như thế nào?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
