INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90174, 'Tư tưởng về đảng kiểu mới của giai cấp vô sản, được Hồ Chí Minh vận dụng, phát triển trong quá trình sáng lập và rèn luyện Đảng Cộng sản Việt Nam là tư tưởng của ai?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
