INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90175, 'Điền vào chỗ trống trong câu nói sau của Hồ Chí Minh: “Đảng có những điều kiện kỷ luật bắt buộc mỗi đảng viên phải theo. Không có kỷ luật sắt không có Đảng. Đã vào Đảng thì phải theo tư tưởng của Đảng. Đảng đã chỉ thị nghị quyết là phải làm. Không làm thì … …”.', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
