INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90700, 'Đuổi ra khỏi Đảng.', true, 90175);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90176, 'Theo Hồ Chí Minh, việc Đảng cần làm ngay sau khi cuộc chống Mỹ, cứu nước của nhân dân Việt Nam hoàn toàn thắng lợi là?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
