INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90202, 'Theo Hồ Chí Minh, đoàn kết quốc tế có vai trò như thế nào đối với thắng lợi của cách mạng Việt Nam?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
