INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90203, 'Theo tư tưởng Hồ Chí Minh, một trong những nguyên tắc đoàn kết quốc tế là:', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90808, 'Các bên cùng có lợi.', false, 90203);
