INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90204, 'Câu nói sau đây của Hồ Chí Minh được viết trong bức thư nào: “Tôi khuyên đồng bào đoàn kết chặt chẽ và rộng rãi. Năm ngón tay có ngón ngắn ngón dài. Nhưng ngắn hay dài đều hợp nhau lại nơi bàn tay. Trong mấy triệu người cũng có người thế này, thế khác, nhưng thế này hay thế khác đều dòng dõi tổ tiên ta”?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90812, 'Thư gửi đồng bào Nam bộ, năm 1946.', true, 90204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90813, 'Thư gửi đồng bào toàn quốc, năm 1947.', false, 90204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90814, 'Thư gửi các đồng chí Bắc Bộ, năm 1947.', false, 90204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90815, 'Thư gửi các đồng chí Trung Bộ, năm 1947.', false, 90204);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90205, 'Chọn phương án đúng nhất đối với tư tưởng Hồ Chí Minh: Để tranh thủ sự giúp đỡ của các nước xã hội chủ nghĩa trong đấu tranh cách mạng, cần coi trọng nhân tố:', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90816, 'Tự lực cánh sinh, dựa vào sức mình là chính.', true, 90205);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90817, 'Có đường lối độc lập, tự chủ.', false, 90205);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90818, 'Có sự lãnh đạo đúng đắn của Đảng.', false, 90205);
