INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90835, 'Hợp tác thống nhất, bình đẳng giữa các giai cấp, tầng lớp.x', false, 90209);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90210, 'Hồ Chí Minh đã giương cao ngọn cờ nào khi đoàn kết giữa cách mạng Việt Nam với các lực lượng tiến bộ trên thế giới?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
