INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90839, 'Chủ nghĩa quốc tế vô sản.', false, 90210);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90211, 'Câu nói sau của Hồ Chí Minh là về nguyên tắc nào trong tư tưởng đoàn kết quốc tế: “Thực lực là cái chiêng mà ngoại giao là cái tiếng. Chiêng có to, tiếng mới lớn”?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90840, 'Thống nhất về mục tiêu và lợi ích.', false, 90211);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90841, 'Có lý, có tình.', false, 90211);
