INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90843, 'Tôn trọng chủ quyền, toàn vẹn lãnh thổ.', false, 90211);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90212, 'Theo Hồ Chí Minh, Mặt trận dân tộc thống nhất phải đặt dưới sự lãnh đạo của ai?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90844, 'Giai cấp công nhân.', false, 90212);
