INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90847, 'Đảng Cộng sản Việt Nam.', true, 90212);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90213, 'Theo Hồ Chí Minh, bản chất của các đoàn thể, tổ chức quần chúng nhân dân là:', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90848, 'Tổ chức của Đảng.', false, 90213);
