INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90850, 'Tổ chức của Dân.', true, 90213);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90851, 'Tổ chức của Quốc tế cộng sản.', false, 90213);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90214, 'Nền văn hóa mới mà chúng ta xây dựng theo tư tưởng Hồ Chí Minh bao gồm tính dân tộc, tính đại chúng và tính chất gì?', 'SINGLE_CHOICE', 90004, 9999, 'PRIVATE', 'MEDIUM');
