INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90249, 'Nhận định nào sau đây đúng theo tư tưởng Hồ Chí Minh?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90992, 'Văn hóa phải ở trong kinh tế và chính trị có nghĩa là văn hóa phải tham gia thực hiện những nhiệm vụ chính trị.', false, 90249);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90993, 'Văn hóa phải ở trong kinh tế và chính trị có nghĩa là văn hóa phải thúc đẩy xây dựng và phát triển kinh tế.', false, 90249);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90994, 'Văn hóa phải ở trong kinh tế và chính trị có nghĩa là văn hóa phải góp phần ổn định chính trị.', false, 90249);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90995, 'Văn hóa phải ở trong kinh tế và chính trị có nghĩa là văn hóa phải tham gia thực hiện những nhiệm vụ chính trị, thúc đẩy xây dựng và phát triển kinh tế.', true, 90249);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90250, 'Trong mối quan hệ giữa văn hóa với kinh tế, chính trị, xã hội, Hồ Chí Minh xác định:', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90996, 'Văn hóa ở trong kinh tế, chính trị, xã hội.', true, 90250);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90997, 'Văn hóa thuộc về kiến trúc thượng tầng.', false, 90250);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90998, 'Văn hóa là đời sống tinh thần xã hội.', false, 90250);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90999, 'Cả ba phương án kia đều đúng.', false, 90250);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90251, 'Trong tư tưởng Hồ Chí Minh về đạo đức, CẦN nghĩa là gì?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91000, 'Lao động cần cù, có kế hoạch.', false, 90251);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91001, 'Lao động có kế hoạch, có năng suất cao.', false, 90251);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91002, 'Lao động cần cù, có năng suất cao.', false, 90251);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91003, 'Lao động cần cù, siêng năng, có kế hoạch, có sự sáng tạo và có năng suất cao.', true, 90251);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90252, 'Trong tư tưởng Hồ Chí Minh về đạo đức, KIỆM nghĩa là gì?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91004, 'Tiết kiệm sức lao động, thời gian.', false, 90252);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91005, 'Tiết kiệm của cải.', false, 90252);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91006, 'Tiết kiệm thời gian và của cải.', false, 90252);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91007, 'Tiết kiệm công sức, thời gian và của cải.', true, 90252);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90253, 'Trong tư tưởng Hồ Chí Minh về đạo đức, CHÍNH được biểu hiện trong mối quan hệ nào?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91008, 'Bản thân, cấp trên.', false, 90253);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91009, 'Mọi người, công việc.', false, 90253);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91010, 'Cấp trên, cấp dưới, nhân dân.', false, 90253);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91011, 'Bản thân, mọi người, công việc.', true, 90253);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90254, 'Theo tư tưởng Hồ Chí Minh, “tinh thần quốc tế trong sáng” được hiểu như thế nào?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91012, 'Tinh thần đoàn kết quốc tế vô sản.', false, 90254);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91013, 'Tinh thần đoàn kết với các dân tộc bị áp bức, với nhân dân lao động các nước.', false, 90254);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91014, 'Tinh thần đoàn kết với các lực lượng tiến bộ trên thế giới.', false, 90254);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91015, 'Cả ba phương án kia đều đúng.', true, 90254);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90255, 'Điền vào chỗ trống trong câu sau của Hồ Chí Minh: “Hiểu chủ nghĩa Mác - Lênin là….. Nếu thuộc bao nhiêu sách mà sống không có tình có nghĩa thì sao gọi là hiểu chủ nghĩa Mác - Lênin được” ?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91016, 'Phải hiểu những nguyên lý.', false, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91017, 'Phải các cặp phạm trù, quy luật.', false, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91018, 'Phải sống với nhau có tình, có nghĩa.', true, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91019, 'Phải làm việc tốt.', false, 90255);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90256, 'Theo Hồ Chí Minh đạo đức cách mạng là một phạm trù lịch sử, nghĩa là nó cũng thay đổi theo nhiệm vụ từng thời kỳ của cách mạng, “đạo đức xã hội chủ nghĩa không phải ở đâu cũng biểu hiện giống nhau. Ở nước ta đạo đức xã hội chủ nghĩa là …..”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91020, 'Lao động xây dựng nước nhà.', false, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91021, 'Cần kiệm xây dựng nước nhà.', true, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91022, 'Bảo vệ tổ quốc xã hội chủ nghĩa.', false, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91023, 'Học tập, lao động, nghiên cứu khoa học.', false, 90256);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90257, 'Hồ Chí Minh yêu cầu Đảng phải “là đạo đức, là văn minh”; “Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, ….. ”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91024, 'Là người chỉ đường cho nhân dân.', false, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91025, 'Là người chỉ huy tài tình cho cách mạng.', false, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91026, 'Là người đầy tớ thật trung thành của nhân dân.', true, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91027, 'Là người dẫn dắt nhân dân đến thắng lợi cuối cùng.', false, 90257);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90258, 'Nhận định sau đây là của ai: “Chủ tịch Hồ Chí Minh, một biểu tượng xuất sắc về sự tự khẳng định dân tộc, đã cống hiến trọn đời mình cho sự nghiệp giải phóng dân tộc của nhân dân Việt Nam, góp phần vào cuộc đấu tranh chung của các dân tộc vì hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội”?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91028, 'M.I. Matsna (Apganixtan).', false, 90258);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91029, 'Tổng thống Xu-các-nô (Indonesia).', false, 90258);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91030, 'Oxíp Men-đen-xtam (Nga).', false, 90258);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91031, 'Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO).', true, 90258);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90259, 'Chọn phương án đúng điền vào chỗ trống trong câu sau của Hồ Chí Minh: “Người cách mạng phải có ….. thì mới gánh được nặng và đi được xa”?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91032, 'Trí tuệ.', false, 90259);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91033, 'Phương pháp cách mạng.', false, 90259);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91034, 'Đạo đức cách mạng.', true, 90259);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91035, 'Ý chí cách mạng.', false, 90259);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90260, 'Nhận định sau đây của Hồ Chí Minh trong bài viết/bài nói nào: “Một dân tộc dốt là một dân tộc yếu”?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91036, '“Những nhiệm vụ cấp bách của Nhà nước Việt Nam dân chủ cộng hòa” (3/9/1945).', false, 90260);
