INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91038, '“Thư gửi các học sinh” (9/1945).', true, 90260);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91039, '“Thư gửi Ủy ban nhân dân các kỳ, tỉnh, huyện và làng” (Báo Cứu quốc, số 69, ngày 17/10/1945).', false, 90260);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90261, 'Chọn phương án đúng điền vào chỗ trống trong câu sau của Hồ Chí Minh về vai trò của văn hóa: “Văn hóa ... cho quốc dân đi”.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91040, 'Chỉ đường.', false, 90261);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91041, 'Soi đường.', true, 90261);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91042, 'Mở đường.', false, 90261);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91043, 'Dẫn đường.', false, 90261);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90262, 'Nội dung xây dựng con người xã hội chủ nghĩa theo tư tưởng Hồ Chí Minh gồm:', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91044, 'Có ý thức làm chủ, tinh thần tập thể xã hội chủ nghĩa và tư tưởng “mình vì mọi người, mọi người vì mình”.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91045, 'Cần kiệm xây dựng đất nước, hăng hái bảo vệ Tổ quốc; Có lòng yêu nước nồng nàn, tinh thần quốc tế trong sáng.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91046, 'Có phương pháp làm việc khoa học, phong cách quần chúng, dân chủ, nêu gương.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91047, 'Cả ba phương án kia đều đúng.', true, 90262);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90263, 'Theo Hồ Chí Minh, tinh thần quốc tế trong sáng được hiểu là:', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91048, 'Tinh thần đoàn kết quốc tế vô sản.', false, 90263);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91049, 'Tinh thần đoàn kết với tất cả những người tiến bộ trên thế giới.', false, 90263);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91050, 'Tinh thần đoàn kết với các dân tộc bị áp bức.', false, 90263);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91051, 'Cả ba phương án kia đều đúng.', true, 90263);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90264, 'Luận điểm nào dưới đây được Hồ Chí Minh nói về chức năng của văn', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91052, 'Văn hóa phải nâng cao dân trí.', true, 90264);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91053, 'Văn hóa không thể đứng ngoài, mà phải ở trong kinh tế và chính trị.', false, 90264);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91054, 'Văn hóa là một kiến trúc thượng tầng.', false, 90264);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91055, 'Văn hóa phải gắn liền với lao động sản xuất.', false, 90264);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90265, 'Hồ Chí Minh đã chỉ rõ: Phải làm thế nào cho văn hóa thấm sâu vào tâm lý quốc dân, nghĩa là văn hóa phải sửa đổi được những tham nhũng, lười biếng, phù hoa, xa xỉ; văn hóa phải ….. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91056, 'Xây dựng tình cảm cao đẹp.', false, 90265);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91057, 'Bồi dưỡng tư tưởng đúng đắn.', false, 90265);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91058, 'Giáo dục lại tinh thần nhân dân.', false, 90265);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91059, 'Soi đường cho quốc dân đi.', true, 90265);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90266, 'Hồ Chí Minh coi trọng văn hóa, học vấn, trí tuệ. Người nói: “Muốn xây dựng chủ nghĩa xã hội thì nhất định phải có ….. Cần phải học văn hóa, chính trị, kỹ thuật”. “Người có học mới có tiến bộ, càng học càng tiến bộ”. Chọn phương án đúng điền vào chỗ trống.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91060, 'Học thức.', true, 90266);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91061, 'Giáo dục.', false, 90266);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91062, 'Khoa học.', false, 90266);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91063, 'Văn hóa.', false, 90266);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90267, 'Theo Hồ Chí Minh, trong xã hội có áp bức dân tộc và áp bức giai cấp thì tính nhân văn cao cả nhất là gì?', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91064, 'Giành độc lập cho dân tộc.', false, 90267);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91065, 'Xoá bỏ bóc lột giai cấp.', false, 90267);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91066, 'Giành độc lập cho dân tộc và xoá bỏ bóc lột giai cấp.', true, 90267);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91067, 'Đấu tranh cho hòa bình, thống nhất và độc lập dân tộc.', false, 90267);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (90268, 'Chọn phương án đúng vào chỗ trống trong câu sau của Hồ Chí Minh: “Người đi giáo dục ….. phải học thêm mãi, học không bao giờ đủ, còn sống còn phải học”.', 'SINGLE_CHOICE', 90005, 9999, 'PRIVATE', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91068, 'Phải yêu nghề.', false, 90268);
