INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91553, 'Cho lược đồ Cơ Sở Dữ liệu sau: NhanVien ( MaNV, HoNV, TenNV, DiaChi, ThanhPho ) KhachHang( MaKH, TenKH, DiaChi, ThanhPho, SoDu, GioiHanTinDung) HoaDon( MaHD, NgayLapHoaDon, MaKH, MaNV) ChiTietHoaDon (MaHD, MaSP, SoLuong,GiaBan ) SanPham(MaSP,MoTa, NhomHang, KhoHang,GiaGoc) Dựa vào lược đồ Cơ Sở Dữ liệu trên, Tạo câu truy vấn để liệt kê danh sách các sản phẩm có giá từ 50000 đến 100000?', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96201, 'Select * From SanPham Where GiaGoc>=50000', false, 91553);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96202, 'Select * From SanPham Where GiaGoc<=100000', false, 91553);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96203, 'Select * From SanPham Where GiaGoc between 50000 and 100000', true, 91553);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96204, 'Select * From SanPham Where GiaGoc in(50000,100000)', false, 91553);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91554, 'Cho lược đồ Cơ sở dữ liệu sau: SINHVIEN(MaSV, HoSV, TenSV, Phai, NgaySinh, DiaChi, DienThoai, MaLop) LOP(MaLop, TenLop, MaKhoa, GVCN) KETQUA(MaSV, MaMH, LanThi, Diem) MONHOC(MaMH, TenMH, SoTinChi) Liệt kê danh sách các sinh viên gồm (MaSV, HoSV, TenSV) có điểm thi môn CSDL cao nhất?', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96205, 'Select K.MaSV, HoSV, TenSV From SinhVien S, KetQua K Where S.MASV=K.MASV And MaMH=''CSDL'' And Diem>=ALL (Select Diem From KetQua where MaMH =''CSDL'')', false, 91554);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96206, 'Select K.MaSV, HoSV, TenSV From SinhVien S, ketqua K Where S.MASV=K.MASV And MaMH=''CSDL'' And Diem= (Select max(Diem)From ketqua where MaMH =''CSDL'')', false, 91554);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96207, 'Select top 1 with ties K.MaSV, HoSV, TenSV From SinhVien S, KetQua K Where S.MASV=K.MASV And MaMH=''CSDL'' order by diem desc', false, 91554);
