INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96213, 'Học Viên (Mã học viên, tên học viên, điạ chỉ, ngày sinh, số điện thoại, ngày nhập học, mã môn học) Môn học(Mã môn học, tên môn học, thời lượng) Khoá chính là Mã môn học Với: khoá chính cuả bảng học viên là Mã học viên và khoá chính cuả bảng môn học là Mã môn học.', false, 91556);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96214, 'Học Viên (Mã học viên, tên học viên, điạ chỉ, ngày sinh, số điện thoại, ngày nhập học,Mã môn học) Môn học(Mã môn học, tên môn học, thời lượng, Mã học viên) Với: khoá chính cuả bảng học viên là Mã học viên, Mã môn học và khoá chính của bảng môn học là Mã môn học, Mã học viên', false, 91556);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96215, 'Học Viên (Mã học viên, tên học viên, điạ chỉ, ngày sinh, số điện thoại) Môn học(Mã môn học, tên môn học, thời lượng) Học Viên Mon Hoc(Mã học viên, Mã môn học) Với: khoá chính cuả bảng "Học Viên" là Mã học viên Khoá chính cuả bảng "Môn học" là Mã môn học. Khoá chính cuả bảng "Học Viên Mon Hoc" là Mã học viên, Mã môn học.', true, 91556);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96216, 'Học Viên (Mã học viên, tên học viên, điạ chỉ, ngày sinh, số điện thoại) Môn học(Mã môn học, tên môn học, thời lượng, Mã học viên) Với: khoá chính cuả bảng học viên là Mã học viên và khoá chính cuả bảng môn học là Mã môn học.', false, 91556);
