INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91603, 'Cho các bảng sau: KhachHang (MaKH, TenKH, ThanhPho) SanPham(MaSP, TenSP, SoLuong, DonGia) DaiLy (MaDL, TenDL, ThanhPho, HueHong) DatHang (MaDH, NgayDH, MaKH, MaDL, MaSP, SoLuong, ThanhTien). Chọn câu lệnh SQL để giải quyết câu truy vấn sau: Tăng giá cuả mỗi sản phẩm trong bảng SanPham lên 10% cho tất cả các sản phẩm mà khách hàng ''C01'' đặt mua.', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
