INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91619, 'Cho lược đồ Cơ sở dữ liệu sau: SinhVien(MaSV, HoSV, TenSV, Phai, NgaySinh, DiaChi, DienThoai, MaLop) Lop(MaLop, TenLop, MaKhoa, GVCN) KetQua(MaSV, MaMH, LanThi, Diem) MonHoc(MaMH, TenMH, SoTinChi) Liệt kê danh sách các sinh viên có điểm điểm trung bình cao nhất. Danh sách gồm (MaSV, HoSV, TenSV,DiemTrungBinh)?', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96465, 'Select Top 1 K.MaSV, HoSV, TenSV,DiemTrungBinh=Avg(Diem) From SinhVien S, KetQua K Where S.MASV=K.MASV Group by K.MaSV, HoSV, TenSV', false, 91619);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96466, 'Select K.MaSV, HoSV, TenSV,DiemTrungBinh=Avg(Diem) From SinhVien S, KetQua K Where S.MASV=K.MASV And DiemTrungBinh>=ALL(Select Avg(Diem) From KetQua Group by MaSV )', false, 91619);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96467, 'Select K.MaSV, HoSV, TenSV,DiemTrungBinh=Avg(Diem) From SinhVien S, KetQua K Where S.MASV=K.MASV And DiemTrungBinh>=ALL(Select Avg(Diem) From KetQua Group by MaSV ) Group by K.MaSV, HoSV, TenSV', false, 91619);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (96468, 'Select K.MaSV, HoSV, TenSV,DiemTrungBinh=Avg(Diem) From SinhVien S, KetQua K Where S.MASV=K.MASV Group by K.MaSV, HoSV, TenSV Having avg(diem)>=ALL(Select Avg(Diem) From KetQua Group by MaSV )', true, 91619);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91620, 'Cho lược đồ Cơ sở dữ liệu sau: SinhVien(MaSV, HoSV, TenSV, Phai, NgaySinh, DiaChi, DienThoai, MaLop) Lop(MaLop, TenLop, MaKhoa, GVCN) KetQua(MaSV, MaMH, LanThi, Diem) MonHoc(MaMH, TenMH, SoTinChi) Tạo query để tính sỉ số thực trên từng lớp. Danh sách bao gồm: MaLop, TenLop và SiSo ?', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
