INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91621, 'Cho lược đồ Cơ sở dữ liệu sau: SinhVien(MaSV, HoSV, TenSV, Phai, NgaySinh, DiaChi, DienThoai, MaLop) Lop(MaLop, TenLop, MaKhoa, GVCN) KetQua(MaSV, MaMH, LanThi, Diem) MonHoc(MaMH, TenMH, SoTinChi) Liệt kê danh sách các sinh viên gồm (MaSV, HoSV, TenSV) đăng ký ít nhất là 3 môn học.', 'SINGLE_CHOICE', 90027, 9998, 'PUBLIC', 'MEDIUM');
