INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91973, '4 giám đốc dự án (PM) ngồi ăn trưa với nhau và thảo luận về dự án của họ. phần lớn thời gian họ phàn nàn về việc quản lys và điều hành dự án khó khăn như thế nào. Một số lời phàn nàn là về các cổ đông và các thay đổi mà họ tạo ra cho dự án. Người khác thì phàn nàn về sự khó khăn trong việc thúc đẩy nhân viên hợp tác và làm việc. 1 người PM muốn tập trung vào tất cả các lợi ích của ma trận tổ chức mà họ đều làm ra. Anh ta sẽ đề cập tới vấn đề nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97875, 'Cải thiện quyền quản lý và kiểm soát nguồn lực của PM', true, 91973);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97876, 'Có hơn một người tham gia quản lý dự án', false, 91973);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97877, 'Truyền thông dễ dàng hơn', false, 91973);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97878, 'Báo cáo dễ dàng hơn.', false, 91973);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91974, '2 PM vừa nhận ra họ đang ở trong một ma trận tổ chức yếu và quyền lực của họ trong vai trò là PM bị hạn chế. Một người nhận ra anh ta thật sự là người giải quyết công việc dự án (project expediter), người còn lại nhận ra rằng anh ta là điều phối viên của dự án (project coordinator). Vậy người tiến hành và điều phối viên của dự án khác nhau ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97879, 'Người giải quyết công việc dự án không thể đưa ra các quyết định', true, 91974);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97880, 'Người giải quyết công việc dự án có thể đưa ra nhiều quyết định hơn điều phối viên dự án', false, 91974);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97881, 'Người giải quyết công việc báo cáo cho quản lý cấp cao hơn', false, 91974);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97882, 'Người giải quyết công việc có một số thẩm quyền riêng', false, 91974);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91975, 'Trong một tổ chức hướng dự án (tổ chức trong đó k có các công việc thường nhật mà toàn là dự án), đội dự án có đặc điểm gì:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97883, 'Báo cáo cho một vài thủ trưởng', false, 91975);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97884, 'Không có sự trung thành đối với dự án', false, 91975);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97885, 'Báo cáo với người quản lý có trách nhiệm và thẩm quyền (functional manager)', false, 91975);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97886, 'Thường xuyên có mặt trong dự án, không có phòng ban chức năng (will not always have a home)', true, 91975);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91976, 'Một PM đang cố gắng hoàn thành dự án phát triển phần mềm, nhưng không thể tập trung và quan tâm nhiều tới dự án. Nguồn nhân lực được tập trng vào hoàn thành các công việc liên quan tới các tiến trình sản xuất phần mềm, và PM có ít thẩm quyền để phân công nguồn lực một cách hợp lý. Loại hình tổ chức nào mà người PM này đang làm việc?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97887, 'Tổ chức bao gồm các phòng ban chức năng.', true, 91976);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97888, 'Ma trận. đối với tổ chức loại này, thành viên đội dự án phải báo cáo với 2 thủ trưởng: 1 là PM và quản lý bộ phận chức năng.', false, 91976);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97889, 'Tổ chức mà PM là người giải quyết công việc', false, 91976);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97890, 'Tổ chức mà PM là người điều hành', false, 91976);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91977, 'Một PM có ít kinh nghiệm quản lý dự án. Nhưng anh ta được phân công làm PM cho một dự án mới. do anh ta sẽ làm việc trong một tổ chức ma trận (matrix organization) để hoàn thành dự án của mình, anh ta có thể trông đợi việc truyền thông trong dự án của mình có đặc điểm:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97891, 'Đơn giản', false, 91977);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97892, 'Truyền thông mở và thúc đẩy', false, 91977);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97893, 'Phức tạp', true, 91977);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97894, 'Khó tự động hóa', false, 91977);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91978, '2 nhân viên trong đội dự án đang nói chuyện với nhau và phàn nàn về việc rất nhiều người đang yêu cầu nhân viên đó phải làm một số việc. nếu anh ta làm việc trong một tổ chức bao gồm các phòng ban chức năng (functional organization), ai sẽ có quyền để đưa ra chỉ dẫn cho các thành viên dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97895, 'Người quản lý dự án PM', false, 91978);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97896, 'Người quản lý bộ phận chức năng functional manager', true, 91978);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97897, 'Đội dự án', false, 91978);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97898, 'Ma trận kiểm soát chặt tight matrix', false, 91978);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91979, 'Ai có nhiều thẩm quyền nhất trong một tổ chức hướng dự án (projectized organization)', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97899, 'Người quản lý dự án PM', true, 91979);
