INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97902, 'Đội dự án đều có quyền như nhau', false, 91979);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91980, 'Tính chất nào dưới đây không phải là tính chất của một dự án', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
