INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91981, 'Các bên liên quan quản lý dự án ngoại trừ việc:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97907, 'Đưa cho các bên liên quan một ít $ (giving stakeholders extras)', true, 91981);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97908, 'Xác định các bên liên quan', false, 91981);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97909, 'Xác định yêu cầu của các bên liên quan', false, 91981);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97910, 'Quản lý các mong đợi của các bên liên quan', false, 91981);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91982, 'Một người quản lý và giám đốc kĩ thuật thảo luận về một thay đổi trong gói công việc chính. Sau khi thảo luận, người quản lý liên lạc với bạn và yêu cầu bạn hoàn thành các thủ tục giấy tờ để thực hiện việc thay đổi đó. Đây là ví dụ về:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97911, 'Sự chú ý việc quản lý vào quản lý phạm vi', false, 91982);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97912, 'Lập kế hoạch quản lý', false, 91982);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97913, 'Trách nhiệm của người giải quyết công việc dự án', true, 91982);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97914, 'Một sự thay đổi hệ thống điều khiển.', false, 91982);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91983, 'Dự án đang trong quá trình lập kế hoạch nhóm. 3 bên có liên quan yêu cầu giám đốc dự án cung cấp một số thông tin về phương pháp quản lý dự án mới của công ty, phương pháp này lấy từ đâu và tại sao nó lại khác biệt với cách họ quản lý các dự án. 3 bên có liên quan đều là bạn của người quản lý dự án, toàn bộ nhóm dự án đều đã làm việc với nhau trong nhiều năm. Dự án sử dụng một vài điều khoản mới như “hành động hiệu chỉnh” (corective action), điều này làm cho một số bên có liên quan lo lắng, họ không chắc chắn nếu cách thức quản lý dự án sẽ thay đổi cùng với các điều khoản mới. người quản lý dự án nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97915, 'Đưa ra lời khuyên cho các bên có liên quan rằng PM sẽ giữ lại các điều khoản này trong truyền thông trong dự án.', false, 91983);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97916, 'Cung cấp một danh sách các điều khoản mới và định nghĩa của nó', false, 91983);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97917, 'Thông báo cho phòng quản lý dự án', true, 91983);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97918, 'Chắc chắn rằng PM sẽ duy trì thẩm quyền của mình như một người quản lý dự án, mặc dù PM và các bên có liên quan là bạn.', false, 91983);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91984, 'Một PM đang quản lý dự án thứ 2 của mình. Dự án đã bắt đầu được 1 tháng sau khi dự án thứ nhất bắt đầu. dự án đầu tiên của PM này là một dự án nhỏ, tuy nhiên đang mở rộng từng ngày. Mỗi ngày trôi qua, người PM này bắt đầu cảm thấy cần sự giúp đỡ. Gần đây, anh ta đã nghe có tin rằng năm ngoái cũng có một dự án gần giống với dự án thứ 2 của anh ta. Anh ta nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97919, 'Liên lạc với người PM của dự án kia và yêu cầu hỗ trợ', false, 91984);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97920, 'Sử dụng bản ghi và hướng dẫn từ phòng quản lý dự án', true, 91984);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97921, 'Chờ đợi xem nếu dự án bị ảnh hưởng bởi sự mở rộng phạm vi dự án', false, 91984);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97922, 'Chắc chắn rằng phạm vi dự án phải được các bên có liên quan đồng ý và phê duyệt', false, 91984);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91985, 'Dự án đang tiến hành tốt, ngoại trừ số lượng các thay đổi đã được tạo ra. Dự án được thực hiện và chia ra 7 ban khác nhau trong công ty và sẽ cải thiện đáng kể hiệu năng của các phòng ban này khi nó được thực hiện. có 14 quy trình quản lý dự án được lựa chọn để sử dụng trong dự án này. PM là một chuyên gia kĩ thuật và được training về truyền thông và quản lý nhân lực. điều nào dưới đây là nguyên nhân của vấn đề của dự án (số lượng các thay đổi)?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97923, 'PM không được huấn luyện để hiểu rõ môi trường công ty', false, 91985);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97924, 'Dự án nên được giám sát quản lý nhiều hơn để có kết quả tốt và đem lại lợi nhuận cho công ty', false, 91985);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97925, 'Dự án nên sử dụng thêm nhiều tiến trình quản lý dự án hơn', false, 91985);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97926, 'Một vài bên liên quan chưa được xác định', true, 91985);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91986, 'Vòng đời dự án và vòng đời sản phẩm khác nhau. Trong vòng đời dự án có đặc điểm gì khác khi so sánh với vòng đời sản phẩm?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97927, 'Không kết hợp phương pháp luận', false, 91986);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97928, 'Là khác biệt trong từng ngành sản xuất khác nhau', true, 91986);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97929, 'Có thể sinh ra nhiều dự án khác nhau', false, 91986);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97930, 'Miêu tả các hành động quản lý dự án', false, 91986);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91987, 'Các bên có liên quan có thể được xác định trong quy trình nào của việc quản lý dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97931, 'Khởi tạo, lên kế hoạch, thực thi, kiểm soát và kết thúc dự án', true, 91987);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97932, 'Khởi tạo và lên kế hoạch', false, 91987);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97933, 'Lên kế hoạch và kiểm soát', false, 91987);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97934, 'Kiểm soát và kết thúc', false, 91987);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91988, 'Trong quản lý dự án, ta chỉ quản lý bởi mục tiêu làm việc khi nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97935, 'Được hỗ trợ quản lý (it''s supported by management)', true, 91988);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97936, 'Các luật được viết ra', false, 91988);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97937, 'Dự án không ảnh hưởng tới mục tiêu chung', false, 91988);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97938, 'Dự án bao gồm mục tiêu dự án trong tôn chỉ dự án', false, 91988);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91989, 'Người quản lý của bạn quyết định rằng tất cả các đơn hàng (orders) đều được coi như trong dự án (treated as "project") và người PM sẽ cập nhật các đơn hàng này hàng ngày, giải quyết các vấn đề và chắc chắn rằng khách hàng chính thức chấp nhận sản phẩm trong vòng 30 ngày. Doanh thu từ 1 đơn hàng riêng lẻ có thể dao động từ 100$ tới 150000$. PM không yêu cần phải lập kế hoạch và chỉ cần cung cấp trạng thái đơn hàng hàng ngày. Bạn xác định tình huống này như thế nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97939, 'Do mỗi đơn hàng là một sự cố gắng tạm thời nên mỗi đơn hàng đều là một dự án', false, 91989);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97940, 'Đây là việc quản lý chương trình cho đến khi có nhiều dự án kéo theo', false, 91989);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97941, 'Đây là công việc định kỳ (recurring process)', true, 91989);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97942, 'Doanh thu của các đơn hàng trên 100000$ sẽ được coi như một dự án và sẽ kéo theo các hoạt động quản lý dự án', false, 91989);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91990, 'Trong giai đoạn (quy trình - process) nào của vòng đời dự án mà tài liệu ngân sách chi tiết được viết ra?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
