INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97946, 'Thực thi', false, 91990);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91991, 'Tôn chỉ dự án được viết ra trong giai đoạn nào của vòng đời dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97947, 'Thực thi', false, 91991);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97948, 'Lập kế hoạch', false, 91991);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97949, 'Kết thúc', false, 91991);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97950, 'Khởi tạo', true, 91991);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91992, 'Đội dự án vừa hoàn thành lịch khởi tạo dự án (initial project schedule) và ngân sách dự án. Việc phải làm tiếp theo là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97951, 'Bắt đầu xác định rủi ro', false, 91992);
