INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97953, 'Xác định các yêu cầu truyền thông', true, 91992);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97954, 'Làm sơ đồ Gantt', false, 91992);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91993, 'Lịch làm việc chi tiết của dự án có thể được tạo ra sau khi đã có:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
