INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97958, 'Bảng đánh giá rủi ro chi tiết', false, 91993);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91994, 'Người nên được kiểm soát dự án trong quá trình lập kế hoạch dự án là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97959, 'Người quản lý dự án PM', true, 91994);
