INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91995, 'Trong giai đoạn khởi tạo dự án, văn bản nào dưới đây KHÔNG cần thiết:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97963, 'Các quy trình của công ty', false, 91995);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97964, 'Văn hóa của công ty', false, 91995);
