INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97966, 'Tuyên bố phạm vi dự án', true, 91995);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91996, 'Nhà tài trợ dự án vừa cung cấp bản tuyên bố phạm vi dự án sơ bộ. việc phải làm tiếp theo là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97967, 'Bắt đầu hoàn thành gói công việc', false, 91996);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97968, 'Hoàn thành phê chuẩn phạm vi dự án', false, 91996);
