INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97970, 'Bắt đầu tạo ra các kế hoạch quản lý', true, 91996);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91997, 'Các ràng buộc về lịch trình dự án mức cao được xác định trong giai đoạn nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97971, 'Khởi tạo', true, 91997);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97972, 'Lập kế hoạch', false, 91997);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97973, 'Thực thi', false, 91997);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97974, 'Kiểm soát', false, 91997);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91998, 'Bảng phân rã công việc WBS và từ điển WBS đều được hoàn thành. Đội dự án bắt đầu xác định các rủi ro. Nhà tài trợ liên lạc với PM để yêu cầu làm ma trận trách nhiệm. dự án có ngân sách là 100000$ với 14 nhân lực đến từ 3 quốc gia. Dự án có một rủi ro nhỏ và PM đã quản lý rất nhiều dự án giống dự án này. Việc phải làm tiếp theo là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97975, 'Hiểu rõ kinh nghiệm của nhà tài trợ trong các dự án trước', false, 91998);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97976, 'Tạo ra danh sách hoạt động (activity list)', true, 91998);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97977, 'Chắc chắn rằng phạm vi dự án đã được xác định', false, 91998);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97978, 'Hoàn thành quản lý rủi ro và ma trận trách nhiệm', false, 91998);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (91999, 'Một PM không có nhiều thời gian để lên kế hoạch trước khi ngày bắt buộc khởi động dự án đang tới. Do đó anh ta muốn lập kế hoạch hiệu quả nhất có thể. Anh ta nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97979, 'Chắc chắn nên có tuyên bố phạm vi dự án sơ bộ đã hoàn thành và sau đó tiến hành làm WBS', false, 91999);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97980, 'Tạo danh sách hoạt động trước khi tạo ra sơ đồ mạng', true, 91999);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97981, 'Có tài liệu về các rủi ro đã biết trước khi làm các giả thuyết và ước tính sâu hơn', false, 91999);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97982, 'Hoàn thiện kế hoạch quản lý chất lượng trước khi quyết định đơn vị đo chất lượng', false, 91999);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92000, 'PM chắc chắn rằng sản phẩm của dự án phải hoàn thiện theo kế hoạch quản lý dự án. Anh ta đang ở giai đoạn nào của dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97983, 'Lên kế hoạch', false, 92000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97984, 'Thực thu', false, 92000);
