INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97994, 'Kết thúc dự án', false, 92002);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92003, 'Trong buổi họp đội dự án, một nhân viên dự án hỏi về đơn vị đo đạc nào được sử dụng trong dự án để kiểm soát hiệu năng. nhân viên này cảm thấy một vài thước đo có liên quan tới công việc của anh ta đang không chính xác. Dự án được xem xét tốt nhất trong phần nào của giai đoạn phát triển dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
