INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97998, 'Khởi tạo', false, 92003);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92004, 'Trong khi hoàn thành gói công việc, nhà tài trợ yêu cầu PM báo cáo dự án đang được diễn tiến ntn. Trong quá trình chuẩn bị báo cáo, PM yêu cầu tất cả nhân viên dự án họ đã làm được bao nhiêu % công việc của mình. Có một nhân viên rất khó khăn trong việc quản lý từ đầu. khi trả lời câu hỏi của PM, anh ta nói rằng chưa hoàn thành gì cả. Mệt mỏi vì được trả lời như vậy, PM báo cáo với thủ trưởng của đội dự án là các nhân viên không có tinh thần hợp tác. Vấn đề thật sự ở đây là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (97999, 'PM không có đủ nguồn lực cho dự án', false, 92004);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98000, 'PM không tạo ra hệ thống tưởng thưởng xứng đáng cho nhân viên để nâng cao tinh thần hợp tác của họ', false, 92004);
