INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92022, 'Tôn chỉ dự án cho một dự án của được phê chuẩn để lê kế hoạch và bạn vừa được phân công là PM. Nhận ra rằng lên kế hoạch dự án là nỗ lực xuyên suốt dự án, việc nào sau đây bạn nên kết hợp nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98071, 'Tạo bảng WBS và định nghĩa hành động', true, 92022);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98072, 'Ước tính thời gian hành động và xây dựng lịch làm việc', false, 92022);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98073, 'Lên kế hoạch nhân sự và ước tính chi phí', false, 92022);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98074, 'Ước tính chi phí và tính toán ngân sách', false, 92022);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92023, 'Tất cả các điều dưới đây đều là một phần của quản lý và thực thi quản lý dự án, ngoại trừ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98075, 'Xác định các thay đổi', false, 92023);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98076, 'Sử dụng bảng WBS', false, 92023);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98077, 'Thực hiện các hành động hiệu chỉnh', false, 92023);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98078, 'Xây dựng một hệ thống kiểm soát dự án.', true, 92023);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92024, 'Một PM được trang bị để lãnh đạo một dự án kỹ thuật cao trong khu vực với những người ít thông thạo về lĩnh vực này. PM ủy quyền xây dựng lịch làm việc, ước tính chi phí, lựa chọn hành động và phân công hành động cho nhiều thành viên trong đội dự án, và chỉ làm việc như người xem xét và điều phối các hoạt động của dự án. Kết quả của cách tiếp cận này giống như:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98079, 'Một đội chức năng suốt toàn bộ dự án ở mức độ cao, là điển hình của sự sáng tạo và trách nhiệm', false, 92024);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98080, 'Một đội hỗn loạn lúc ban đầu, nhưng sau đó sẽ trở nên gắn kết và làm việc hiệu quả', false, 92024);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98081, 'Một đội không thực sự có hiệu quả, nhưng luôn làm việc cùng nhau do môi trường làm việc mà PM đem lại', false, 92024);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98082, 'Một đội có hiệu năng thấp, nhuệ khí thấp, dễ xung đột và tốc độ thay thế nhân viên cao', true, 92024);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92025, 'Bạn đang trong quá trình thực hiện các thay đổi quan trọng cho một sản phẩm đã có, khi bạn biết rằng nguồn lực đã hứa vào lúc khởi động dự án hiện tại đang không có thì điều tốt nhất bạn nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98083, '. Chỉ ra làm thế nào mà các nguồn lực đã được cam kết cho dự án của bạn lúc ban đầu', false, 92025);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98084, 'Lập lại kế hoạch dự án mà không có các nguồn lực đó', false, 92025);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98085, 'Giải thích, trình bày ảnh hưởng nếu nguồn nhân lực đã cam kết không có.', true, 92025);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98086, 'Phá dự án, k làm nữa', false, 92025);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92026, 'Bạn được phân công để quản lý việc phát triển của website đầu tiên của một tổ chức. website này sẽ rất phức tạp và có tính tương tác cao, và đội dự án của bạn cũng như khách hàng chưa có kinh nghiệm gì trong việc phát triển website. Thời hạn bàn giao sản phẩm rất gấp gáp. Bất kỳ một sự chậm trễ nào sẽ tiêu tốn tiền của công ty bạn cũng như khách hàng. Bạn có một nhà tài trợ dự án và có bản hợp đồng bàn giao, tôn chỉ dự án và kế hoạch quản lý dự án đều đã có chữ ký. Bên phía khách hàng đã giữ lại đầy đủ các thông báo của quá trình thực hiện dự án thông qua báo cáo trạng thái và biên bản họp. dự án đang trong đúng lịch trình, trong ngân sách và việc xem xét lại cuối cùng (chỉ mang tính hình thức) cũng đã được lên lịch. Đột nhiên, bạn nghe rằng toàn bộ nỗ lực có thể bị hủy bởi vì sản phẩm đang phát triển là hoàn toàn không được chấp nhận. điều gì là nguyên nhân của vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98087, 'Một bên có liên quan không được liên quan thỏa đáng trong dự án (not adequately involved)', true, 92026);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98088, 'Tôn chỉ dự án và kế hoạch dự án không được giải thích kỹ lưỡng hoặc không được xem xét lại một cách đầy đủ từ phía khách hàng', false, 92026);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98089, 'Hợp đồng truyền thông không đầy đủ và không cung cấp các thông tin yêu cầu cho các bên có liên quan', false, 92026);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98090, 'Nhà tài trợ dự án không cung cấp đầy đủ cho dự án', false, 92026);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92027, 'PM nhận được 1 thay đổi từ khách hàng và thay đổi này không ảnh hưởng tới lịch hoạt động của dự án và dễ dàng để hoàn thành. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98091, 'Thực hiện thay đổi càng sớm càng tốt', false, 92027);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98092, 'Liên lạc với nhà tài trợ để được sự cho phép', false, 92027);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98093, 'Liên lạc với ban kiểm soát thay đổi', false, 92027);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98094, 'Ước tính các thành phần khác trong tam giác ràng buộc.', true, 92027);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92028, 'Công ty của bạn vừa trúng thầu một dự án lớn. dự án sẽ bắt đầu trong vòng 3 tháng và có trị giá 2000000$. Bạn đang là PM của một dự án đã có. Điều đầu tiên bạn nên làm là gì sau khi nghe tin về dự án mới?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98095, 'Hỏi ban điều hành công ty về nguồn nhân lực mà dự án mới sẽ sử dụng', false, 92028);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98096, 'Nâng mức nguồn lực cho dự án của bạn', false, 92028);
