INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92029, 'Bạn là PM vừa được phân công để kiểm soát một dự án (người PM cũ của dự án này vừa rời khỏi công ty). Người PM cũ nói với bạn rằng dự án đang trong đúng lịch trình, nhưng chỉ khi anh ta thúc giục liên tục các nhân viên làm việc. điều đầu tiên bạn sẽ làm trong cương vị 1 PM mới là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98099, 'Kiểm tra trạng thái rủi ro', false, 92029);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98100, 'Kiểm tra chi phí hiệu năng', false, 92029);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98101, 'Xác định chiến lược quản lý', true, 92029);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98102, 'Nói với đội dự án về mục tiêu của bạn', false, 92029);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92030, 'Bạn được phân công làm PM của một dự án đang được thực hiện. dự án vẫn đang thực hiện trong ranh giới các ràng buộc, tuy nhiên khách hàng k hài lòng với hiệu năng của dự án. Điều đầu tiên bạn nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98103, 'Thảo luận vấn đề khách hàng đưa ra với đội dự án', false, 92030);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98104, 'Tính toán lại các ràng buộc (baseline)', false, 92030);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98105, 'Thương lượng lại hợp đồng', false, 92030);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98106, 'Gặp khách hàng để trao đổi', true, 92030);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92031, 'Một PM biết được rằng các hành động hiệu chỉnh vừa được 1 nhân viên dự án thực hiện, nhưng chưa được ghi lại. người PM này nên làm gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98107, 'Báo cáo vi phạm với giám đốc chức năng', false, 92031);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98108, 'Làm sáng tỏ lý do đằng sau hành động của nhân viên đó', false, 92031);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98109, 'Thêm hành động hiệu chỉnh này vào bản ghi (historical record)', true, 92031);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98110, 'Tìm xem ai đã gây ra vấn đề này (ai đã thực hiện hiệu chỉnh)', false, 92031);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92032, 'Yêu cầu của khách hàng thay đổi thông số của sản phẩm sẽ làm thời gian thực hiện dự án tăng thêm 2 tuần. người PM nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98111, 'Dồn lịch thực hiện để hoàn thành đúng thời hạn (recover the 2 weeks)', false, 92032);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98112, 'Cắt giảm phạm vi để hoàn thành đúng hạn, bù lại 2 tuần thêm vào', false, 92032);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98113, 'Tham khảo ý kiến nhà tài trợ trước khi có bất kỳ hành động nào', true, 92032);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98114, 'Hỏi ý kiến (or khuyên bảo - advise) khách hàng về ảnh hưởng của sự thay đổi', false, 92032);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92033, 'Trong quá trình thực thi dự án, PM xác định có một thay đổi về nguyên vật liệu cho dự án là cần thiết. PM triệu tập 1 cuộc họp để lên kế hoạch thực hiện thay đổi này. Đây là một ví dụ về:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98115, 'Quản lý bằng mục tiêu', false, 92033);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98116, 'Sự thiếu hụt hệ thống kiểm soát thay đổi', true, 92033);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98117, 'Quan hệ giữa các thành viên dự án được đánh giá tốt', false, 92033);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98118, 'Sự thiếu hụt một bảng WBS rõ ràng', false, 92033);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92034, 'Dự án đang phát triển tốt khi tất cả các thay đổi bất ngờ từ các bên có liên quan. Sau khi các thay đổi đã được xác định, PM dành thời gian với tất cả các bên có liên quan để tìm ra tại sao lại có thay đổi và xem xét có thêm thay đổi nữa hay không. Công việc dự án tạm lắng xuống khi một nhân viên tình cờ đề cập với PM rằng anh ta đã thêm chức năng vào sản phẩm của dự án mà không làm ảnh hưởng tới thời gian, chi phí hay chất lượng của dự án. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98119, 'Hỏi nhân viên đó làm thế nào để xác định sự cần thiết của chức năng này', false, 92034);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98120, 'Tổ chức họp để xem xét lại công việc đã hoàn thành của nhân viên này', false, 92034);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98121, 'Tìm kiếm các chức năng thêm vào khác', false, 92034);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98122, 'Hỏi nhân viên đó làm thế nào anh ta biết được rằng không ảnh hưởng tới thời gian, chi phí hay chất lượng của dự án', true, 92034);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92035, 'Một PM đang quản lý một hợp đồng có giá sẵn (fixed price contract). Cô ấy nghĩ rằng một thay đổi lớn từ yêu cầu của khách hàng sẽ ảnh hưởng tới lịch trình dự án. Cô ấy nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98123, 'Gặp các bên có liên quan', false, 92035);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98124, 'Gặp đội dự án', false, 92035);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98125, 'Thương lượng lại về phần còn lại của hợp đồng', false, 92035);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98126, 'Theo sau hệ thống kiểm soát thay đổi', true, 92035);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92036, 'Trong khi hoàn thành một dự án, một PM nhận ra rằng anh ta cần giảm bớt chi phí dự án. Sau khi nghiên cứu các lựa chọn của mình, anh ta thực hiện thay đổi dưới đây. Lựa chọn nào sẽ làm giảm chi phí dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98127, 'Thay đổi thành phần A từ thành phần B. thành phần A có chi phí cao hơn nhưng có vòng đời chi phí ít hơn B', false, 92036);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98128, 'Thay đổi nguồn lực C thành nguồn lực B để hoàn thành hành động A. nguồn lực B có nhiều nhân viên có kinh nghiệm hơn', false, 92036);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98129, 'Di chuyển hành động B và H để thực hiện cùng lúc, và chấp nhận tăng 30% rủi ro mà 5 nguồn lực cần thiết sẽ được thêm vào sau đó', false, 92036);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98130, 'Bỏ một kiểm tra từ kế hoạch quản lý dự án', true, 92036);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92037, 'Dự án này được tuyên bố (chartered?) để xác định cách thức mới để mở rộng vòng đời sản phẩm của một sản phẩm của công ty bậc trung. Người PM tới từ một ban kỹ thuật và đội dự án là từ ban sản phẩm và ban tiếp thị. Tuyên bố phạm vi dự án sơ bộ và kế hoạch dự án đã hoàn thành khi một bên có liên quan thông báo với đội dự án là: có một cách tốt hơn để hoàn thành một gói công việc. họ cung cấp văn bản xem xét kỹ thuật từ ban của họ, văn bản này chứng minh cách thức mới để hoàn thành công việc sẽ thực sự nhanh hơn cách thức cũ. PM đã từng có kinh nghiệm tương tự với phòng ban này trong dự án khác, và hi vọng là sẽ xảy ra trong dự án này. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
