INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92059, 'Dự án đã gần như hoàn thành. Dự án có biến động về lịch trong là 300 và biến động chi phí là -900. Tất cả đã được hoàn thành và đáp ứng yêu cầu chất lượng ngoại trừ việc giám định kiểm soát chất lượng. Tất cả các mục trong nhật ký vấn đề (issue log) đều được giải quyết. Khá nhiều nguồn lực đã được giải phóng. Nhà tài trợ tổ chức một buổi gặp mặt để xác minh sản phẩm khi khách hàng thông báo với PM rằng họ muốn một thay đổi chính đối với phạm vi dự án. PM nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
