INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92060, 'Bạn vừa tham gia vào phòng quản lý dự án sau 5 năm làm việc trong dự án. Một trong những điều bạn muốn giới thiệu với công ty là sự cần thiết của bảng WBS. Một vài PM đã tức giận do bạn đang đòi hỏi họ phải làm thêm việc. Điều nào dưới đây là tốt nhất khi bạn muốn thuyết phục họ sử dụng WBS?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98223, 'Nói với học rằng WBS sẽ ngăn chặn các công việc từ không tốt tới tốt (from slipping to the crack)', true, 92060);
