INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92061, 'Một PM mới vừa xin bạn lời khuyên để tạo ra bảng WBS. Sau khi bạn giải thích quy trình cho anh ta, anh ta hỏi bạn rằng nên sử dụng phần mềm nào để lập bảng WBS và anh ta nên làm gì với nó khi anh ta hoàn thành. Bạn sẽ trả lời rằng bức hình (picture) không phải là kế quả giá trị nhất của việc tạo bảng WBS, đó là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
