INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92092, 'Trong khi lên kế hoạch dự án, bạn ước tính thời gian cần thiết cho mỗi hoạt động và thêm ước tính để tạo ra ước lượng dự án. Bạn cam kết hoàn thành dự án đúng hạn. Trong tình huống này, điều gì Sai?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
