INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92094, 'Bạn là 1 PM ở Mỹ, phát triển dự án phần mềm 5,000,000$. Trong khi làm việc với đội dự án để xây dựng sơ đồ mạng, bạn chú ý một chuỗi các hoạt động có thể được thực hiện song song nhưng phải hoàn thành trong một thứ tụ riêng biệt. Loại hoạt động nào của phương pháp sắp xếp thứ tự hoạt động được yêu cầu cho những hoạt động này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
