INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92097, '. Bạn có một dự án với các hoạt động sau: hoạt động A kéo dài 40 giờ và có thể bắt đầu sau khi bắt đầu dự án. Hoạt động B kéo dài 25 giờ và nên bắt đầu sau khi bắt đầu dự án. Hoạt động C phải bắt đầu sau khi hoạt động A và kéo dài trong 35 giờ. Hoạt động D phải bắt đầu sau hoạt động B và C và kéo dài 30 giờ. Hoạt động E phải bắt đầu sau hoạt động C và kéo dài 10 giờ. Hoạt động F và D là các hoạt động cuối cùng của dự án. Điều nào dưới đây là đúng nếu hoạt động B thực sự kéo dài trong 37 giờ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98371, 'Đường tới hạn là 67 giờ', false, 92097);
