INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92106, 'Dự án được tính toán để hoàn thành 4 ngày sau ngày hoàn thành mong đợi (desired completion date). Bạn không có nguồn lực nào khác. Dự án có rủi ro thấp, tỷ lệ chi phí có lợi (benefit cost ratio) được mong đợi là 1.6 và các phụ thuộc được ưu tiên. Trong tình huống này, điều tốt nhất nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
