INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92135, 'Là một PM, bạn được giới thiệu các thông tin sau về giá trị thực NPV của một vài dự án. Bạn sẽ lựa chọn dự án nào trong số các dự án dưới đây?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
