INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92136, 'Công ty của bạn có thể chấp nhận 1 trong 3 dự án sau: dự án A có NPV là 30000$ và cần 6 năm để hoàn thành, dự án B có NPV là 60000$ và cần 3 năm để hoàn thành, dự án C có NPV là 90000$ và cần 4 năm để hoàn thành. Dựa vào các thông tin trên, bạn sẽ chọn dự án nào để thực hiện?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
