INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92137, 'Người bán nói với bạn rằng các hoạt động của bạn gây ra việc tăng chi phí của họ. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
