INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98538, 'Giảm phạm vi', false, 92138);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92139, 'Một dự án phát triển cửa hàng mới yêu cầu việc mua bán của nhiều thiết bị, máy móc và đồ đạc. Phòng ban có trách nhiệm cho việc phát triển vừa tập trung quy trình mua bán bên ngoài và tiêu chuẩn hóa hệ thống đặt hàng mới. Những thủ tục trên có trong tài liệu nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
