INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98541, 'Kế hoạch quản lý nhân lực', false, 92139);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98542, 'Chính sách của tổ chức', true, 92139);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92140, 'Vào giai đoạn đầu của dự án, bạn có buổi thảo luận với nhà tài trợ về các kỹ thuật ước lượng nên được sử dụng. Bạn muốn có đánh giá của chuyên gia, nhưng nhà tài trợ phản đối và muốn dùng ước tính tương tự. Tốt nhất nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98543, 'Đồng ý với ước tính tương tự như một đánh giá của chuyên gia', true, 92140);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98544, 'Đề nghị đánh giá vòng đời như một thỏa hiệp', false, 92140);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98545, 'Xác định tại sao nhà tài trợ muốn một ước tính chính xác như thế', false, 92140);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98546, 'Cố gắng thuyết phục nhà tài trợ đồng { các đánh giá của chuyên gia do nó chính xác hơn', false, 92140);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92141, 'Bạn vừa hoàn thành giai đoạn khởi tạo của một dự án nhỏ và đang bước sang giai đoạn lên kế hoạch khi một bên có liên quan tới dự án hỏi bạn về ngân sách dự án và đường chuẩn chi phí (cost baseline). Bạn nên nói gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98547, 'Ngân sách dự án có thể được tìm thấy trong tôn chỉ dự án mới vừa hoàn thành', false, 92141);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98548, 'Ngân sách dự án và đường chuẩn sẽ không được kết thúc và được chấp nhận cho đến khi giai đoạn lên kế hoạch hoàn tất', true, 92141);
