INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98550, 'Có thể hoàn thành một ước tính trước khi kế hoạch quản lý dự án được tạo ra', false, 92141);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92142, 'PM được chỉ định ước tính chi phí chung để chia nhỏ các hoạt động để thiết lập một đường chuẩn cho việc đo đạc hiệu năng dự án. Đây là quy trình gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
