INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98554, 'Kiểm soát chi phí', false, 92142);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92143, 'Bạn được hỏi để chuẩn bị ngân sách để hoàn thành một dự án. Dự án này vừa bắt đầu năm ngoái và bị hoãn trong 6 tháng. Điều nào dưới đây không có trong ngân sách?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
