INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98556, 'Chi phí ngầm', true, 92143);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98557, 'Chi phí trực tiếp', false, 92143);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98558, 'Chi phí biến động (VC - variable costs)', false, 92143);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92144, 'Để cung cấp một dự án mới cho phòng ban của mình, bạn cần di chuyển tài nguyên từ một dự án sang một dự án khác. Do phòng ban của bạn đang làm việc hết công suất, di chuyển tài nguyên sẽ chăncs chắn trì hoãn dự án mà bạn chuyển tài nguyên. Điều này làm ảnh hưởng tiêu cực ít nhất đến dự án nào dưới đây ếu bạn di chuyển tài nguyên từ dự án này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98559, 'Dự án A với tỷ lệ chi phí lợi ích là 0.8, không có tôn chỉ dự án, có 4 nguồn lực', true, 92144);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98560, '. Dự án B với NPV là 60000$, 12 nguồn lực, và chi phí biến động giữa 1000$ tới 2000$ một tháng', false, 92144);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98561, 'Dự án C với chi phí cơ hội là 300000$, không có hệ thống kiểm soát dự án, tỷ suất hoàn vốn nội bộ IRR là 12%', false, 92144);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98562, 'Dự án D với chi phí gián tiếp là 20000$ và 13 nguồn lực', false, 92144);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92145, 'Một dự án sản xuất có chỉ số thực hiện lịch trình SPI là 0.89 và chỉ số thực hiện chi phí CPI là 0.91. Thông thường, giải thích nào tốt nhất cho tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98563, 'Phạm vi dự án đã thay đổi', false, 92145);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98564, 'Một nhà cung cấp không kinh doanh nữa và một nhà cung cấp khác cần được tìm thấy', false, 92145);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98565, 'Các thiết bị thêm vào cần thiết phải mua', false, 92145);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98566, 'Hoạt động đường giới hạn thực hiện lâu hơn và cần nhiều giờ lao động để hoàn thành', true, 92145);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92146, 'Mặc dù các bên có liên quan nghĩ rằng có đủ tiền trong ngân sách, dự án thực hiện được 1 nửa và CPI là 0.7. Để xác định nguyên nhân cốt lõi, các bên có liên quan kiểm tra dự án và phát hiện ra ngân sách chi phí dự án đã bị ước tính một cách tương tự. mặc dù các ước tính hoạt động thêm vào ước tính dự án, các bên có liên quan nghĩ rằng có gì đó bị bỏ sót trong khi hoàn thành ước tính. Điều bị bỏ sót ấy là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98567, 'Chi phí ước tính được nên được sử dụng để đo CPI', false, 92146);
