INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98569, 'Ước tính từ dưới lên nên được sử dụng', true, 92146);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98570, 'Thông tin lịch sử không được tính đến', false, 92146);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92147, 'Bạn là một PM của công ty tư vấn lớn. cấp trên của bạn vừa hỏi ý kiến của bạn trong một quyết định về dự án nào công ty nên theo đuổi. Dự án A có tỷ suất hoàn vốn nội bộ IRR là 12%. Dự án B được dự đoán có tỷ lệ chi phí lợi ích BCR là 1.3. Dự án C có chi phí cơ hội là 75000$. Dự án D có thời gian thu hồi vốn là 6 tháng. Bạn sẽ chọn dự án nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98571, 'Dự án A', true, 92147);
