INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98574, 'Dự án D', false, 92147);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92148, 'You are about to take over a project from another project manager and find out the following information about the project. Activity Z has an early start ES of day 15 and a late start LS of day 20. Activity Z is a difficult activity. Cost performance index CPI is 1.1. Schedule performance index SPI is 0.8. There are 11 stakeholders on the project. Based on this information, which of the following would you be the Most concerned about?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98575, 'Schedule', true, 92148);
