INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92150, 'Bạn cung cấp ước tính chi phí dự án cho nhà tài trợ dự án. Anh ta không hài lòng với ước tính, do anh ta nghĩ rằng giá có thể thấp hơn. Anh ta bảo bạn cắt giảm 15% ước tính dự án. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
