INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92155, 'Một người quản lý chú ý tới một PM đang tổ chức họp với một vài nhân viên đội dự án và một vài bên có liên quan tới dự án để thảo luận chất lượng dự án. Lịch trình dự án sẽ được nén lại và CPI là 1.1. Họ đã làm việc chăm chỉ trong dự án, đội dự án được thưởng theo hệ thống thưởng của PM và đây là một đội vững chắc. người quản lý đưa ra giả thuyết là PM không có đủ thời gian để tổ chức họp về chất lượng khi lịch trình không được nén. Điều nào dưới đây mô tả đúng nhất về việc người quản lý này đã sai?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
