INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92169, 'Trong khi lập kế hoạch dự án, điều nào thông thường sẽ có ưu tiên nhất, chất lượng, chi phí hay lịch trình?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98659, 'A. Chi phí là quan trọng nhất, sau đó là chất lượng, cuối cùng là lịch trình', false, 92169);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98660, 'B. Chất lượng là quan trọng hơn lịch trình và chi phí', false, 92169);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98661, 'C. Lịch trình là quan trọng nhất, sau đó là chất lượng, cuối cùng là chi phí', false, 92169);
