INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92170, 'Một PM đang sử dụng sơ đồ nhân quả với đội dự án để quyết định các nhân tốt biến đổi sẽ được kết nối ntn với các vấn đề tiềm năng.PM sẽ làm việc trong phần nào của quá trình quản lý chất lượng dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98663, 'Phân tích chất lượng', false, 92170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98664, 'Thực hiện đảm bảo chất lượng', false, 92170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98665, 'Thực hiện kiểm soát chất lượng', false, 92170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98666, 'Lên kế hoạch chất lượng', true, 92170);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92171, 'Một PM và đội từ một công ty thiết kế thiết bị đường sắt đang giao nhiệm vụ để thiết kế thiết bị tải đá vào ô tô đường sắt. thiết kế cho phép 2% số đã bị đổ, tổng số lượng lên tới 2 tấn hao hụt mỗi ngày. Người PM nên dẫn chứng kiểm soát chất lượng, đảm bả chất lượng và cải tiến chất lượng trong văn bản nào??', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98667, 'Kế hoạch quản lý chất lượng', true, 92171);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98668, 'Chính sách chất lượng', false, 92171);
