INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98670, 'Kế hoạch quản lý dự án', false, 92171);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92172, 'Trong khi họp đội dự án, đội dự án thêm vào phạm vi đặc biệt của công việc thêm do họ xác định rằng nó sẽ làm lợi cho khách hàng. Điều gì là sai trong tình huống này', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98671, 'Đội dự án đang tạo thêm lợi ích cho khách hàng nhưng k được trả thêm tiền (gold plating)', true, 92172);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98672, 'B. Những nỗ lực này không nên được hoàn thành trong khi họp', false, 92172);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98673, 'C. Chẳng có gì sai. Đây là cách để thỏa mãn và vượt quá yêu cầu của khách hàng', false, 92172);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98674, 'Chẳng có gì sai. PM đang kiểm soát dc tình huống này', false, 92172);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92173, 'Đội dự án vừa tạo ra kế hoạch mô tả cách họ thực hiện chính sách chất lượng. Nó giải quyết cấu trúc hướng tổ chức, trách nhiệm, thủ tục và các thông tin khác về kế hoạch cho chất lượng. nếu thay đổi này trong quá trình thực hiện dự án, kế hoạch nào dưới đây sẽ thay đổi theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98675, 'Đảm bảo chất lượng', false, 92173);
