INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98678, 'Kiểm soát chất lượng', false, 92173);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92174, 'Bạn là một PM cho một dự án hệ thống thông tin lớn khi một người từ phòng chất lượng đến và nói về bắt đầu kiểm tra chất lượng dự án của bạn. Đội dự án, đã chịu áp lực phải hoàn thành dự án nhanh nhất có thể, cảm thấy khó chịu về kiểm tra này. Bạn nên giải thích với đội rằng mục đích của kiểm tra chất lượng là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98679, 'A. Một phần của giám định ISO 9000', false, 92174);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98680, 'Để kiểm tra nếu khách hàng đang theo sát quy trình chất lượng.', false, 92174);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98681, 'C. Để xác định các chính sách không phù hợp', true, 92174);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98682, 'Để kiểm tra tính chính xác nếu chi phí được đội dự án xem xét', false, 92174);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92175, 'Bạn đang trong dự án xây dựng thiết bị mới. Các kết cấu đã được đặt vào vị trí và các ống dẫn nhiệt cũng sẽ được đặt đúng chỗ, khi đó người quản lý cấp cao thông báo với bạn rằng anh ta đang lo lắng dự án không đáp ứng được tiêu chuẩn chất lượng. Bạn nên làm gì trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98683, 'A. Cam đoan với người quản lý cấp cao rằng trong khi lên kế hoạch chất lượng đã xác định dự án sẽ đáp ứng được tiêu chuẩn chất lượng', false, 92175);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98684, 'Ước tính tương tự sẽ có kết quả trong tương lai', false, 92175);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98685, 'C. Đào tạo đội đảm bảo chất lượng', false, 92175);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98686, 'Kiểm tra kết quả từ các kế hoạch quản lý chất lượng trong quá khứ', true, 92175);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92176, 'Bạn được hỏi để lựa chọn công cụ và kỹ thuật để thực hiện chương trình đảm bảo chất lượng để bổ sung cho các hoạt động kiểm soát chất lượng đã có. Bạn nên chọn điều nào dưới đây?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98687, 'Kiểm tra chất lượng', true, 92176);
