INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98690, 'Phân tích xu hướng', false, 92176);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92177, 'Dự án cài đặt phần mềm mới đang thực hiện. PM đang làm việc với phòng ban đảm bảo chất lượng để cải thiện sự tin tưởng của mọi người rằng dự án sẽ đáp ứng các tiêu chuẩn chất lượng. điều nào dưới đây họ phải có trước khi bắt đầu quá trình này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
