INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98693, 'Hệ thống đo đạc kiểm soát chất lượng', true, 92177);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98694, 'Làm lại công việc (rework)', false, 92177);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92178, 'Dự án bạn đang làm việc có gia tăng chi phí hiệu quả, tăng hiệu suất và tăng tinh thần, chí khí(morale). Điều gì có thể là nguyên nhân cho các thay đổi này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98695, 'Mục tiêu dự án được đáp ứng khi thực hiện', false, 92178);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98696, 'Tăng chất lượng', true, 92178);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98697, 'Ban lãnh đạo tập trung vào chính sách ngăn chặn', false, 92178);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98698, 'Tưởng thưởng (reward) cho nỗ lực của các các nhân', false, 92178);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92179, 'Một PM vừa đảm nhiệm dự án từ một PM khác trong giai đoạn thực thi dự án. Người PM trước đó đã tạo ra ngân sách dự án, xác định các yêu cầu truyền thông và đang chuẩn bị hoàn thành gói công việc. Người PM mới nên làm điều gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98699, 'A. Kết hợp thực hiện các gói công việc', false, 92179);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98700, 'B. Xác định các tiêu chuẩn chất lượng', true, 92179);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98701, 'C. Bắt đầu xác định rủi ro', false, 92179);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98702, 'Thực hiện kế hoạch quản lý dự án', false, 92179);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92180, 'Một dự án đang phải đối mặt với 1 thay đổi lớn đối với sản phẩm đầu ra. Nếu PM phải quyết định tiêu chuẩn chất lượng nào là có liên quan tới thay đổi, PM sẽ', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98703, 'Quản lý chất lượng', false, 92180);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98704, 'Thực hiện đảm bảo chất lượng', false, 92180);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98705, 'Lên kế hoạch chất lượng', true, 92180);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98706, 'Thực hiện kiểm soát chất lượng', false, 92180);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92181, 'Vào cuối dự án, PM xác định dự án sẽ thêm 4 vùng chức năng và 3 vùng hiệu năng. Khách hàng bày tỏ sự hài lòng với dự án. Sự thành công của dự án có nghĩa là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98707, 'Dự án không đủ tiêu chuẩn thành công', false, 92181);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98708, 'Dự án không thành công vì nó thực hiện thêm những điều khách hàng muốn mà k được trả thêm tiền (gold plating)', true, 92181);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98709, 'Dự án không thành công do khách hàng hài lòng nghĩa là họ phải trả thêm tiền cho công việc', false, 92181);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98710, 'Dự án thành công do đội đã có cơ hội học các vùng chức năng mới và khách hàng hài lòng', false, 92181);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92182, 'Trong giai đoạn thực thi dự án, một nhân viên đội dự án thông báo với PM rằng một gói công việc không đáp ứng được tiêu chuẩn chất lượng, và cô ta tin rằng gói công việc này không thể đáp ứng được. PM họp với các bên có liên quan để phân tích tình huống. PM này đang ở trong quy trình quản lý chất lượng nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98711, 'Thực hiện đảm bảo chất lượng', false, 92182);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98712, 'Kiểm soát dự án', false, 92182);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98713, 'Thực hiện kiểm soát chất lượng', true, 92182);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98714, 'Lên kế hoạch chất lượng', false, 92182);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92183, 'PM chú ý rằng các hoạt động dự án đang được hoàn thành bởi 1 phòng ban đều làm việc không đáng kể so với kế hoạch. Đến thời hạn, không có hoạt động hay gói công việc nào đi đúng đường tới hạn, cũng như nó ảnh hưởng tới kế hoạch chuỗi tới hạn. PM khó chịu vì vấn đề này. Khi 4/5 hoạt động trong đường tới hạn phải được phòng ban này thực hiện. sau khi gọi 3 cuộc, cuối cùng, PM quyết định trái với người lãnh đạo của phòng ban này và xác định điều gì đang xảy ra. Cuộc hội thoại này lâu do cả 2 nói 2 ngôn ngữ khác nhau và họ cố gắng giao tiếp bằng tiếng Pháp (ngôn ngữ chung). Để giúp việc giao tiếp đơn giản hơn, PM thường xuyên yêu cầu người lãnh đạo của phòng ban này nhắc lại những gì đã nói. Anh ta nói với nhân viên của mình tuân theo chính sách của công ty và yêu cầu 2 mức kiểm thử. Trong quá trình hội thoại, anh ta cũng nhận xét khiến cho người PM tin rằng chính sách bao gồm quá nhiều công việc. Đây là lần thứ 4 PM nghe những nhận xét như thế. PM nên làm gì tốt nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98715, 'Thời gian trễ trong các đường khác', false, 92183);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98716, 'Sự xuất hiện đường tời hạn mới.', true, 92183);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98717, 'Các nguồn lực được chỉ định cho các nhiệm vụ khác trên đường tới hạn', false, 92183);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98718, 'Nhiệm vụ dài nhất còn lại trong kế hoạch', false, 92183);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92184, 'Điều chỉnh các nhiệm vụ được phân bổ khác nhau trong dự án để duy trì khối lượng nguồn lực phù hợp được gọi là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98719, 'Tạo ra kế hoạch quản lý truyền thông tốt hơn và yêu cầu chỉ một ngôn ngữ chính thức trong dự án và phải có người dịch ngay lập tức', false, 92184);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98720, 'Liên lạc với ai đó trong phòng ban, người này cũng nói ngôn ngữ mẹ đẻ của PM tốt để xác nhận ý kiến của người lãnh đạo phòng ban đó', false, 92184);
