INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92185, 'Một PM bị tràn ngập với các vấn đề trong dự án của anh ấy. Anh ta xác định nguyên nhân gốc rễ của vấn đề theo thứ tự để xác định nên tập trung vào đâu. Công cụ nào dưới đây là tốt nhất để anh ta sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
