INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92186, 'Là một PM, bạn đang chuẩn bị phương pháp để quản lý chất lượng. Bạn đang tìm kiếm phương pháp có thể chứng minh mối quan hệ giữa các sự kiện và kết quả kéo theo. Bạn muốn sử dụng một phương pháp để mô hình các sự kiện này và là nguyên nhân cho ảnh hưởng xấu tới chất lượng. Bạn sẽ sử dụng sơ đồ nào dưới đây để đạt được mục đích của mình?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
