INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92199, 'Một PM phải công bố lịch trình dự án. Các hoạt động, ngày bắt đầu, kết thúc và các nguồn lực đã được xác định. Người PM nên làm gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98779, 'Phân phối lịch trình dự án dựa theo kế hoạch quản lý truyền thông', false, 92199);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98780, 'Xác nhận sự có sẵn của các nguồn lực', true, 92199);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98781, 'Tinh chỉnh kế hoạch quản lý dự án để phản ảnh các thông tin chi phí chính xác hơn', false, 92199);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98782, 'Công bố sơ đồ đoạn giải thích đường thời gian (timeline)', false, 92199);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92200, 'Trong mỗi buổi họp đội dự án, PM hỏi mỗi thành viên đội dự án mô tả công việc họ đang làm và PM phân công các công việc mới cho mỗi thành viên. Thời gian kéo dài của buổi họp tăng do có nhiều công việc khác nhau được phân công. Điều này có thể xảy ra do tất cả các nguyên nhân dưới đây, ngoại trừ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98783, 'Sự thiếu bảng WBS', false, 92200);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98784, 'Sự thiếu ma trận gán trách nhiệm', false, 92200);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98785, 'Sự thiếu cân bằng nguồn lực', true, 92200);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98786, 'Sự thiếu liên quan của đội dự án trong khi lập kế hoạch dự án', false, 92200);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92201, 'Bạn là một PM đứng đầu một dự án liên chức năng trong môi trường ma trận yếu. không có thành viên nào trong đội dự án báo cáo với bạn một cách hữu dụng và bạn không có khả năng để trực tiếp tưởng thưởng cho sự làm việc của họ. dự án khó, kéo theo ràng buộc nghiêm ngặt về thời gian và các thách thức trong quản lý chất lượng. Loại hình sức mạnh quản lý dự án nào dưới đây sẽ có hiệu quả nhất trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98787, 'Ám chỉ (referent)', false, 92201);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98788, 'Chuyên môn (expert)', true, 92201);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98789, 'Hình phạt (penalty)', false, 92201);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98790, 'Luật chính thức (formal)', false, 92201);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92202, 'Một nhân viên dự án không làm việc tốt trong dự án do cô ấy thiếu kinh nghiệm trong công việc phát triển hệ thống. không có sẵn ai có đủ điều kiện để làm việc này. Đối với PM, giải pháp nào là tốt nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98791, 'Tham khảo ý kiến các giám đốc chức năng để xác định động cơ hoàn thành dự án cho thành viên đội dự án', false, 92202);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98792, 'Thay người mới có nhiều kỹ năng hơn để phát triển công việc.', false, 92202);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98793, 'Sắp xếp để nhân viên này được đào tạo', true, 92202);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98794, 'Cấp phát một vài nguồn lịch trình dự trữ', false, 92202);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92203, 'Một PM vừa tìm ra nhà thầu phụ chính của dự án luôn luôn chậm tiến độ công việc. nhân viên dự án có trách nhiệm với phần này của dự án không có tiến triển tốt với nhà thầu phụ này. Để giải quyết vấn đề, người PM nói rằng:”cả 2 người phải từ bỏ một số thứ để giải quyết vấn đề này”. Phương pháp giải quyết vấn đề nào mà PM đang sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98795, 'Đối đầu', false, 92203);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98796, 'Thỏa hiệp', true, 92203);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98797, 'Sự hòa nhã làm ổn thỏa (smoothing)', false, 92203);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98798, 'Giao tiếp', false, 92203);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92204, 'Một dự án có một vài đội. Đội C đã một lần không kịp deadline trong quá khứ. Điều này là nguyên nhân khiến đội D phải hủy đường tới hạn một vài lần. Với tư cách là ng lãnh đạo của đội D, bạn nhận được thông tin rằng deadline tiếp theo có thể sẽ không kịp. bạn nên gặp và trao đổi với:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98799, 'Người quản lý của đội D', false, 92204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98800, 'Chỉ riêng PM', false, 92204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98801, 'PM và ban lãnh đạo', false, 92204);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98802, 'PM và đội trưởng đội C', true, 92204);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92205, 'Dự án mới làm hứng khởi cả PM và đội dự án. Đây là lần đầu tiên người PM được phân công vai trò là PM. Đội có cảm giác họ có khả năng hoàn thành công việc mà chưa bao giờ làm trước đó. Đội gồm 29 người góp phần mô tả sản phẩm và đội gồm 9 chuyên gia nhiều kinh nghiệm chuyên môn. Trong quá trình lên kế hoạch, 3 nhân viên có chuyên môn cao đã không đồng ý về phạm vi của 2 sản phẩm. một ng chỉ ra rằng bản nháp WBS nên thêm 2 gói công việc. một người nói rằng gói công việc liên quan không nên được thực hiện. người thứ 3 đồng ý với 2 người trên. PM nên giải quyết xung đột này ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98803, 'PM nên lắng nghe sự khác biệt trong quan điểm, xác định lựa chọn tốt nhất và thực hiện nó', false, 92205);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98804, 'PM nên trì hoãn các thảo luận, gặp gỡ riêng từng người và xác định cách tiếp cận tốt nhất.', false, 92205);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98805, 'PM nên lắng nghe sự khác biệt trong quan điểm, khuyến khích các thảo luận logic và tạo điều kiện cho thỏa thuận', true, 92205);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98806, 'PM nên giúp đội dự án tập trung vào khía cạnh thích hợp trong ý kiến của họ và xây dựng sự thống nhất bằng cách sử dụng kỹ thuật', false, 92205);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92206, 'Dự án vừa bắt đầu và bao gồm nhân lực từ 14 phòng ban khác nhau. Tôn chỉ dự án được ký bởi một người và bao gồm hơn 30 yêu cầu chính phải được đáp ứng trong dự án. Nhà tài trợ thông báo với PM rằng SPI phải được giữ trong khoảng 0.95 và 1.1. một vài phút điều tra dẫn đến xác định được 34 bên có liên quan, và mục tiêu lịch trình đã có ràng buộc. PM vừa mới được tuyển dụng. loại quyền lực quản lý dự án nào dưới đây là tốt nhất để giúp PM có được sự hợp tác từ những người khác?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98807, 'Luật chính thức', true, 92206);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98808, 'Tư vấn, tham khảo (referent)', false, 92206);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98809, 'Luật phạt', false, 92206);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98810, 'Chuyên môn', false, 92206);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92207, 'PM đang cố gắng giải quyết tranh chấp giữa 2 nhân viên dự án. Một ng nói rằng hệ thống nên được tích hợp trước khi kiểm thử, và người còn lại có ý kiến rằng ủng hộ việc mỗi hệ thống nên được kiểm thử trước khi tích hợp. Dự án bao gồm hơn 30 người, và 12 hệ thống cần phải tích hợp. nhà tài trợ yêu cầu rằng việc tích hợp phải được thực hiện đúng thời điểm. tuyên bố nào của PM là tốt nhất để giải quyết mâu thuẫn này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98811, 'Làm theo cách của PM', false, 92207);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98812, 'Mọi người hãy bình tĩnh để hoàn thành công việc', false, 92207);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98813, 'Hãy giải quyết vấn đề này một lần nữa vào tuần sau khi mọi người đều bình tĩnh', false, 92207);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98814, 'Hãy thực hiện các kiểm thử giới hạn trước khi thực hiện và kết thúc kiểm thử sau khi cài đặt', true, 92207);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92208, 'Một PM đang trong giai đoạn thực thi dự án khi một bên có liên quan đề nghị một thay đổi lớn. thay đổi này sẽ dẫn đến sửa chữa lớn lần thứ 3 của dự án. Vào cùng thời điểm, PM khám phá ra một gói công việc lớn của được hoàn thành do một thủ trưởng đã chuyển nhân viên của anh ta sang một dự án khác có mức độ ưu tiên cao hơn. Ai là người thích hợp nhất để PM xác định các vấn đề này cùng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98815, 'Đội dự án', false, 92208);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98816, 'Người quản lý cấp cao', false, 92208);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98817, 'Khách hàng', false, 92208);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98818, 'Nhà tài trợ', true, 92208);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92209, 'Làm việc trong một dự án đang thực hiện khi PM chợt nghe 2 nhân viên cãi nhau về tập hợp các hướng dẫn. PM điều tra và khám phá rằng các hướng dẫn cho việc xây dựng móng bên tông đang được đổ được dịch sai giữa 2 ngôn ngữ khác nhau đang được sử dụng trong dự án. Điều nào dưới đây là tốt nhất đối với PM để làm đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98819, 'Lấy hướng dẫn được dịch bởi một bên tin cậy và nhiều kinh nghiệm', false, 92209);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98820, 'Tìm kiếm cho các ảnh hưởng về chất lượng của việc dịch sai hướng dẫn đổ móng', true, 92209);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98821, 'Làm đội dự án chú ý tới vấn đề này và hỏi họ tìm kiếm các lỗi khác của bản dịch', false, 92209);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98822, 'Thông báo với nhà tài trợ về vấn đề trong báo cáo dự án tiếp theo.', false, 92209);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92210, 'Kỹ thuật giải quyết xung đột có thể được sử dụng trong dự án bao gồm: đối đầu, làm bình lặng (smoothing), vũ lực và:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
