INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98826, 'Kiểm soát', false, 92210);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92211, 'Việc thực hiện dự án có CPI=1.03 và SPI=1. Có 14 nhân viên và mỗi nhân viên đều có đầu vào trong kế hoạch quản lý dự án cuối cùng. Khách hàng đồng ý 3 sản phẩm bàn giao hoàn thành cho đến nay mà k có phàn nàn và ma trận gán trách nhiệm không thay đổi từ khi dự án bắt đầu. dự án đang được hoàn thành trong môi trường ma trận và không có hợp đồng nào thêm vào dự án. Nhà tài trợ hài lòng với trạng thái của dự án, một nhân viên luôn phàn nàn về việc công việc dự án của anh ta khá tốn thời gian. Điều nào dưới đây là tốt nhất cho PM thực hiện?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98827, 'Xem xét lại hệ thống thưởng của dự án', true, 92211);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98828, 'Cố gắng cải thiện hiệu năng lịch trình của dự án', false, 92211);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98829, 'Gặp khách hàng để cố gắng kéo dài tiến độ', false, 92211);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98830, 'Giành lấy văn bản chấp nhận chính thức từ khách hàng', false, 92211);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92212, 'Dự án đang được thử thách quản lý. Mỗi người bị thúc giục để hoàn thành dự án đúng thời hạn. Không may, sự căng thẳng tăng lên đến nỗi mỗi cuộc họp đội dự án đều trở thành chiến trường cãi nhau và có rất ít công việc được hoàn thành trong buổi họp. một nhân viên yêu cầu được vắng mặt trong các buổi họp tiếp theo, vì mng làm anh ta bực mình. Trong khi đó, nhà tài trợ yêu cầu được tham dự để hiểu rõ hơn dự án đang được thực hiện ntn và các vấn đề liên quan để hoàn thành dự án, và khách hàng bắt đầu thảo luận về thêm phạm vi vào dự án. Trong tình huống này, PM tốt nhất nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98831, 'Hỏi nhà tài trợ nếu các thông tin cần thiết nên được gửi trong báo cáo hơn là nhà tài trợ tham gia vào buổi họp', false, 92212);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98832, 'Thông báo với đội ai muốn được vắng mặt buổi họp về nguyên tắc của truyền thông trong các buổi họp như thế này', false, 92212);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98833, 'Tạo ra một luật mới cho các buổi họp và thông báo tới đội dự án', true, 92212);
