INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92213, 'Đánh giá hiệu quả dự án khác với hành động đánh giá hiệu năng đội dự án ở chỗ đánh giá hiệu quả dự án tập trung vào:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
