INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92214, 'Một PM có 1 vấn đề phức tạp để giải quyết và tạo quyết định về cái gì cần thiết để làm. Một vài tháng sau, vấn đề lại xuất hiện trở lại. PM đã KHÔNG làm gì trước đó?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
