INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92216, 'Bạn vừa tìm ra một nhà thầu phụ chính cho dự án của bạn đã cung cấp hàng chậm tiến độ. Nhà thầu phụ này tiếp cận với bạn và yêu cầu tiếp tục chấp nhận hàng sẽ bị chậm nhưng sẽ được giảm 1 phần giá thành. Lời mời chào này là một ví dụ về:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
