INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98889, 'Sơ đồ đoạn (bar chart)', false, 92226);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98890, 'Kế hoạch quản lý truyền thông', true, 92226);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92227, 'Thông tin dự án đã được phân phối dựa theo kế hoạch quản lý truyền thông. Một vài sản phẩm của dự án đã thay đổi tuân theo kế hoạch quản lý dự án. Một bên có liên quan tỏ ra ngạc nhiên với PM khi nghe thấy các thay đổi đã được công bố về sản phẩm dự án. Tất cả các bên có liên quan đều nhận được thông báo về thay đổi. PM nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98891, 'Xác định tại sao bên có liên quan đó không nhận được thông tin và cho anh ta biếtkhi nó đã được công bố', false, 92227);
