INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98894, 'Xác định tình huống trong buổi họp ủy ban hướng dẫn lần tới để những ngườicòn lại không bỏ sót các thông tin thay đổi được công bố.', false, 92227);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92228, 'Truyền thông là chìa khóa thành công của dự án. Với tư cách là PM, bạn có 3 bên có liên quan cần phải giao tiếp. bạn có 6 kênh truyền thông. Một bên có liên quan mới được thêm vào và bạn cũng phải giao tiếp với anh ta. Như vậy có bao nhiêu kênh truyền thông bạn đang có bi h?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98895, '7', false, 92228);
