INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92229, '2 nhân viên đang cãi nhau về điều gì cần làm để hoàn thành gói công việc.Nếu PM muốn biết chuyện gì đang xảy ra, cô ấy nên chú ý nhất vào:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98899, 'Điều gì đã được nói ra và khi nào', false, 92229);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98900, 'Điều gì đã được nói ra, ai nói và thời gian nói', false, 92229);
