INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98902, 'Mức độ và tông giọng của mỗi người (nói từ từ hay quát vào mặt nhau J) ) vàcách nói riêng của mỗi người.', true, 92229);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92230, 'Một PM có một đội dự án bao gồm các nhân viên từ 4 quốc gia. Dự án rất quan trọng đối với công ty, và PM có liên quan tới thành công của dự án. Thời gian của dự án là chấp nhận được. Loại phương pháp truyền thông nào anh ta nên sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98903, 'Lời nói không chính thức', false, 92230);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98904, 'Văn bản chính thức', true, 92230);
