INSERT INTO _answer (id, text, is_correct, question_id) VALUES (98906, 'Văn bản không chính thức', false, 92230);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92231, 'Nhân tố nào có ảnh hưởng lớn nhất tới chi phí lao động theo ước tính trên đơn vị cho dự án.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
