INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92263, 'Một PM tập hợp đội dựán lại, xác định 56 rủi ro trong dựán, xác định các yếu tốkích hoạt rủi ro, xếp hạng trong ma trận mức độrủi ro, kiểm tra các giảthiết và ước lượng chất lượng dữliệu sửdụng. Đội dựán vẫn tiếp tục chuyển sang quá trình quản lýrủi ro. PM đã quên không làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
