INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92265, 'Trong khi lên kếhoạch quản lýrủi ro, đội của bạn đã đưa ra 434 rủi ro và 16 nguyên nhân chính của các rủi ro này. Dựán là dựán cuối cùng trong chuỗi các dự án mà đội sẽlàm việc cùng nhau. Nhà tài trợrất khuyến khích và một khối lượng lớn thời gian đã được đầu tư đểchắc chắn tôn chỉdựán đã hoàn thành và được ký bởi tất cảcác bên có liên quan chính. Trong giai đoạn lập kếhoạch dựán, đội không đưa ra một cách thức hiệu quả đểlàm giảm hoặc thoát rủi ro. Nó không phải là công việc đểcó thểthuê ngoài hay bịloại bỏ. Giải pháp tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
