INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92300, 'Nhà tài trợvà PM đang thảo luận loại hợp đồng nào mà PM lên kếhoạch sử dụng trong dựán. Người bán chỉra rằng tổchức thực hiện đã dành ra nhiều tiền để thuê đội ngũthiết kế để đưa ra bản thiết kế. PM lo lắng rằng rủi ro từngười mua sẽ ít nhất có thể. Một lợi thếtừhợp đồng giá cô định cho người bán là', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
