INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92301, 'Nhưmột phần của hệthống quản lýsổsách, bạn đang cốgắng chắc chắn rằng toàn bộhồsơtừhợp đồng đã được ghi lại và ghi vào bản mục lục. Điều nào dưới đây bạn không nên lo lắng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
