INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92305, 'Công ty của bạn có một việc khẩn cấp và cần các công việc hợp đồng hoàn thành càng sớm càng tốt. Với tình huống này, điều nào dưới đây là có ích nhất để thêm vào hợp đồng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
