INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92307, 'Đội dựán đang cãi nhau vềngười bán tiềm năng mà chấp nhận các đềnghị. Một nhân viên dự án tranh luận vềmột người bán tin cậy trong khi 1 nhân viên khác muốn dựán được trao cho một người bán khác. Đội dựán đang ởtrong phần nào của quá trình quản lýthu mua?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
