INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92308, 'Đội dựán dường nhưthích tranh luận: họ đã tranh luận vềmọi thứ. Thật may là PM đã thiết lập 1 hệthống kiểm tra và các buổi họp xây dựng đội mà sẽgiúp đỡ và khuyến khích đội dựán hợp tác nhiều hơn với nhau. Điều mới nhất họtranh luận là họnên tựhoàn thành gói công việc của mình hay thuê ngoài. Họ đang ở trong quá trình nào của việc quản lýthu mua?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
