INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92310, 'Bạn là 1 PM, người quản lý chương trình đến đểgiúp đỡvềgiá thầu cho dự án mới nhất của cô ấy. bạn muốn bảo vệcông ty của bạn khỏi các rủi ro tài chính. Bạn đã có định nghĩa phạm vi giới hạn. Loại hình hợp đồng nào là tốt nhất đểlựa chọn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
