INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92312, 'Dựán của bạn vừa được xúc tiến và bạn đang tìm kiếm một nhà thầy phụ để hoàn thiện mạng lưới nhanh chóng. Không có thời gian để đưa ra yêu cầu cho các đềnghị(RFP) nên bạn chọn sửdụng một công ty bạn đã sửdụng nhiều lần đểphát triển phần mềm. Mối bận tâm chính trong tình huống này là', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99230, 'Sựthông đồng giữa các nhà thầu phụ', false, 92312);
