INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99233, 'Tổchức hội nghịnhà thầu.', false, 92312);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92313, 'PM và nhà tài trợdựán đang thảo luận vềchi phí dựán và khi nào tốt đểcông ty của họtham gia vào dựán hoặc thuê một công ty khác làm việc này. Nếu họhỏi ýkiến của bạn, bạn nên nói rằng công ty nên tựlàm dựán này sẽtốt hơn nếu như:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99234, 'Có quá nhiều dữliệu độc quyền', true, 92313);
