INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99244, 'Đưa ra một văn bản mặc định (default letter)', true, 92315);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99245, 'Yêu cầu người bán ngừng làm việc cho tới khi kếhoạch công việc được chuẩn bị.', false, 92315);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92316, 'Kết thúc hợp đồng khác với kết thúc hoạt động quản trị ởchỗ, kết thúc hợp đồng', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
