INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92318, 'Đội dự án đang tranh luận về người bán sắp tới, người đã đệ trình các đề nghị (submit proposals). Một nhân viên tranh luận về một người bán tin cậy, trong khi một nhân viên khác muốn một nguòi bán khác sẽ có dự án. Điều tốt nhất mà PM nên nhắc nhở đội của mình tập trung vào trong quá trình tìm ra lựa chọn là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99254, 'Các tài liệu hợp đồng', false, 92318);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99255, 'Kiểm tra hợp đồng', false, 92318);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99256, 'Các tiêu chuẩn đánh giá', true, 92318);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99257, 'Kế hoạch quản lý hợp đồng', false, 92318);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92319, 'Tổ chức đang cố gắng quyết định có nên chia phòng ban quản lý hợp đồng và phân công trách nhiệm ký kết hợp đồng cho một phòng ban có trách nhiệm trực tiếp với dự án hay không. Một chuyên gia về hợp đồng không thực sự muốn có sự chia tách này do họ sẽ mất……………………… trong môi trường phân tán việc ký kết hợp đồng (or phi tập trung- decentralized)', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99258, 'Tiêu chuẩn thực hiện quản lý dự án của công ty', false, 92319);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99259, 'Sự trung thành với dự án (loyalty)', false, 92319);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99260, 'Kinh nghiệm', false, 92319);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99261, 'Quyền được truy cập cho những người khác với những chuyên môn tương tự', true, 92319);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92320, 'Trong giai đoạn thực thi dự án, các nhân viên đội dự án bàn giao sản phẩm của dự án cho người bán. Tuy nhiên, người bán từ chối những sản phẩm này, tuyên bố rằng nó không đáp ứng yêu cầu ở trang 300 của tài liệu đặc tả chi tiết kỹ thuật. bạn đã xem lại tài liệu và cũng đồng {. Điều tốt nhất nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99262, 'Giải thích rằng hợp đồng đã sai và nên được thay đổi', false, 92320);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99263, 'Đưa ra yêu cầu thay đổi', false, 92320);
