INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99265, 'Họp đội dự án để xem xét lại yêu cầu ở trang 300', false, 92320);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92321, 'Loại hợp đồng nào bạn KHÔNG muốn sử dụng nếu bạn không đủ nhân lực để kiểm tra các hóa đơn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
