INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99269, 'Hợp đồng khuyến mại giá cố định (FPIF-fixed price incentive fee)', false, 92321);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92322, 'Một PM mới đang bắt đầu tạo ra bản hợp đồng tuyên bố công việc. Một bên có liên quan muốn thêm 1 vài hạng mục vào bản hợp đồng tuyên bố công việc. Một bên có liên quan khác chỉ muốn mô tả các yêu cầu chức năng. dự án rất quan trọng với công ty của PM, nhưng một người bán sẽ làm việc này. Bạn sẽ khuyên PM này điều gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99270, 'Bản hợp đồng tuyên bố công việc nên chung chung (general) để cho phép người bán có quyết định của riêng mình', false, 92322);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99271, 'Bản hợp đồng tuyên bố công việc nên chung chung để cho phép các hiệu chỉnh sau này', false, 92322);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99272, 'Bản hợp đồng tuyên bố công việc nên chi tiết để cho phép các hiệu chỉnh sau này', false, 92322);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99273, 'Bản hợp đồng tuyên bố công việc nên càng chi tiết càng tốt cho loại dự án', true, 92322);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92323, 'Một khách hàng đưa cho bạn bản hợp đồng tuyên bố công việc cho một dự án 8 tháng khá phức tạp và có 1 vài điểm chưa biết. Khách hàng yêu cầu bạn chỉ làm việc (just “get it done”) và chỉ muốn gặp bạn vào cuối tháng thứ 8 khi bạn bàn giao dự án hoàn thiện. trong tình huống này, điều tốt nhất nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99274, 'Hoàn thành dự án như được yêu cầu, nhưng thỉnh thoảng xác minh phạm vi với khách hàng trong suốt dự án', true, 92323);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99275, 'Hoàn thành dự án chỉ trong 8 tháng mà không hề liên lạc với khách hàng trong khoảng thời gian này', false, 92323);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99276, 'Hỏi ban lãnh đạo để thỉnh thoảng xác nhận với khách hàng', false, 92323);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99277, 'Hoàn thành dự án, nhưng ghi lại rằng khách hàng không muốn liên lạc', false, 92323);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92324, 'Gần cuối dự án cuối cùng của bạn, một nhóm các bên có liên quan muốn thêm các yêu cầu vào khi họ biết rằng họ sẽ bị ảnh hưởng từ dự án của bạn. điều này sẽ là một rắc rối do bạn không bao gồm thời gian và chi phí trong kế hoạch quản lý dự án cho những yêu cầu kiểu này. Điều tốt nhất bạn nên làm đề ngăn chặn những vấn đề này trong các dự án sắp tới là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99278, 'Xem xét lại từ điển WBS thật kỹ lưỡng, tìm kiếm các mô tả chưa hoàn tất', false, 92324);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99279, 'Xem xét lại tôn chỉ dự án thật kỹ lưỡng, kiểm tra các lỗ hổng nghiệp vụ', false, 92324);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99280, 'Làm thêm một công việc kỹ lưỡng về lên kế hoạch hợp đồng', false, 92324);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99281, 'Chú { thêm vào ban lãnh đạo các bên có liên quan', true, 92324);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92325, 'Dự án phát triển phần mềm không phát triển tốt. có hơn 30 bên có liên quan, và không ai đồng ý với mục tiêu dự án. Một bên có liên quan tin rằng dự án có thể có được 30% cải thiện trong khi một bên khác tin rằng có thể lên tới 50%. PM thì là 10% cải thiện là thực tế hơn. Cách giải quyết tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99282, 'Tiếp tục phát triển dự án và tìm kiếm thêm thông tin sau đó để giải quyết vấn đề', false, 92325);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99283, 'Lấy số liệu trung bình và sử dụng làm mục tiêu', false, 92325);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99284, 'Thực hiện một phân tích khả thi', true, 92325);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99285, 'Hỏi nhà tài trợ để có quyết định cuối cùng', false, 92325);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92326, 'Một đội dự án đã hoàn thành, và khách hàng đã chấp nhận, phạm vi dự án đã hoàn thành. Tuy nhiên, các bài học rút ra do phòng ban quản lý dự án yêu cầu vẫn chưa dc hoàn thành. Trạng thái của dự án là ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99286, 'Dự án chưa hoàn thành do dự án cần phải lên kế hoạch lại', false, 92326);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99287, 'Dự án chưa hoàn thành cho tới khi toàn bộ dự án và sản phẩm bàn giao là hoàn thành và được chấp nhận', true, 92326);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99288, 'Dự án là hoàn thành do khách hàng đã chấp nhận sản phẩm bàn giao', false, 92326);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99289, 'Dự án hoàn thành do dự án đã đến ngày kết thúc (reach the due date)', false, 92326);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92327, 'Bạn đang ở giai đoạn giữa dự án của một sản phẩm mới phát triển cho 1công ty công khai giao dịch, bạn biết được người PM trước đã chi trả 3000000$ mà không được phê chuẩn theo chính sách công ty. Thật may mắn, CPI=1.2. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99290, 'Liên lạc với người quản lý của bạn', true, 92327);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99291, 'Đặt khoản chi đó vào một tài khoản của bên thứ 3 (escrow account) để làm bằng chứng', false, 92327);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99292, 'Che giấu khoản chi này trong phần tập trung chi phí lớn nhất sẵn có (the largest cost center available)', false, 92327);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99293, 'Từ chối khoản chi này', false, 92327);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92328, 'Trong cuộc họp với một vài bên có liên quan, PM được yêu cầu thêm công việc vào phạm vi dự án. PM đã sử dụng thông tin phù hợp với dự án trước khi tôn chỉ dự án được ký và nhớ rằng nhà tài trợ đã từ chối rõ ràng các khoản vốn cho phạm vi được đề cập bởi các bên có liên quan. Điều tốt nhất mà PM nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99294, 'Cho nhà tài trợ biết các yêu cầu của các bên có liên quan', false, 92328);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99295, 'Đánh giá ảnh hướng của các phạm vi thêm vào', false, 92328);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99296, 'Nói với các bên có liên quan rằng không thể thêm phạm vi', true, 92328);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99297, 'Thêm công việc nếu còn thời gian trong lịch trình dự án', false, 92328);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92329, 'Khi kiểm tra lịch của một nhân viên để lên lịch họp, bạn nhìn thấy cô ấy đã đặt lịch gặp với 1 bên có liên quan chính nhưng bạn đã không được thông báo. Cách thăm dò tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99298, 'Từ chối đề cập vấn đề này với nhân viên đó nhưng vẫn tiếp tục theo dõi các hành động của cô ta.', false, 92329);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99299, 'Thông báo với thủ trưởng của bạn về vấn đề này', false, 92329);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99300, 'Nói chuyện về việc này với thủ trưởng của cô ta', false, 92329);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99301, 'Nói chuyện về việc này với cô ấy', true, 92329);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92330, 'PM đang có một thời gian khó khăn khi giữ cho dự án phát triển đúng lịch trình. Dự án yêu cầu 220 người để hoàn thành. Tất cả các vấn đề của dự án đã được giải quyết và PM hài lòng, SPI=0.67, CPI=1.26, có 23 hoạt động trong đường tới hạn và độ dài PERT của dự án là 26. Trong điều kiện này, báo cáo trạng thái hàng tháng nên báo cáo rằng:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99302, 'Dự án vẫn hoạt động tốt', false, 92330);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99303, 'Dự án sẽ bị chậm tiến độ', false, 92330);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99304, 'Chi phí dự án thấp hơn ngân sách', false, 92330);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99305, 'Các vấn đề và các tùy chọn', true, 92330);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92331, 'Nhân viên của bạn đã chậm 3 ngày so với lịch báo cáo. 5 phút trước khi cuộc họp mà chủ đề của báo cáo sẽ được thảo luận thì cô ấy mới đưa cho bạn báo cáo. Bạn nhận thấy có 1 vài lỗi nghiêm trọng trong đó, bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99306, 'Hủy cuôc họp và lên lịch họp lại sau khi báo cáo đã được sửa chữa', true, 92331);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99307, 'Tới buổi họp và nói với mọi người tham gia là có lỗi trong báo cáo', false, 92331);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99308, 'Bắt buộc nhân viên phải thuyết trình và những người tham gia khác im lặng tìm lỗi', false, 92331);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99309, 'Hủy cuộc họp và tự viết lại báo cáo', false, 92331);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92332, 'Một người quản lý có trách nhiệm cho 1 dự án có được sự hỗ trợ từ người lãnh đạo cấp cao. Từ khi bắt đầu, bạn đã không đồng ý với ng quản lý này về việc dự án nên tiến hàng ntn và các sản phẩm bàn giao là gì. Bạn và cô ấy đã bất đồng quan điểm rất nhiều vấn đề trong quá khứ. Phòng ban của bạn được giao nhiệm vụ cung cấp 1 vài gói công việc quan trọng do dự án. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99310, 'Cung cấp cho cô ta những gì cô ấy cần', true, 92332);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99311, 'Thông báo với quản lý của bạn về mối lo âu về sự hỗ trợ của cô ấy', false, 92332);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99312, 'Nói chuyện với cô ta vào lúc bắt đầu dự án và cố gắng mô tả tại sao bạn phản đối và tìm ra 1 cách để giải quyết vấn đề', false, 92332);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99313, 'Hỏi để được thoát ra khỏi dự án', false, 92332);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92333, 'Một dự án lớn và phức tạp về xây dựng trong một công ty nc ngoài yêu cầu sự kết hợp để di chuyển các thiết bị yêu cầu qua 1 con phố đông đúc. Để chắc chắn thiết bị được vận chuyển an toàn, các mối liên hệ của bạn ở nc này thông báo rằng bạn phải trả cho các cảnh sát địa phương 1 khoản để thuận tiện cho việc vận chuyển. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
