INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92334, 'Một cuộc thương lượng lớn với 1 nhà thầu phụ tiềm năng đã được lên lịch vào ngày mai, bạn phát hiện ra có 1 cơ hội tốt mà dự án sẽ bị hoãn. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
