INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92335, 'Bạn được phân công quản lý 1 dự án đã hoàn thành được 1 nửa theo lịch trình. Sau đánh giá bao quát, bạn phát hiện ra dự án đang đi chậm hơn lịch trình (far behind schedule), và dự án có thể sẽ kéo dài gấp đôi thời gian ước tính ban đầu của PM trước. tuy nhiên, nhà tài trợ đã được nói là dự án đang đúng lịch trình. Hành đông tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99322, 'Cố gắng cấu trúc lại lịch trình để đáp ứng với thời hạn cuối cùng của dự án', false, 92335);
