INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99329, 'Cài đặt thay đổi đối với các địa điểm còn lại và tiếp tục theo lịch trình', false, 92336);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92337, 'Bạn đang làm việc trong dự án nghiên cứu và phát triển, khách hàng yêu cầu bạn bao gồm một thành phần đặc biệt vào dự án. Bạn biết rằng nó có nghĩa là thêm công việc, và bạn k muốn có sự vượt quá nguồn dự trữ có sẵn. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
