INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92338, 'Bạn là PM cho 1 trong nhiều dự án trong 1 chương trình lớn và quan trọng. tại buổi họp quan trọng, bạn chú ý rằng một PM khác đã báo cáo dự án của cô ấy đúng lịch trình. Tìm kiếm trong dự án của bạn khoảng 1 vài tuần trc, bạn nhớ rằng nhiều sản phẩm bàn giao từ dự án khác đã bị chậm trễ. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
