INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92340, 'Nhân viên của bạn đã chậm 3 ngày so với lịch báo cáo. 5 phút trước khi cuộc họp mà chủ đề của báo cáo sẽ được thảo luận thì cô ấy mới đưa cho bạn báo cáo. Bạn thấy có 1 vài lỗi nghiêm trọng trong báo cáo. Điều này có thể ngăn chặn ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
