INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92343, 'Để hoàn thành công việc trong dự án của bạn, bạn đã được cung cấp các thông tin bí mật từ tất cả khách hàng của bạn. một trường đại học liên lạc với bạn để nhờ giúp đỡ trong nghiên cứu của họ. sự giúp đỡ như vậy sẽ đòi hỏi bạn cung cấp cho công ty 1 vài dữ liệu khách hàng từ file của bạn. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
