INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92344, 'Ban lãnh đạo đã hứa với bạn 1 phần phí ưu đãi từ khách hàng nếu bạn hoàn thành dự án sớm hạn. trong khi hoàn thành 1 sản phẩm bàn giao quan trọng, đội của bạn thông báo rằng sản phẩm đã đáp ứng các yêu cầu trong hợp đồng nhưng không cung cấp chức năng mà khách hàng cần. nếu sản phẩm bàn giao muộn, dự án không thể hoàn thành sớm hạn. bạn nên làm gì /', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
