INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92345, 'Bạn vừa phát hiện ra 1 lỗi trong kế hoạch cài đặt mà sẽ ngăn cản 1 cuộc họp quan trọng (milestone date). điều tốt nhất bạn nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
