INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92346, 'Trong khi kiểm tra độ bền của bêtông được đổ trong dự án của bạn, bạn phát hiện ra hơn 35% bê tông không đáp ứng được tiêu chuẩn chất lượng của công ty bạn. bạn cảm thấy chắc chắn rằng bê tông sẽ hoạt động tốt, và bạn k nghĩ rằng bê tông cần đáp ứng các tiêu chuẩn chất lượng. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
