INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99373, 'Mã hóa cẩn thận tất cả các giao tiếp của PM', false, 92347);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92348, 'Một dự án có ngân sách eo hẹp khi bạn bắt đầu thương lượng với 1 người bán về thiết bị. người bán nói với bạn rằng giá của thiết bị này là cố định. Ng quản lý của bạn nói với bạn thương lượng giá cả với người bán. Hành động nào là tốt nhất', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99374, 'Thực hiện nỗ lực cam kết tốt để tìm cách giảm giá', true, 92348);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99375, 'Hoãn thương lượng cho tới khi bạn thuyết phục được ng quản lý của bạn thay đổi quyết định', false, 92348);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99376, 'Vẫn thương lượng, nhưng chỉ về những khía cạnh khác của dự án', false, 92348);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99377, 'Hủy thương lượng', false, 92348);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92349, 'Bạn đang làm việc trong 1 dự án xây dựng lớn đang thực hiện trong đường giới hạn. các nguồn lực được sử dụng từ từ(remain steady), thủ trưởng của bạn vừa thưởng bạn vì nỗ lực của bạn. một thành viên đội dự án trở về từ 1 cuộc họp với khách hàng và nói với bạn rằng khách hàng không hài lòng với việc thực hiện dự án. Điều đầu tiên bạn nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99378, 'Nói với ng quản lý của bạn', false, 92349);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99379, 'Hoàn thành các bài tập xây dựng đội dự án và mời đại diện khách hàng tham dự', false, 92349);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99380, 'Thay đổi đường lịch trình cơ bản', false, 92349);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99381, 'Gặp khách hàng để tìm ra chi tiết (uncover detail)', true, 92349);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92350, 'Một PM phát hiện một khuyết điểm trong sản phẩm mà phải bàn giao cho khách hàng hôm nay. PM biết khách hàng k có hiểu biết kĩ thuật để chú ý tới khuyết điểm này. Sản phẩm đáp ứng các yêu cầu của hợp đồng, nhưng không đáp ứng tiêu chuẩn chất lượng của PM. PM nên làm gì trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99382, 'Đưa ra sản phẩm và lấy sự chấp nhận chính thức từ khách hàng', false, 92350);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99383, 'Ghi lại vấn đề trong các bài học thu được để các dự án trong tương lai sẽ không mắc phải vấn đề đó nữa', false, 92350);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99384, 'Thảo luận vấn đề với khách hàng', true, 92350);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99385, 'Thông báo với khách hàng sản phẩm sẽ bị chậm trễ', false, 92350);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92351, 'Ban lãnh đạo nói với 1 PM để thầu lại một phần của dự án cho 1 công ty mà ban lãnh đạo đã làm việc nhiều lần. trong tình huống này, PM nên bận tâm lớn nhất về:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99386, 'Chắc chắn công ty có đủ khả năng để hoàn thành dự án', true, 92351);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99387, 'Đáp ứng yêu cầu thời gian của ban lãnh đạo', false, 92351);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99388, 'Chi phí của công việc thầu lại', false, 92351);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99389, 'Các điều khoản và điều kiện hợp đồng', false, 92351);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92352, 'Khách hàng trong một dự án nói với PM rằng anh ta đã hết tiền chi trả cho dự án. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99390, 'Thay đổi lịch trình các công việc để thực hiện thời gian muộn hơn so với lịch trình cũ để khách hàng có thêm nguồn vốn', false, 92352);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99391, 'Bắt đầu kết thúc các hoạt động quản trị', true, 92352);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99392, 'Dừng công việc', false, 92352);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99393, 'Cắt giảm nhân sự 1 phần đội dự án (release part of the team)', false, 92352);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92353, 'Bạn là PM cho 1 dự án lớn trong hợp đồng với chính phủ. Hợp đồng 2 năm, nhiều triệu $ đã được ký 6 tháng trước. bạn không được kéo theo trong thương lượng hợp đồng hay thiết lập các thủ tục cho việc quản lý các thay đổi, nhưng bạn đang tràn ngập với các thay đổi từ khách hàng và từ những người trong tổ chức của bạn. thông thường, ai sẽ có trách nhiệm cho việc xem xét chính thức các thay đổi lớn đối với dự án/hợp đồng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99394, 'Ban kiểm soát thay đổi', true, 92353);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99395, 'Ban ký hợp đồng/pháp lý', false, 92353);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99396, 'PM', false, 92353);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99397, 'Lãnh đạo cấp cao', false, 92353);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92354, 'Phòng kĩ thuật muốn mục tiêu dự án cải thiện 10%. Phòng IT muốn nguồn lực của phòng k bị sử dụng nhiều hơn 5% vào dự án. Ban lãnh đạo, cũng là thủ trưởng của bạn, muốn đội dự án giảm thuế pháp lý (tax liability). Điều tốt nhất bạn nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99398, 'Xây dựng 1 kế hoạch đáp ứng tất cả các mục tiêu trên', false, 92354);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99399, 'Mọi người cùng bàn bạc và đồng ý 1 mục tiêu', false, 92354);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99400, 'Tính đến mục tiêu của phòng kỹ thuật và phòng IT nhưng đáp ứng ít đối với mục tiêu của ban lãnh đạo (holding a further meeting)', true, 92354);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99401, 'Chỉ tính đến mục tiêu của ban lãnh đạo.', false, 92354);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92355, 'Điều chỉnh các nhiệm vụ được phân bổ khác nhau trong dự án để duy trì khối lượng nguồn lực phù hợp được gọi là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99402, 'Tạo ra kế hoạch quản lý truyền thông tốt hơn và yêu cầu chỉ một ngôn ngữ chính thức trong dự án và phải có người dịch ngay lập tức', false, 92355);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99403, 'Liên lạc với ai đó trong phòng ban, người này cũng nói ngôn ngữ mẹ đẻ của PM tốt để xác nhận ý kiến của người lãnh đạo phòng ban đó', false, 92355);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99404, 'Tìm xem nếu hành động tiếp theo có nên ước tính lại không', false, 92355);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99405, 'Làm việc với hiệu quả gia tăng của tổ chức thực hiện bằng cách khuyến khi sự cải thiện của chính sách bằng cách sử dụng các câu hỏi', true, 92355);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92356, 'Nhân tố nào có ảnh hưởng lớn nhất tới chi phí lao động theo ước tính trên đơn vị cho dự án.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99406, 'Thông tin lịch sử', false, 92356);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99407, 'Sử dụng các nhà cung cấp bên ngoài.', false, 92356);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99408, 'Các quy trình kiểm soát thay đổi.', false, 92356);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99409, 'Các yêu cầu mức độ kỹ năng nguồn nhân lực', true, 92356);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92357, 'Giám đốc dự án đang xây dựng kế hoạch cho dự án. Giám đốc dự án đã xác định các nhiệm vụ và chỉ định nguồn lực thích hợp. Công cụ được sử dụng thông báo rằng một vài nguồn lực được phân bổ xong. Bước tiếp theo của giám đốc dự án sẽ là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99410, 'Di chuyển các nguồn lực.', false, 92357);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99411, 'Yêu cầu thêm nguồn lực.', false, 92357);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99412, 'Điều chỉnh nguồn lực', true, 92357);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99413, 'Dự thảo ngân sách ngoài giờ', false, 92357);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92358, 'Giám đốc dự án đã khám phá vấn đề với môđun thống kê của dự án. Các số đo đã được ghi rõ cho các đơn vị của của Mỹ nhưng các nhà lập trình nước ngoài sử dụng các đơn vị quốc tế. Vấn đề này có thể tránh được ở chỗ nào trong dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99414, 'Lập kế hoạch dự án', true, 92358);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99415, 'Kiểm thử dự án.', false, 92358);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99416, 'Kiểm soát dự án.', false, 92358);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99417, 'Quay vòng dự án', false, 92358);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92359, 'Giám đốc dự án được chỉ định cho một dự án lớn đã và đang được thực hiện một số lần. Đội dự án vừa hoàn tất giai đoạn thiết kế của dự án và đang tiến hành trong giai đoạn triển khai. Tại điểm này, thay đổi nào có thể xẩy ra mà không phải gánh chịu rủi ro của việc tiến hành lại toàn bộ giai đoạn thiết kế?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99418, 'Phạm vi', false, 92359);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99419, 'Nhiệm vụ', false, 92359);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99420, 'Thiết kế chi tiết', false, 92359);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99421, 'Ngày tháng chuyển giao', true, 92359);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92360, 'Giám đốc dự án được khách hàng đề nghị thực hiện những thay đổi quan trọng cho dự án. Những thay đổi này không được chú tâm trong Tài liệu thiết kế hay Phạm vi dự án. Cách tốt nhất để giám đốc dự án đáp lại yêu cầu là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99422, 'Thông báo với khách hàng rằng thay đổi phạm vi là không được phép.', false, 92360);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99423, 'Trình yêu cầu thay đổi lên Ban quản lý thay đổi.', true, 92360);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99424, 'Triển khai các thay đổi theo yêu cầu ngay lập tức.', false, 92360);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99425, 'Thiết kế lại toàn bộ dự án từ vạch xuất phát.', false, 92360);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92361, 'Ai có trách nhiệm chuẩn bị báo cáo đánh giá sau triển khai?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99426, 'Người sử dụng', false, 92361);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99427, 'Giám đốc dự án', true, 92361);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99428, 'Nhà tài trợ', false, 92361);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99429, 'Kỹ sư cao cấp', false, 92361);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92362, 'Bạn đang quản lý đội kỹ thuật là những người lao động bán thời gian. Phần lớn những người lao động này là sinh viên và có những cam kết khác trong suốt năm học. Năm ngoái bạn đã chậm trễ trong một vài dự án bởi vì bạn đã sắp xếp các dự án được hoàn tất trong suốt kỳ thi tốt nghiệp của sinh viên. Hiện nay bạn đang bắt đầu thực hiện một kế hoạch cho các dự án sắp tới và có thời hạn cuối cùng khác trong suốt giai đoạn thi tốt nghiệp. Bạn nên làm gì để ngăn chặn xung đột này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99430, 'Sử dụng các nguồn lực khác trong suốt giai đoạn thi tốt nghiệp', false, 92362);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99431, 'Sử dụng nhiều nguồn lực hơn và rút ngắn lịch trình dự án', true, 92362);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99432, 'Thuê thêm sinh viên để trợ giúp trong suốt giai đoạn thi tốt nghiệp', false, 92362);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99433, 'Sắp xếp dự án được hoàn tất sau giai đoạn thi tốt nghiệp', false, 92362);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92363, 'Bạn đang xây dựng phạm vi công việc cho một dự án sẽ sử dụng các nguồn lực kỹ thuật giới hạn. Thay đổi đã được một trong số các nguồn lực kỹ thuật yêu cầu để điều chỉnh màn ảnh đầu vào của người dùng. Cá nhân nào phải phê chuẩn yêu cầu này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99434, 'Nhà tài trợ dự án', false, 92363);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99435, 'Giám đốc dự án', false, 92363);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99436, 'Lãnh đạo đội xây dựng', false, 92363);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99437, 'Đại diện của những người dùng cuối', true, 92363);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92364, 'Bạn được bổ nhiệm là giám đốc dự án của một dự án hiện tại. Bạn đã từng ở công ty một vài năm nhưng không nằm trong phạm vi dự án này đang diễn ra. Kế hoạch quản lý dự án được đặt đúng chỗ. Dự án không vượt quá một vài ngưỡng cửa thay đổi nào đó. Khách hàng không vui với trạng thái dự án. Trong các hành động sau đây thì hành động ban đầu tốt nhất là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99438, 'Xác nhận hệ thống quản lý thay đổi đang vận hành thích hợp', false, 92364);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99439, 'Tiến hành xây dựng đội ngũ với tất cả các đối tượng liên quan dự án', false, 92364);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99440, 'Xác nhận các nhu cầu và kỳ vọng của khách hàng.', true, 92364);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99441, 'Chuẩn bị kế hoạch hành động hiệu chỉnh', false, 92364);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92365, 'Bạn là giám đốc một dự án đã bắt đầu cách đây 4 tháng. Dự án đã được bảo vệ khoảng một năm bởi phó chủ tịch bộ phận nhưng việc quản lý tài chính và trách nhiệm của nhà tài trợ đã được giao phó cho một trong những trưởng bộ phận. Một vài giám đốc khác cũng nằm trong danh sách phê chuẩn các tài liệu dự án chính. Tài liệu dự án ban đầu đã được hoàn tất và phê duyệt và dự án nằm trong lịch trình. Các yêu cầu đã được xác định, lập tài liệu và đệ trình để được sự chấp thuận trách nhiệm của nhà tài trợ. Những phê duyệt theo yêu cầu đã nhận được vào cuối ngày được phân bổ theo vòng phê duyệt. Tuy nhiên phê duyệt của một giám đốc phụ thuộc vào việc thêm ba yêu cầu quan trọng. Các yêu cầu này không lường trước được trong phạm vi dự án ban đầu cũng không phải chúng được khám phá trong suốt giai đoạn phân tích yêu cầu. Rủi ro nào bạn chắc chắn cần phải chú trọng nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99442, 'Thay đổi phạm vi dự án', true, 92365);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99443, 'Mất sự hỗ trợ của nhà tài trợ', false, 92365);
