INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92368, 'Bạn tiếp quản một dự án đang được tiến hành khoảng ba tháng. Giám đốc dự án trước yêu cầu đội dự án cung cấp các ước tính hàng tuần trong tiến trình thực hiện. Kế hoạch dự án chỉ ra 5 giai đoạn và 1.000 nhiệm vụ. Giai đoạn đầu tiên đã kết thúc và có 800 nhiệm vụ chưa hoàn thành. Trong số 800 nhiệm vụ chưa hoàn thành thì có 200 nhiệm vụ đã hoàn thành 50%. Phát biểu nào về trạng thái dự án là đúng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
