INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92402, 'Giám đốc công nghệ thông tin gửi cho kỹ sư mạng trong đội dự án ma trận của anh ta một bức thư điện tử yêu cầu anh ta chuẩn bị báo cáo kỹ thuật chi tiết cho theo một số chỉ dẫn được đưa ra trong thư điện tử. Một tuần sau, giám đốc bộ phận của kỹ sư mạng đến chỗ giám đốc dự án để phàn nàn rằng kỹ sư phải mất 45 giờ để chuẩn bị một bản báo cáo dài 80 trang. Giám đốc dự án trình bày sơ qua là anh ta nghĩ bản báo cáo sẽ chỉ dài 4 trang. Vấn đề chính có thể gây ra xung đột này là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99590, 'Thiếu chuyên môn với tư cách là kỹ sư mạng trong việc chuẩn bị tài liệu kỹ thuật.', false, 92402);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99591, 'Thiếu những chỉ dẫn được xác định trong thư điện tử tạo ra công việc ngoài phạm vi.', true, 92402);
