INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92403, 'Giám đốc dự án công nghệ thông tin được chuyển giao quy định dự án và tài liệu phạm vi phác hoạ mọi khía cạnh của dự án mới đã được công ty phê chuẩn. Giám đốc dự án công nghệ thông tin mang tài liệu này tới cuộc họp bắt đầu dự án. Trong những lựa chọn dưới đây, hãy chọn ra lựa chọn tốt nhất xem ai nên nhận tài liệu này.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99594, 'Đội dự án và các nhà tài trợ.', false, 92403);
