INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99596, 'Đội dự án và khách hàng.', false, 92403);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99597, 'Các đối tượng liên quan dự án và đội dự án', true, 92403);
