INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92405, 'Giám đốc dự án đang trải qua bất đồng giữa nhà cung cấp và đội dự án. Bằng việc điều tra tình hình, giám đốc dự án đã thấy rằng nhà tài trợ đã tăng giá cả ban đầu đã được nhất trí trong hợp đồng do nhu cầu thị trường. Phương hướng hành động nào là tốt nhất để giải quyết xung đột này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
