INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92471, 'Trong suốt giai đoạn xây dựng dự án, đội dự án đã xác định số lượng rủi ro có thể ảnh hưởng tới chất lượng của kết quả. Trước khi xây dựng kế hoạch phản ứng rủi ro, đội dự án nên:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99863, 'Không để ý đến các rủi ro bất kỳ không nằm trên đường tới hạn', false, 92471);
