INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99865, 'Phân tích khả năng mỗi rủi ro có thể xẩy ra và ảnh hưởng tiềm ẩn của từng rủi ro', true, 92471);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99866, 'Sử dụng phương pháp luận kỹ thuật duyệt và đánh giá chương trình để ưu tiên rủi ro', false, 92471);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92472, 'Trong suốt quá trình xây dựng dự án đã được phê duyệt, giám đốc dự án nhận thấy rằng phạm vi dự án không được xác định hợp lý, làm tăng lượng kinh phí đáng kể và trễ hạn các phần có thể chuyển giao. Giám đốc dự án yêu cầu một cuộc họp với các đối tượng liên quan dự án để thông báo cho họ về sự chênh lệch phạm vi theo yêu cầu.Giám đốc dự án nên tiếp cận tốt nhất biến động phạm vi cho dự án này như thế nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99867, 'Chuẩn bị cấu trúc chi tiết công việc mới chỉ ra thời gian yêu cầu cho việc hoàn tất dự án và kinh phí theo yêu cầu mới', false, 92472);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99868, 'Thông báo cho các đối tượng liên quan dự án về sự thay đổi kinh phí và lịch trình theo yêu cầu, giảm bớt các chi phí phụ với một kế hoạch dự phòng đúng chỗ và nhận được sự phê duyệt bằng văn bản cho những thay đổi yêu cầu', true, 92472);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99869, 'Thông báo cho các đối tượng liên quan dự án về thời gian và kinh phí theo yêu cầu cần để hoàn tất dự án cùng với các minh chứng về mặt tài chính như Phân tích giá trị thu được, ROI (Hoàn trả đầu tư) và biến động lịch trình', false, 92472);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99870, 'Xác định biến động chi phí và lịch trình và đề nghị phê chuẩn những thay đổi theo yêu cầu.', false, 92472);
