INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92491, 'WBS và WBS dictionary đã được hoàn thành. Đội dự án đang bắt tay vào xác định các rủi ro. Nhà tài trợ liên hệ với giám đốc dự án, yêu cầu phải có ma trậm gán trách nhiệm. dự án có ngân sách là 100.000 đô na và đặt tại 3 quốc gia với nhân số 14 người. Có một số rủi ro được dự đoán đối với dự án này và giám đốc dự án đã quản lý rất nhiều dự án tương tự. Điều tiếp theo nên làm là?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
