INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99945, 'make sure the project scope í defined (chắc chắn rằng phạm vi dự án đã được xác định)', false, 92491);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99946, 'complete risk management and issue the responsibility assignment matrix (hoàn thành quản lý rủi ro và phát hành ma trận gán trách nhiệm)', false, 92491);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92492, 'Giám đốc dự án không có nhiều thời gian dành cho việc lên kế hoạch trước ngày bắt đầu dự án (cố định, bắt buộc). bởi vậy anh ta muốn thực hiện giai đoạn lên kế hoạch một cách hiệu quả nhất có thể. Điều nào sau đây nên được thực hiện?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99947, 'Đảm bảo rằng bạn đã hoàn thành bản báo cáo phạm vi dự án sơ bộ và sau đó bắt đầu làm WBS', true, 92492);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99948, 'tạo một danh sách hoạt động trước khi tạo một sơ đồ network', false, 92492);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99949, 'lập tài liệu về tất cả các rủi ro đã biết trước khi lập tài liệu về các giả tưởng ở mức cao', false, 92492);
