INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92493, 'Những ràng buộc lập lịch cấp cao vừa được xác định, vậy bạn đang ở trong nhóm tiến trình nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
