INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92494, 'Giám đốc dự án chắc chắn rằng sản phẩn của dự án đã được hoàn thành theo như bản kế hoạch quản lý dự án. Vậy anh ta đang ở trong giai đoạn nào của tiến trình quản lý dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
