INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99958, 'closing (giám sát và kiểm soát)', true, 92494);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92495, 'Giám đốc dự án nhận được 1 cuộc gọi từ một thành viên đội, lưu ý anh ra rằng có mâu thuẫn giữa tốc độ của hệ thống trong dự án và tốc độ mong muốn (hoặc tốc độ đề ra). Nếu giám đốc dự án sau đó đánh giá xem mâu thuẫn đó có cần phải đối phó hay không, thì anh ta đang ở trong pha nào của tiến trình quản lý dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
