INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99962, 'closing (giám sát và kiểm soát)', false, 92495);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92496, 'Một thanh viên đội dự án lưu ý PM rằng các hoạt động bao gồm một gói công việc là không còn phù hợp. vậy tốt nhất PM nên thuộc phần nào của tiến trình quản lý dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
