INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99966, 'project closing', false, 92496);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92497, 'Trong cuộc họp đội dự án, một thành viên hỏi về phép đo sẽ được sử dụng cho việc đánh giá hiệu năng dự án. Thành viên này cảm thấy một số phương pháp liên quan tới các hoạt động mà anh ta được giao là không đúng. Pha tốt nhất mà dự án nên ở vào lúc này là?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
