INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99970, 'initiating', false, 92497);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92498, 'Trong quá trình hoàn thành các gói công việc, nhà tài trợ yêu cầu PM báo cáo về tiến độ dự án. Để chuẩn bị cho bản báo cáo, PM yêu cầu các thành viên thông báo lại phần trăm hoàn thành công việc của họ. Trong đội có một thành viên “khó bảo”. Trả lời lại yêu cầu của PM, anh ta hỏi lại: “Phần trăm hoàn thành của cái gì cơ?”. Mệt mỏi với những câu kiểu như vậy, PM báo cáo lại với sếp của thành viên đó rằng anh ta có thái độ hợp tác. Điều nào sau đây mới là vấn đề thực sự?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99971, 'the project manager did not get buy-in from the manager for the resources on the project', false, 92498);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99972, 'the project did not create and adequate reward system for team members to improve their cooperation', false, 92498);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99973, 'the project manager should have had a meeting with the team member’s boss the first time the team member caused trouble.', false, 92498);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (99974, 'The project manager does not have work packages.', true, 92498);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92499, 'Sự tương ứng, những thay đổi hợp đồng và các yêu cầu phải trả là ......của quản lý hợp đồng', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
