INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92509, 'Những vấn nào sau đây mô tả chính xác nhất vai trò của PM trong việc tích hơp?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
