INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92511, 'Bạn là 1 PM mới mà trước đây chưa bao giờ bạn quản lý 1 dự án nào. Bạn đã được yêu cầu lên kế hoạch 1 dự án mới. Điều gì là tốt nhất trong tình hình này dựa vào ______ quá trình lập kế hoạch để cải thiện cơ hội thành công', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100023, 'A.Sự hiểu biết và training của bạn', false, 92511);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100024, 'B.Phân tích các bên liên quan', false, 92511);
