INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100030, 'D.Phạm vi dự án', false, 92512);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92513, 'Một PM quản lí một hợp đồng giá cố định. Cố ấy nghĩ rằng đây là một khách hàng lớn- các yêu cầu thay đổi có thể ảnh hưởng tới kế hoạch của dự án. Cô ấy nên làm điều gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
