INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92514, 'Khi hoàn thành xong một dự án, PM nhận thấy rằng a ấy cần giảm bớt chi phí của dự án. Sau khi xem xét các lựa chọn của anh ấy, a ấy quyết định đưa ra các lựa chọn sau. Với sự lựa chọn nào làm giảm bớt chi phí của dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100035, 'Thay đổi thành phần A từ thành phần B. Thành phần A có giá khá cao cho việc mua bán, nhưng lại có giá các vòng đời thấp hơn B', false, 92514);
