INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92535, 'Trong suốt cuộc họp của đội dự án, 1 thành viên của đội đề nghị mở rộng phạm vi dự án cái mà dựa trên phạm vị trong tôn chỉ của dự án. Đầu ra của quản lý dự án cái mà đội dự án cần tập trung để hoàn thành tất cả công việc và chỉ các công việc yêu cầu. Đó là ví dụ của', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
