INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92537, 'Một dự án thì gần như đã hoàn thành xong.Dự án không đúng với tiến độ 300(đơn vị thời gian) và không đúng với chi phí là 900(đơn vị chi phí).Nhưng một trong những kiểm tra quản lý chất lượng đã hoàn thành và những yêu cầu về chất lượng của các thành phần đã được đáp ứng.Tất cả chất lượng trong bản ghi chất lượng đã được giải quyết.Nhà tài trợ gọi để chuẩn bị 1 cuộc họp xác minh sản phẩm khi khách hàng thông báo muốn thực hiện 1 thay đổi lớn trong phạm vi dự án.Việc nên làm:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
