INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92538, 'Bạn vừa tham gia văn phòng quản lý dự án sau 5 năm làm việc trong các dự án.một trong nhưng điều bạn muốn giới thiệu với công ty của bạn là cần phải làm các WBS.Một vài người PM đang tức giận mà bạn yêu cầu họ làm thêm WBS.Việc nào sau đây là tốt nhất để nói cho các PM để thuyết phục họ sử dụng WBS', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
