INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92610, 'Đầu tiên trong chu trình dự án của bạn, bạn có 1 cuộc thảo luận với nhà đầu tư về việc ước lượng những công nghệ sẽ được sử dụng. Bạn muốn có 1 cái nhìn tổng quát nhưng nhà đầu tư tranh cãi về những ước lượng tương tự. ý kiến nào tốt nhất:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
