INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92611, 'Bạn cần phải hoàn thành tiến trình khởi tạo của 1 dự án nhỏ và có thể thay đổi trong suốt quá trình lập kế hoạch khi các bên liên quan của dự án hỏi bạn về chi phí của dự án và đường chi phí cơ sở. Bạn cần nói với họ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100422, 'Ngân sách dự án có thể được đưa ra trong tôn chỉ của dự án, cái cần phải hoàn thành ngay.', false, 92611);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100423, 'Ngân sách dự án và đường chi phí cơ sở sẽ không thể hoàn thành và chấp nhận trừ khi tiến trình lập kế hoạch được hoàn thành', true, 92611);
