INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92614, 'Để cung cấp 1 dự án mới trong bộ phận của bạn, bạn cần phải chuyển tài nguyên từ 1 dư án sang dự án khác, Vì bộ phận của bạn đang làm việc năng xuất, việc chuyển tài nguyên từ dự án nào chắc chắn sẽ làm trì hoãn dự án đó. Nó sẽ gây ra những tác động tiêu cực nhất nếu bạn chuyển tài nguyên từ dự án sau :', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100434, 'Dự án A với tỉ lệ lợi nhuận trên chi phí là 0,8 , không có điều kệ dự án và bốn nguồn tài nguyên', true, 92614);
