INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92615, 'Một dự án sản xuất có chỉ số tiến độ thực hiện (SPI) là 0,89 và chỉ số chi phí thực hiện (CPI) là 0,91, Nói chung đâu là giải thích tốt nhất vì sao lại xảy ra tình trạng trên:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
