INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92616, 'Mặc dù các bên liên quan nghĩ rằng đã có đủ tiền trong ngân sách, một nửa thông qua chỉ số chi phí thực hiện dự án (CPI) là 0,7. Để xác định nguyên nhân gốc rễ, một vài bên liên quan tiến hành kiểm toán dự án và phát hiện ra ngân sách chi phí dự án được ước tính một cách tương tự. Tất cả các hoạt động dự toán làm tăng dự toán của dự án. Các bên liên quan nghĩ có gì đó đã bị bỏ quên trong quá trình hoàn thành ước tính dự án. Điều nào dưới đây mô tả những gì đã bị bỏ quên :', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
