INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92629, 'Khi lên kế hoạch cho dự án của mình , bạn đặt yếu tố nào lên hàng đầu :chất lượng , chi phí hay lịch hoàn thành?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
