INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92631, 'Một giám đốc dự án cùng đội ngũ làm việc từ một công ty thiết kế trang thiết bị đường sắt được yêu cầu thiết kế một loại máy để chất đá từ đường ray lên xe. Người ta cho phép máy làm rơi 2% đá trong quá trình vận hành, trên tổng số hơn 2 tấn đá rơi trên đường ray mỗi ngày.Giám đốc dự án sẽ sử dụng tài liệu nào để minh chứng cho kiểm soát chất lượng,bảo đảm chất lượng, cải tiến chất lượng trong dự án này ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
