INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92633, 'Đội dự án đã tạo một kế hoạch mô tả cách họ thực thi các điều khoản đảm bảo chất lượng.Nội dung chủ yếu liên quan tới cấu trúc của tổ chức,trách nhiệm , các thủ tục và các thông tin khác về kế hoạch quản lí chất lượng. Nếu nó thay đổi trong quá trình thực hiện dự án , điều nào dưới đây cũng sẽ thay đổi ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
