INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92640, 'Giám đốc dự án mới đảm nhận dự án từ giám đốc dự án cũ trong thời gian thực hiện dự án.Giám đốc dự án tiền nhiệm đã tạo ngân sách dự án , xác định các yêu cầu truyền thông và đi dần tới hoàn thiện gói công việc. Vị giám đốc dự án mới cần làm gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
