INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92642, 'Khi dự án kết thúc , giám đốc dự án xác định là dự án có thêm 4 chức năng và thêm 3 mục công việc. Khách hàng rất hài lòng. So với “ thành công của 1 dự án “ , điều này có nghĩa thế nào ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
