INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92643, 'Trong quá trình thực hiện dự án , một thành viên của đội dự án thông tin cho giám đốc dự án là các gói công việc không đáp ứng được yêu cầu chất lượng. Giám đốc dự án đã gặp gỡ tất cả những người có liên quan tới vấn đề này để phân tích .phần nào trong tiến trình quản lí chất lượng mà giám đốc dự án có liên quan tới ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
