INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92654, 'bạn vừa được chỉ định làm quản lý dự án cho một dự án viễn thông lớn. Dự án này một năm thực hiện được khoảng 1 nửa . Các nhóm dự án bao gồm 5 người bán hàng và 20 nhân viên của công ty bạn. Bạn muốn hiểu xem ai có trách nhiệm làm gì trong dự án. Bạn sẽ tìm thấy thông tin đó ở đâu ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
