INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92655, 'Người quản lí dự án công bố kế hoạch dự án.Các hoạt động,thời gian bắt đầu,thời gian kết thúc ,tài nguyên được nhận biết.PM nên làm gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
