INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92657, 'Trong mỗi cuộc họp của dự án,PM hỏi mỗi thành viên trong đội để miêu tả công việc mỗi người làm,PM giao cho mọi người công việc mới.Độ dài của các cuộc họp sẽ tăng lên bởi vì rất nhiều các công việc được gán..Những nguyên nhân nào sau đây sẽ xảy ra loai trừ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
