INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92658, 'Bạn là PM lãnh đạo đội dự án cross-functional trong điều kiện ma trận yếu.Các thành viên báo cáo cho bạn các hàm,bạn không trực tiếp thưởng cho họ.Dự án rất khó khăn,những ràng buộc thời gian dày đặc,khó khăn về tiêu chuẩn chất lượng.Những loại năng lực nào của PM sau đây ảnh hưởng nhất tới vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100610, 'Sự liên quan', false, 92658);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100611, 'Chuyên môn', true, 92658);
