INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100613, 'Chính thức', false, 92658);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92659, 'Thành viên của đội không thực hiện tốt trong dự án,vì cô ấy không có kinh nghiệm trong việc phát triển hệ thống.Không ai nói rõ công việc để làm.Giải pháp tôt nhất của PM là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100614, 'Hỏi ý kiến quản lí chức năng động viên sự hoàn thành dự án cho các thành viên trong đội', false, 92659);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100615, 'Giành được tài nguyên mới có kĩ năng hơn trong việc phát triển', false, 92659);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100616, 'Sắp xếp các thành viên trong đôi để đào tạo lại', true, 92659);
