INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92660, 'PM mới tìm được 1 bản hợp đồng con cho dự án của cô ấy.Thành viên trong dự án phản hồi các phần của dự án không theo bản hợp đồng.Để giải quyết vấn đề này,PM nói:”bạn sẽ từ bỏ 1 vài thứ để giải quyết vấn đề này”.Phương pháp giải quyết xung đột nào cô ấy sẽ sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100618, 'Sự đương đầu', false, 92660);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100619, 'Sự thỏa hiệp', true, 92660);
