INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100621, 'Giao tiếp', false, 92660);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92661, 'Dự án có 1 vài đội,đội C làm lỡ mất deadline trong quá khứ.Nguyên nhân do đội D phá vỡ những chỉ trích từ những lần trước.Là người lãnh đạo đội D,ban nhận văn bản của deadline sắp tới cũng bị lỡ,bạn nên gặp:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100622, 'Quản lí đội D', false, 92661);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100623, 'gặp mình quản lí dự án', false, 92661);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100624, 'quản lí và quản lí dự án', false, 92661);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100625, 'quản lí dự án và lãnh đạo đội C', true, 92661);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92662, 'Giám đốc và cả đội dự án đều mong chờ dự án mới.Đây là nhiệm vụ quản lý dự án đầu tiên.Đội dự án cảm thấy họ sẽ có khả năng hoàn thành công việc mà họ chưa được làm trước đây bao giờ.Có 29 người góp phần để miêu tả sản phẩm và đội dự án có 9 chuyên gia nhiều kinh nghiệm trong lĩn vực của họ.Đi qua một phần kế hoạch ,ba nhóm của đội ngũ kỹ thuật đang bất đồng ý kiến về phạm vi của hai phát biểu.Một nhóm chỉ vào WBS dự thảo và nói rằng các gói công việc cần được bổ sung thêm.Một nhóm nói rằng các gói công việc đặc biệt không nên được làm.Thành viên trong nhóm thứ ba đồng ý với cả 2 nhóm trên,Giám đốc dự án tốt nhất nên giải quyết xung đột như thế nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100626, 'Anh ta nên lắng nghe các quan điểm khác nhau,xác định lựa chọn tốt nhất,và thực hiện sự lựa chọn đó.', false, 92662);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100627, 'Anh ta nên hoãn lại các cuộc thảo luận,gặp gỡ các cá nhân và xác định phương pháp tốt nhất.', false, 92662);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100628, 'Anh ta nên lắng nghe các quan điểm khác nhau,động viên thảo luận hợp lý,và tạo điều kiện thuận lợi cho một thỏa thuận.', true, 92662);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100629, 'Anh ta sẽ giúp các nhóm tập trung vào khía cạnh thích hợp với quan điểm của họ,và xây dựng sự thống nhất bằng cách giảm bớt sự căng thẳng và xây dựng nhóm tiêu điểm chung.', false, 92662);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92663, 'Dự án vừa được bắt đầu và gồm 14 người ở những ban khác nhau.Hợp đồng được kí bởi một người và gồm hơn 30 yêu cầu chính phải được đáp ứng trên dự án.Các nhà tài trợ thông báo cho người quản lý dự án răng SPI phải được giữ giữa 0,95 và 1,1.Vài phút khảo sát kết quả của 34 người giữ tiền đặt cọc và các mục tiêu tiến độ của dự án bị hạn chế.Một giám đốc dự án vừa mới được thuê.Loại quyền lực quản lý dự án nào sau đây tốt nhất giúp giám đốc dự án đạt được sự hợp tác của những người khác?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100630, 'Chính thức', true, 92663);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100631, 'Ám chỉ', false, 92663);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100632, 'Hình phạt', false, 92663);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100633, 'Chuyên gia', false, 92663);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92664, 'Giám đốc dự án đang cố gắng hòa giải cuộc tranh luận giữa 2 nhóm thành viên.Một nhóm nói hệ thống nên được tích hợp trước khi kiểm thử và nhóm còn lại cho rằng mỗi hệ thống nên được kiểm thử trước khi tích hợp.Dự án gồm hơn 30 người,và có 12 hệ thống cần được tích hợp.Các nhà tài trợ đang yêu cầu việc tích hợp phải xảy ra cùng một thời gian.Ý kiến tốt nhất của giám dự án có thể làm để giải quyết xung đột là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
