INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100636, 'Hãy giải quyết điều này một lần nữa vào tuần tới sau khi tất cả chúng ta bình tĩnh', false, 92664);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100637, 'Chúng ta hãy làm kiểm thử có giới hạn trước khi tích hợp và hoàn thành kiểm thử sau khi tích hợp', true, 92664);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92665, 'Một dự án là ở giữa các quá trình thực hiện khi một bên liên quan đề xuất một sự thay đổi mới.Sự thay đổi này sẽ gây ra 3 sự đại tu chính của dự án.Cúng lúc,giám đốc dự án phát hiện ra rằng một gói công việc chính đã không hoàn thành vì thành viên trưởng nhóm đã chuyển đến một dự án có mức ưu tiên cao hơn.Người nào sau đây tốt nhất cho giám đốc dự án để giải quyết những vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
