INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92667, 'Khi làm việc trên các dự án đang được tiến hành ,giám đốc dự án nghe được 2 nhân viên tranh cãi về một bộ tài liệu hướng dẫn.Giám đốc dự án điều tra và phát hiện ra rằng bộ tài liệu cho việc xây dựng móng bê tông đang được đổ được dịch kém cỏi giữa những ngôn ngữ khác nhau đang sử dụng trên dự án.Điều nào sau đây là tốt nhất để giám đốc dự án làm trước tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
