INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92670, 'Có một dự án được thử thách để quản lý.Mối người được thúc đẩy hoàn thành dự án trong một khoảng thời gian.Nhưng đáng tiếc, căng thẳng đã xảy ra đên độ các buổi hpj nhóm đều la hét,hỗn loạn và ít công việc được thực hiện trong suốt buổi họp .Một thành viên của nhóm yêu cầu được xin lỗi trong các buổi họp nhóm trong tương lai.Như tất cả đang lật đổ anh ấy.Trong lúc ấy ,nhà tài trợ đã yêu cầu tham dự cuộc họp nhóm trên để hiểu rõ hơn cách thực hiên dự án và các khach hàng đã bắt đầu thảo luận về việc thêm pham vi dự án!trong tinh huông này điều gì là tốt nhất cho PM', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
