INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92683, 'Dự án truyền thông 1 năm đã đi được nửa đoạn đường khi bạn thay thế chỗ giám đốc dự án trước. Dự án kéo theo 3 khách hàng khác nhau và đội dự án 30 người. Bạn muốn biết được các yêu cầu truyền thông và loại công nghệ nào được sử dụng để hỗ trợ trong truyền thông dự án. Bạn tìm ở đâu những thông tin đó', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
