INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92685, 'Thông tin dự án được phân phối dựa theo kế hoạch quản lý truyền thông. Một số sản phẩm bàn giao dự án bị thay đối tương ứng với kế hoạch quản lý dự án. Một nhà tài trợ đã biểu thị sự ngạc nhiên với giám đốc dự án đối với sự thay đổi sản phẩm bàn giao đã công bố trước đó. Tất cả các nhà tài trợ khác đều nhận được sự liên lạc bao gồm sự thông báo thay đổi. Giám đốc dự án nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100717, 'Xác định tại sao bên tài trợ không nhận thông tin và cho nhà tài trợ đó biết thông tin được công bố', false, 92685);
