INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92686, 'Truyền thông là chìa khóa sự thành công của dự án. Với tư cách là một giám đốc dự án, bạn có 3 nhà tài trợ mà bạn phải liên lạc. Bạn có 6 kênh truyền thông. Một nhà tài trợ mới của bạn mới tham gia nên bạn phải liên lạc với họ. Có bao nhiêu kênh mà bạn có hiện giờ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
