INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92687, 'Hai người tranh luận với nhau cái gì cần thiết để hoàn tất gói công việc. Nếu giám đốc dự án muốn biết cái gì đang diễn ra, cô ấy phải chú ý nhiều nhất vào:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100725, 'Đang nói gì và khi nào', false, 92687);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100726, 'Đang nói gì, ai nói và khi nào trong ngày', false, 92687);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100727, 'Sự lịch sự và họ nói những gì', false, 92687);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100728, 'Độ cao và âm của giọng, và sự lịch sự', true, 92687);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92688, 'Giám đốc dự án có một đội dự án bao gồm người đến từ 4 quốc gia. Dự án rất quan trọng cho công ty, và giám đốc dự án quan tâm đến sự thành công của nó. Độ dài lịch làm việc của dự án có thể chấp nhận được. Loại phương pháp truyền thông nào mà anh ta nên sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100729, 'Giao ước không hình thức', false, 92688);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100730, 'Văn bản hình thức', true, 92688);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100731, 'Giao ước hình thức', false, 92688);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100732, 'Văn bản không hình thức', false, 92688);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92689, 'Tình trạng cuộc họp dự án không tốt lắm. Mọi người đang nói cùng một lúc, có nhiều người không tham gia và có nhiều đề tài được tranh luận một cách hỗn độn. Quy tắc nào dưới đây cho các cuộc họp có hiểu quả ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100733, 'Chứng tỏ sự nhã nhặn và sự chú ý lẫn nhau, điều khiển ai được cho phép để nói', false, 92689);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100734, 'Lịch họp ở mức nâng cao', false, 92689);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100735, 'Có một mục đích cho cuộc họp, với sự phục vụ đúng người', false, 92689);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100736, 'Tạo và công bố đề tài thảo luận và tập hợp các luật, quy định để điều khiển của họp mặt', true, 92689);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92690, 'Bạn được phân công làm giám đốc dự án cho một dự án sản xuất lớn. Dự án một năm đã hoàn thành một nửa. Nó kéo theo 5 khách hàng khác nhau và 20 thành viên của công ty bạn trong đội dự án. Bạn muốn nhanh chóng xem xét dự án đang đứng ở đâu. Loại báo cáo nào duới đây có hữu ích nhất trong việc tìm thông tin như vậy?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100737, 'Tình trạng công việc', false, 92690);
