INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100739, 'Dự báo', false, 92690);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100740, 'Truyền thông', false, 92690);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92691, 'Đội dự án đang đi thăm nhà máy sản xuất của một trong số các nhà cung cấp. Điều nào dưới đây là điều quan trọng nhất cần thực hiện trong bất kỳ cuộc gọi điện thoại cho giám đốc dự án , được thực hiện bởi thành viên đội dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100741, 'Hỏi xem thành viên đội dự án phản hồi lại điều mà giám đốc dự án nói.', true, 92691);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100742, 'Xem xét lại danh sách thông tin liên lạc của tất cả các nhà tài trợ', false, 92691);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100743, 'Hỏi các thành viên đội dự án xem có thay đổi yêu cầu không', false, 92691);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100744, 'Xem xét lại lịch cuộc họp sắp tới', false, 92691);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92692, 'Một giám đốc dự án (PM) nghe được một cuộc nói chuyện giữa 2 bên liên quan – những người đang nói về sự không vui của họ cùng với những ảnh hưởng trên bộ phận của họ, A nói: nếu dự án này thực hiện đúng thời gian và B trả lời: SPI là 1.05. bên A hỏi nếu PM của dự án biết được sự liên quan của B. B trả lời : “anh ta không dảm bảo”. trong trường hợp này, PM cần làm gì là tốt nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100745, 'Để cho A và B biết được PM nghe được cuộc nói chuyện này và hỏi họ để giải quyết trực tiếp bất kỳ câu hỏi nào', false, 92692);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100746, 'tổ chức một buổi gặp mặt có tất cả những bên liên quan để thông báo về tình trạng hiện tại của dự án', false, 92692);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100747, 'gửi cho A, B một bản sao của các bản ghi và đề nghị họ viết comments', false, 92692);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100748, 'tổ chức một buổi gặp mặt với A, B để cho phép họ nói lên những vấn đề của họ', true, 92692);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92693, 'Sự tương ứng, những thay đổi hợp đồng và các yêu cầu phải trả là ......của quản lý hợp đồng', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
