INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100751, 'Chức năng', false, 92693);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100752, 'Đầu vào', false, 92693);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92694, 'một giám đốc dự án (PM) được giao nhiệm vụ quản lý 4 dự án của công ty và đang được xem xét để tham vào nhóm quản lý văn phòng của dự án. Sau đây là quá trình công việc của anh ta. Dự án đầu tiên có sự sai lệch chi phí là -500, được dùng 2 tài nguyên quan trọng, cần thiết để làm lại các phần của dự án trong quá trình thực hiện dự án và có thứ tự ưu tiên thứ 14 của công ty. Dự án thứ 2 kết thúc với sai lệch thời hạn là +100, được hoàn thành với sự rút ngắn thời hạn ban đầu và nhận được một lá thư khen ngợi từ nhà tài trợ, nhưng sản phẩm của dự án không dùng được. dự án thứ 3 có hơn 23% thay đổi so với dự kiến, có một SPI là 0.90 và 25 tệp mở trong vấn để đăng nhập khi dự án đã hoàn thành.Mỗi dự án có kinh phí là 1.000$ và có từ 20% đến 28% thay đổi so với dự kiến. mô tả nào sau đây tốt nhất để giải thích tại sao điều này lại xảy ra?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100753, 'Giám đốc dư án chỉ được quản lý dự án mức ưu tiên thấp và anh ta đã rút ngắn thời hạn và điều này thể hiện anh ta không có kỹ năng làm việc trong việc quản lý văn phòng của dự án', false, 92694);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100754, 'Các vấn đề đăng nhập không nên được dùng trong dự án quy mô như thế này, thể hiện anh ta không có kỹ năng là một giám đốc dự án', false, 92694);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100755, 'Một PM làm việc không hiệu quả (bao gồm cả các bên liên quan), thể hiện rằng anh ta không có kiến thức trong quản lý dự án', true, 92694);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100756, 'Giám đốc dự án có 2 tài nguyên quan trọng trong đội ngũ của họ và vẫn cần lặp lại các giai đoạn trong quá trình thực hiện dự án, thể hiện rằng anh ta khôn có kỹ năng trong quản lý văn phòng của dự án', false, 92694);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92695, 'Trong quá trình thực hiên dự án ,mọi thứ đang thực hiện đúng theo yêu cầu.Hệ thống ủy quyền làm việc cho phép mọi người biêt khi nào cần bắt đầu công việc và việc đăng nhập giúp mọi người theo dõi yêu cầu các bên liên quan.Tỉ lệ lợi nhuận được cải thiện và các nhà tài trợ đưa ra đánh giá nỗ lực của họ cho mỗi thành viên trong đội bằng các mốc lưu trữ.Người quản lí dự án đưa ra ý kiến cho các thàn thành viên để thu được kết quả từ việc hoàn thành của người công việc của họ là sau 2 ngày.Câu nào là đúng nhất trong các câu sau.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100757, 'Người quản lí dự án tập trung vào các yêu cấu của khach hàng', false, 92695);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100758, 'Quản lí chức năng không bao gồm kế hoạch quản lí truyền thông', true, 92695);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100759, 'Hoạt động của người thành công nên được xem xét,không phải là nhừng người tiền nhiệm', false, 92695);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100760, 'Người không được cho vào mốc quan trọng', false, 92695);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92696, 'Có nhiều gói công việc kết thúc thành công trong dự án và khách hàng đưa ra 1số tiêu chuẩn để đánh giá.Dự án dựa trên lịch trình đã đế ra khi khi các kế hoạch hoạt động quan trọng bị trở ngại.Chỉ còn 4 người cho dự án.Có 2 thành viên khác được chuyển sang nếu cần. Người quản lí dự án nhận 3 thành viên khácmà họ đang cố gắng được chuyển vào dự án bởi vì họ thấy dự án không có khả năng thành công.Khi người quản lí theo du án này thì họ nghiên cứu để các thành viên đó giao tiếp mà không cần có dịa chỉ.Câu nào đúng nhất', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100761, 'Có các nhân viên túc trực để giúp đỡ khi gặp khó khăn', false, 92696);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100762, 'Điều tra lý do tại sao tiến độ dự án là tích cực', false, 92696);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100763, 'Xem ai có thể thay thế 3 thành viên đó', false, 92696);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100764, 'Tạo ra một vấn đề đăng nhập mới', true, 92696);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92697, 'Một dự án có 13 thành viên và có ảnh hưởng tới 15 bộ phận trong công ty. Đến giờ dự án được hoàn thành 20% và có bản ghi thực thi thành công từ 5 bộ phận ảnh hưởng, PM tổ chức party để ăn mừng. PM mời đến party những bên liên quan chủ chốt trong dự án để cho họ thấy được thnafh quả đạt được.Tại party đó, PM cố gắng gặp gỡ thêm các đối tác có thể giúp cho dự án thành công hơn. Anh ta vô tình nghe được một quản lý trong số các bộ phận đang nói về việc thiết lập các buổi gặp mặt thường xuyên hơn trong dự án, điều tốt nhất mà PM nên làm đầu tiên là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100765, 'ghi lại hiệu quả của buổi party này', false, 92697);
