INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92699, 'dự án của bạn có một thời gian khó khăn nhận được phê duyệt của kế hoạch quản lý dự án vì có một số bên liên quan mà yêu cầu của họ không được phê duyệt trong dự án. Những bên liên quan này đã tổ chức và tổ chức lên dự án trong khi họ tổ chức buổi gặp mặt sau khi gặp gỡ về các các yêu cầu của họ. Dự án này cuối cùng được phê duyệt và công việc được bắt đầu 6 tháng trước. tất cả những phát biểu nên được dự phòng để thực thi TRỪ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
