INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92700, 'PM đang mong đợi một giải pháp được gửi từ e-mail của một thành viên trong hôm nay. Vào cuối ngày, PM này liên lạc với thành viên của đội vì chưa nhận được thư. Nhân viên này xin lỗi và nói là anh ta không thể gửi thư, và nó sẽ được gửi qua mail. Nhân viên này giải thích rằng anh ta đã thông báo với PM về sự việc này trong suốt cuộc điện thoại trong khi PM đang đi du lịch và PM không thể nghe rõ vì sóng ở đó yếu, điều gì có thể tránh được vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
