INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92721, 'PM tập hợp đội dự án, xác định 56 rủi ro trong dự án, xác định được cái gì sẽ kích hoạt các rủi ro, ma trận chỉ số rủi ro, kiểm tra các giả định và đánh giá chất lượng dữ liệu sử dụng.Team tiếp tục chuyển qua tiến trình quản lý rủi ro.PM đó đã quên làm gì', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
