INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92722, 'Bạn là 1 PM cho dự án xây dựng 1 nhà máy mới, mà trước đó bạn chưa làm bao giờ. Chi phí dự án ước tính là 30.000.000$ và có thể có 3 người đầu tư vào.Khi bắt đầu, dự án không thể hủy bỏ, sẽ có chi phí lớn về nhà máy và thiết bị.Với tư cách là PM , bạn phải cẩn thận ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
