INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92723, 'Trong kế hoạch quản lí rủi ro.đôi của bạn phát hiện ra 434 rủi ro và 16 nguyên nhân chính của các rủi ro đó.Dự án là khâu cuối cùng của một loạt các dự án mà nhóm làm việc với nhau.Nhà tài trợ rất ủng hộ và nhiều lần dành nhiều thời gian để đảm bảo dự án được hoàn thành và ký bởi các bên liên quan Trong kế hoạch dự án,nhóm không thể phát hiện ra cách tốt nhất để làm giảm bớt hay đảm bảo chống lại rủi ro.Đó không phải là công việc mà có thể thuê ở bên ngoài được và cũng không thể xóa bỏ được.Cách giải quyết tốt nhất là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
