INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92724, 'Người quản lí dự án sẽ xác định rủi ro trong dự án của họ.Một vài rủi ro vượt ngoài mong đợi của họ,nhưng họ vẫn mong rủi ro đó nằm trong các rủi ro đã được liệt kê trước đó.Điều này có thể thực hiện như thế nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
