INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92725, 'Một nhà quản lí dự án có kinh nghiệm chỉ bắt đầu công việc cho một máy tích phân (Integrator)công nghệ thông tin lớn.Người quản lí của họ cung cấp cho họ một bản nháp tôn chỉ dự án và ngay lập tức hỏi cô đưa ra phân tích rủi ro của dự án.Cái nào sau đây sẽ giúp đỡ tốt nhất cho sự cố gắng này', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
