INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92726, 'Bạn được bổ nhiệm làm giám đốc của một dự án mới, qui mô lớn và phức tạp. Bởi vì dự án này bussiness-critical( nghiệp vụ quan trọng)và rất rõ ràng,những người quản lí yêu cầu bạn phải phân tích rủi ro của dự án và chuẩn bị chiến lược đáp ứng cho họ càng sớm càng tốt.Những tổ chức có chiến lược quản lí rủi ro thường ít khi được sử dụng hoặc được tuân theo và có một lịch sử của việc quản lí rủi ro tồi.Mốc đầu tiên của dự án trong vòng 2 tuần.Trong việc chuẩn bị kế hoạch đáp ứng rủi ro đầu vào từ cái nào dưới đây thường ít quan trọng nhất:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
