INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92727, 'Bạn đang thực hiện một dự án trong vòng 2 năm để triển khai một công nghệ mới tới lĩnh vực văn phòng trên toàn quốc. Một cơn bão gây ra sự mất điện khi quá trình hoàn thiện dự án gần hoàn tất. Khi có điện trở lại, toàn bộ báo cáo và dữ liệu lịch sử của dự án bị mất mà không có cách nào khôi phục lại. Điều nào nên làm để giảm bớt rủi ro đó?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
