INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92729, 'Chỉ số hiệu năng chi phí(CPI) của một dự án là 0,6 và chỉ số hiệu năng kế hoạch(SPI) là 0,71.Dự án này có 625 gói công việc và được hoàn thành trong kỳ hạn 4 năm.Các thành viên trong nhóm rất thiếu kinh nghiệm và dự án nhận được rất ít hỗ trợ cho việc lập kế hoạch đúng đắn.Điều nào tốt nhất nên làm ở dưới đây:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
