INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92736, 'Một dự án sinh ra một số vấn đề, nhưng bây giờ có vẻ đã kiểm soát được. Trong những tháng cuối của dự án gần như tất cả các dự trữ đã được sử dụng hết và hầu hết các tác động tiêu cực của sự kiện đó đã được dự đoán có xảy ra.Nó chỉ có bốn hoạt động trái và hai trong số đó nằm trên đường tới hạn.Quản lí quan trọng bây giờ thông báo cho người quản lý dự án rằng nếu có thể vì lợi ích tốt nhất của tổ chức thực hiện để hoàn thành dự án trước hai tuần sớm hơn dự kiến để nhận được một phản ứng profit.In bổ sung, quản lý dự án gửi các yêu cầu đề nghị cho một số tha làm việc nhóm đã được đi làm, với hy vọng rằng một công ty khác có thể b có thể làm người quản lý công việc dự án nhanh chóng.Người quản lí dự án có thể được nói cho là cố gắng để làm việc với: CÂU NÀY DỊCH THẤY CHUỐI NHƯNG CHẲNG BIẾT DỊCH NTN CHO XUÔI CẢ Trung ạ', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100920, 'Cơ hội', true, 92736);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (100921, 'Dự trữ', false, 92736);
