INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92762, 'nhóm dự án có vẻ như đã tranh cãi về bất cứ thứ gì mà họ đã thảo luận. May mắn là người quản lý dự án đã thiết lập một hệ thống khen thưởng và các buổi họp xây dựng nhóm, cái mà sẽ giúp đỡ và khuyến khích nhóm hợp tác hơn. Cái gần đây nhất họ tranh cãi với nhau là về việc : phần nào trong tiến trình mua bán phải được cho vào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
