INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92764, 'Quản lý chương trình của bạn đã gặp bạn,PM để cần giúp đỡ về giá thầu cho 1 dự án mới của anh ta.Bạn muốn bảo vệ công ty của bạn khỏi những rủi ro về tài chính.Bạn giới hạn trong việc định nghĩa phạm vi.Kiểu hợp đồng tốt nhất bạn nên chọn là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
