INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92765, 'Đàm phán giữa 2 bên đang trở nên phức tạp hơn.vì vây phía bên A làm 1 vài điều khoản để cho cả 2 bên ký.Ngoài ra,khi công việc đang được thực hiện,bên B mong muốn rằng họ không bị yêu cầu phải cung cấp thêm item mà họ cùng đống ý trong quá trình đàm phán.bời vì nó không nằm trong bản hợp đồng tiếp theo.Trong trường hợp này bên B là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
