INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92766, 'dự án của bạn vừa mới được nhanh chóng được vạch ra và bạn đang tìm kiếm một nhà thầu phụ để hoàn thành hợp tác nhanh chóng .không có thời gian để ra yêu cầu đề nghị , vì vậy bạn chọn một công ty mà trước đây bạn đã hợp tác nhiều lần cho phát triển phần mềm .một mối quan tâm chính trong vấn đề này là :', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
