INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92767, 'quản lý dự án và nhà tài trợ dự án đang thảo luận các chi phí dự án và cho dù đó là tốt hơn nếu công ty riêng của họ làm chủ một phần của dự án hoặc thuê một công ty khác để làm việc. nếu họ hỏi ý kiến của bạn, bạn có thể nói nó sẽ là tốt hơn để làm một mình nếu:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
