INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92769, 'Người bán hàng nhận thấy một hợp đồng để xây dựng một đường thẳng. Mỗi giai đoạn và điều kiện yêu cầu nó là kế hoạch làm việc được cấp phát để chấp nhận ưu tiên cho khách hàng để bắt đầu làm việc, tuy nhiên người bán hàng mắc phải một lỗi. Điều mà khách hàng cần phải làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
