INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92772, 'Nhóm dự án đang tranh cãi về những người bán tiềm năng biết đã gửi đề xuất.Mỗi nhóm thành viên lập luận cho một người bán nhất định, trong khi một thành viên trong nhóm muốn dự án sẽ được trao cho người bán khác nhau. Điều TỐT NHẤT người quản lý dự án này cần phải nhắc nhở các nhóm để tập trung vào để thực hiện lựa chọn là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
