INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92774, 'Trong suốt quá trình thực hiện dự án,các thành viên trong đội dự án của bạn cung cấp 1 dự án cung cấp sản phẩm cho người mua.Ngoài ra,nguời mua từ chối sản phẩm,nói rằng không đáp ứng yêu cầu trên 300 trang trong xác định kĩ thuật.Bạn đã xem lại tài liệu và tìm thấy cái bạn đồng ý.Điều tốt nhất nên làm:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
