INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92776, 'Một quản lý dự án mới đang chuẩn bị tạo 1 bản hợp đồng SOW.1 bên liên quan muốn thêm 1 vài item vào hợp đồng SOW.Một bên liên quan khác chỉ muốn miêu tả các yêu cầu chức năng.Dự án này quan trọng cho công ty của PM. Nhưng 1 người bán sẽ làm công việc này.Bạn nên đưa ra cho PM lời khuyên nào:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101080, 'Bản hợp đồng SOW nên chi tiết hóa như cần thiết cho kiểu của dự án', true, 92776);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101081, 'Bản hợp đồng SOW nói chung nên cho phép người bán làm theo những quyết định của riêng họ', false, 92776);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101082, 'Bản hợp đồng SOW nói chung nên cho phép làm rõ sau này', false, 92776);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101083, 'Bản hợp đồng SOW nên chi tiết việc cho phép làm rõ sau này', false, 92776);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92777, 'Vào gần thời điểm cuối cùng của dự án trước của ban, các yêu cầu mới được đòi hỏi bởi một nhóm các stakeholder (các bên liên quan) khi họ nhận thấy họ sẽ bị tác động bởi dự án của bạn. Điều này trở thành một vấn đề bởi bạn không lường trước thòi gian và chi phí trong kế hoạch quản lý dự án cho các yêu cầu này. Điều tốt nhất bạn có thể làm để ngăn chặn vấn đề tương tự trong tương lại là', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101084, 'Xem lại từ điển WBS kỹ lưỡng, tìm kiếm các mô tả chưa hoàn thiện.', false, 92777);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101085, 'Xem lại tôn chỉ dự án một cách kỹ lưỡng hơn, rà soát các trường hợp nghiệp vụ để phát hiện các lỗ hổng', false, 92777);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101086, 'Lập kế hoạch hợp đồng kỹ lưỡng hơn', false, 92777);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101087, 'Quan tâm nhiều hơn đến quản lý các bên liên quan', true, 92777);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92778, 'Một dự án phát triển phần mềm đang diễn ra không tốt. Có hơn 30 người tham gia và không ai thống nhất về các mục tiêu của dự án. Một người tin rằng dự án cho thể đạt được mức độ cải thiện là 30% trong khi người khác lại tin rằng 50% là điều có thể. Quản lý dự án nghĩ % mức độ cải thiện sản phẩm phải thực tế hơn. Hành động TỐT NHẤT là ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101088, 'Thực hiện phân tích khả thi', true, 92778);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101089, 'Tiếp tục dự án và tìm kiếm nhiều thông tin hơn sau này để giải quyết vấn đề này.', false, 92778);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101090, 'Lấy trung bình các con số và coi đó là mục tiêu.', false, 92778);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101091, 'Hỏi ý kiến nhà tài trợ để đưa ra quyết định cuối cùng.', false, 92778);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92779, 'Một đội dự án đã hoàn thiện, và khách hàng đã chấp nhận phạm vi hoàn chỉnh của dự án. Tuy nhiên, các bài học rút ra được yêu cầu bởi project management office chưa được hoàn thiện. Trạng thái của dự án là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101092, 'Dự án chưa hoàn thành cho tới khi dự án và các sản phẩm bàn giao được hoàn thành và được chấp nhận', true, 92779);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101093, 'Dự án đã hoàn thành vì khách hàng đã chấp nhận các sản phẩm bàn giao', false, 92779);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101094, 'Dự án chưa hoàn thành vì dự án cần được lên kế hoạch lại', false, 92779);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101095, 'Dự án đã hoàn thành vì dự án đã đến này cam kết', false, 92779);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92780, 'Bạn đang ở trong (giữa) công đoạn phát triển một sản phẩm mới cho công ty mình thì bạn phát hiện ra rằng người quản lý trước đã chi trả 3 triệu USD không được thông qua theo các chính sách của công ty. May mắn thay, chỉ số năng suất chi phí CPI của dự án là 1,2. Bạn nên làm gì', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101096, 'Liên hệ với người quản lý của mình', true, 92780);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101097, 'Đặt khoản chi trong một tài khoản giao kèo (??)', false, 92780);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101098, 'Chôn vùi, che giấu chi phí', false, 92780);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101099, 'Từ chối khoản chi', false, 92780);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92781, 'Trong một cuộc họp với một số bên liên quan của dự án, quản lý dự án được đề nghị thêm công việc và phạm vi dự án. Người quản lý dự án đã trao đổi về dự án trước khi tôn chỉ của dự án được ký và anh ta nhớ rằng nhà tài trợ của dự án đặc biệt từ chối không chi thêm tiền cho phạm vi được đưa ra bởi những n gười ngày. Điều TỐT NHẤT mà người quản lý dự án nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101100, 'Nói với stakeholder rằng phạm vi không thể thêm được nữa', true, 92781);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101101, 'Cho nhà tài trợ biết về yêu cầu của stakeholder(các người liên quan)', false, 92781);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101102, 'Đánh giá tác động của việc mở rộng phạm vi', false, 92781);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101103, 'Thêm các công việc nếu thời gian còn cho phép trong lịch trình dự án', false, 92781);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92782, 'Khi kiểm tra lịch của một thành viên nhóm để sắp xếp một buổi họp, bạn thấy cô ấy đã lên lịch gặp với một “key stakeholder ” (một người quan trọng tham gia vào dự án) khác mà bạn không được thông báo. Chiến lược tốt nhất sẽ là :', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101104, 'Đề cập với các thành viên nhóm', true, 92782);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101105, 'Ngăn không đề cập tới điều này cho các thành viên của đội nhưng tiếp tục tquan sát các hoạt động của cô ấy', false, 92782);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101106, 'Thông báo cho sếp bạn về điều này', false, 92782);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101107, 'Đề cập điều này với trưởng nhóm', false, 92782);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92783, 'Người quản lý dự án đang gặp có một thời gian khó khăn để giữ lịch trình dự án trong tầm theo dõi. Dự án cần 220 người để hoàn thành. Tất cả các vấn đề của dự án đã được giải quết theo sự hài lòng (yêu cầu) của PM, chỉ số năng suất thời gian SPI hiện tại là 0.67, và chỉ số năng suất chi phí CPI là 1.26, có 23 hoạt động trên đường thiết yếu (critical path)và khoảng thòi gian PERT là 26. Trong hoàn cảnh này, báo cáo tình trạng hàng tháng nên báo cáo:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101108, 'Các vấn đề và các lựa chọn', true, 92783);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101109, 'Dự án đang tiền hành tốt', false, 92783);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101110, 'Dự án sẽ chậm tiến độ', false, 92783);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101111, 'Chi phí dự án dưới ngân sách', false, 92783);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92784, 'Nhân viên của bạn chậm 3 ngày để đưa báo cáo. 5 phút trước cuộc họp nơi mà chủ đề của báo cáo sẽ được bàn luận, cô ấy đưa bạn báo cáo. Bạn nhận thấy có nhưng sai sót nghiêm trọng trong đó. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101112, 'Hủy cuộc họp và lên lịch lại khi bản báo cáo được sửa', true, 92784);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101113, 'Tới cuộc họp và nói cho các khán giả các lỗi trong báo cáo', false, 92784);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101114, 'Bắt nhân viên thực hiện buổi thuyết trình và giữ im lặng như các người tham dự khác tìm các lỗi', false, 92784);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101115, 'Hủy cuộc họp và tự viết lại báo cáo', false, 92784);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92785, 'Một người quản lý chịu trách nhiệm cho một dự án mà có sự hỗ trợ bởi một người quản lý cao cấp. Ngay từ đầu, bạn đã bất đồng với người quản lý đó về việc dự án nên tiến hành thế nào và các sản phẩm bàn giao sẽ ra sao. Bạn và cô ấy bất đồng nhiều vấn đề trong qua khứ. Phòng của bạn được giao nhiệm vụ cung cấp một số gói quan trọng trong dự án. Bạn sẽ làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101116, 'Cung cấp cho cô ấy thứ mà cô ta cần', true, 92785);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101117, 'Thông tin cho người quản lý của bạn về những quan tâm, lo lắng để tìm sự hỗ trợ của cô ta', false, 92785);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101118, 'Ngồi xuống với người quản lý lúc bắt đầu dự án và cố gắng giải thích, mô tả lý do bạn phản đối dự án và tìm ra cách để giải quyết vấn đề', false, 92785);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101119, 'Đề nghị được chuyển ra khỏi dự án', false, 92785);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92786, 'Một dự án xây dựng lớn và phức tạp tại nước ngoài đòi hỏi phải chuyển các thiết bị qua các đường phố đông đúc của thành phố. Để đảm bảo là các thiết bị được vận chuyển thành công, người liên lạc ở quốc gia đó thông báo cho bạn rằng bạn sẽ phải trả phí cho việc điều phối giao thông. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101120, 'Trả phí', true, 92786);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101121, 'Không trả xu nào bởi vì nó là đút lót', false, 92786);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101122, 'Hủy bỏ công việc', false, 92786);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101123, 'Không trả phí nếu nó không phai là một phần trong ước lượng của dự án', false, 92786);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92787, 'Bạn phải làm việc qua mạng. Có 30 chi nhánh trên ở Mỹ và 20 ở Anh. Một người bán phần mềm có 1 sản phẩm được nâng cấp cho các thiết bị đang được cài đặt. Việc nâng cấp sẽ cung cấp cho khách hàng với các chức năng mà họ yêu cầu, cái mà không có sẵn tại thời điểm bắt đầu của dự án. Hành động tốt nhất trong các trường hợp dưới đây', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101124, 'Cho biết việc nâng cấp của khách hàng và tác động đến thời gian của dự án và các chức năng', true, 92787);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101125, 'Tiếp tục lập kế hoạch, khách hàng của bạn không yêu cầu sự thay đổi', false, 92787);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101126, 'Thực thi sự thay đổi và lập lịch là cần thiết bởi vì điều này yêu cầu sự hỗ trợ của khách hàng', false, 92787);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101127, 'Thực thi sự thay đổi để duy trì các site và tiếp tục với công việc lập lịch', false, 92787);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92788, 'Bạn làm công việc phát triển và nghiên cứu dự án.Khi khách hàng của bạn hỏi bạn về các thành phẩn cơ bản trong dự án. Bạn biết đó là giới thiệu một công việc mới và nó vượt quá quỹ hiện có. Ban nên làm gì.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101128, 'Theo dõi tiến trình kiểm soát sự thay đổi của hợp đồng', true, 92788);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101129, 'Xóa 1 ưu tiên mức dưới trong gói công việc để có nhiều thời gian và có sẵn vốn', false, 92788);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101130, 'Sử dụng ngân sách từ việc dự trữ để bổ sung cho chi phí', false, 92788);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101131, 'Yêu cầu nhiều ngân sách từ nhà tài trợ', false, 92788);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92789, 'Bạn là quản lý dự án cho một hoặc nhiều dự án trong 1 chương trình lớn và quan trọng. Tại một cuộc họp ở mức cao, bạn chú ý rằng những người quản ly dự án khác đã báo cáo về dự án của cô ấy theo như lập lịch. Quay lại với dự án của bạn từ vài tuần trước bạn nhớ có nhiều sản phẩm bàn giao từ các dự án khác cái mà chuyển đển muộn. Bạn nên làm gì.?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101132, 'Gặp gỡ các quản lý dự án khác', true, 92789);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101133, 'Gặp người quản lý chương trình', false, 92789);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101134, 'Xây dựng một kế hoạch quản lý rủi ro', false, 92789);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101135, 'Thảo luận với ông chủ của bạn', false, 92789);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92790, 'Bạn luôn phải người quản lý của bạn để giảm việc ước lượng dự án của bạn là gần 10% sau khi bạn nhận nó từ người quản lý. Phạm vi của dự án mới của bạn là không sáng tỏ và có 30 bên liên quan. Quản lý mong đợi giảm 25% thời gian lãng phí trong dự án. Bạn chọn hành động nào tốt nhất trong tình huống này.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101136, 'Cung cấp 1 sự ước lượng chính xác về giá thực tế và khả năng hỗ trợ', true, 92790);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101137, 'Lập lại kế hoạch để cố gắng đạt 35% để cải thiện thời gian lãng phí', false, 92790);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101138, 'Giảm việc ước lượng và chú ý sự thay đổi trong kế hoạch quản lý rủi ro', false, 92790);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101139, 'Gặp gỡ cả đội dự án để xác định bạn có thể tiết kiệm 10% thời gian bằng cách nào', false, 92790);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92791, 'Nhân viên của bạn có 3 ngày đi muộn với 1 báo cáo. Cô ấy đi vào phòng họp nơi mà báo cáo được thảo luận và tay bạn có 1 bản copy từ 5 phút trước khi chủ đề được thảo luận. Bạn thông báo có 1 vài lỗi nghiêm trọng trong báo cáo. Làm thế nào để ngăn ngừa điều này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
