INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92815, 'Một PM nhiều kinh nghiệm vừa bát đầu làm việc trong một tổchức hợp nhất công nghệthông tin lớn. Quản lýcủa cô ấy cung cấp cho cô ta một bản nháp tôn chỉdựán và ngay lập tức yêu cầu cô ấy cung cấp phân tích vềrủi ro trong dựán. Điều nào dưới đây là tốt nhất có thể giúp đỡ PM?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
