INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92816, 'Bạn được trang bịnhưmột người quản lýcủa một dựán lớn, mới và phức tạp. do dựán này là then chốt trong kinh doanh và rất rõ ràng (visible), các nhà quản lý cấp cao nói với bạn phân tích rủi ro dựán và chuẩn bịchiến lược đáp ứng rủi ro càng sớm càng tốt. Tổchức có quy trình quản lýrủi ro mà rất ít khi được sửdụng, và có lịch sửnắm bắt rủi ro kém. Điểm mốc đầu tiên của dựán là trong vòng 2 tuần nữa. Trong khi chuẩn bịkếhoạch đối phó rủi ro, đầu vào từ đâu thông thường là ít quan trọng nhất trong sốcác đáp án sau:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
