INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92819, 'CPI=0.6, SPI=0.71. Dựán có 625 gói công việc và đang được hoàn thành trong giai đoạn hơn 4 năm. Nhân viên đội dựán rất thiếu kinh nghiệm và dựán nhận được ít hỗtrợcho các kếhoạch thích hợp. Điều nào dưới đây là tốt nhất đểthực hiện?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
