INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92826, 'Một dựán có 1 vài vấn đề, nhưng vẫn trong khảnăng kiểm soát. Vào những tháng cuối của dựán, phần lớn các khoản dựphòng đã được sửdụng và phần lớn các ảnh hưởng tiêu cực của các sựkiện được dựbáo trước đều đã xảy ra. Có 4 hoạt động còn sót lại và 2 hoạt động trong số đó nằm trên đường tới hạn. Ban lãnh đạo đã thông báo với PM rằng công ty thích hoàn thành dựán sớm hơn 2 tuần theo lịch để nhận được thêm lợi nhuận. Đểphản hồi lại, PM gửi một yêu cầu đềxuất cho 1 vài công việc đội dựán chuẩn bịlàm, với hi vọng một công ty khác sẽhoàn thành công việc nhanh hơn. PM tốt nhất nên cốgắng đểlàm việc với', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
