INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92846, 'Giám đốc dự án được chỉ định cho một dự án lớn đã và đang được thực hiện một số lần. Đội dự án vừa hoàn tất giai đoạn thiết kế của dự án và đang tiến hành trong giai đoạn triển khai. Tại điểm này, thay đổi nào có thể xẩy ra mà không phải gánh chịu rủi ro của việc tiến hành lại toàn bộ giai đoạn thiết kế?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
