INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92859, 'Thương lượng giữa 2 bên đang trởnên phức tạp, nên bên A làm một vài ghi chép mà cả2 bên đều kývào. Tuy nhiên, khi công việc hoàn thành, bên B khẳng định rằng họkhông yêu cầu cung cấp một hạng mục mà cả2 bên đều đồng { trong quá trình thương lượng, do nó không có trong hợp đồng tiếp theo. Trong trường hợp này, bên B:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101411, 'Không đúng, do cả2 bên phải tuân theo với những gì họ đã đồng ý', false, 92859);
