INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101421, 'Công ty không cần kiểm soát công việc', false, 92861);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101422, 'Các nguồn lực của công ty là giới hạn', false, 92861);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92862, 'Sau rất nhiều hứng thú và các công việc nặng nhọc, hợp đồng tuyên bốcông việc cho dựán đã hoàn thành. Ngay cảkhi có được sự đồng ýrằng hợp đồng tuyên bố công việc đã hoàn thành, PM vẫn lo lắng khi nào xác định thật sựtất cảcác yêu cầu của người mua. PM tham dựhội nghịcác nhà thầu. Anh ta hỏi bạn lời khuyên nên làm gì tiếp trong cuộc họp hội nghị. Lời khuyên nào là tốt nhất bạn có thểgiúp đỡ anh ta?:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101423, 'Bạn không cần phải tham gia vào hội nghị, người quản lýhội nghịsẽlàm việc đó', false, 92862);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101424, 'Chắc chắn rằng bạn không thương lượng phạm vi dựán', false, 92862);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101425, 'Chắc chắn bạn đã cho toàn bộngười bán đủthời gian đểtrảlời câu hỏi. họ không muốn trảlời câu hỏi khi đối thủcạnh tranh của họcũng có mặt trong hội nghị.', true, 92862);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101426, 'Đểnhà tài trợdựán điều khiển hội nghịvà bạn sẽ đóng vai trò “người tốt” trong hội nghị.', false, 92862);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92863, 'Một người bán được thưởng một hợp đồng đểxây dựng một đường ống. các điều khoản và điều kiện trong hợp đồng yêu cầu kếhoạch công việc được đưa ra đểngười mua phê duyệt trước khi bắt đầu công việc, nhưng người bán không cung cấp được kếhoạch công việc. điều nào dưới đây là tốt nhất cho PM của người bán để thực hiện', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101427, 'Đưa ra một văn bản có mục đích (file a letter of intent)', false, 92863);
