INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101429, 'Đưa ra một văn bản mặc định (default letter)', true, 92863);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101430, 'Yêu cầu người bán ngừng làm việc cho tới khi kếhoạch công việc được chuẩn bị.', false, 92863);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92864, 'Kết thúc hợp đồng khác với kết thúc hoạt động quản trị ởchỗ, kết thúc hợp đồng', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
