INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92865, 'Bạn vừa bắt đầu quản trịmột hợp đồng khi ban lãnh đạo quyết định chấm dứt hợp đồng. bạn nên làm gì trước tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
