INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101438, 'Đến giai đoạn kết thúc hợp đồng.', true, 92865);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92866, 'Đội dự án đang tranh luận về người bán sắp tới, người đã đệ trình các đề nghị (submit proposals). Một nhân viên tranh luận về một người bán tin cậy, trong khi một nhân viên khác muốn một nguòi bán khác sẽ có dự án. Điều tốt nhất mà PM nên nhắc nhở đội của mình tập trung vào trong quá trình tìm ra lựa chọn là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
