INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92867, 'Tổ chức đang cố gắng quyết định có nên chia phòng ban quản lý hợp đồng và phân công trách nhiệm ký kết hợp đồng cho một phòng ban có trách nhiệm trực tiếp với dự án hay không. Một chuyên gia về hợp đồng không thực sự muốn có sự chia tách này do họ sẽ mất……………………… trong môi trường phân tán việc ký kết hợp đồng(or phi tập trung- decentralized)', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101443, 'Tiêu chuẩn thực hiện quản lý dự án của công ty', false, 92867);
