INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92868, 'Trong giai đoạn thực thi dự án, các nhân viên đội dự án bàn giao sản phẩm của dự án cho người bán. Tuy nhiên, người bán từ chối những sản phẩm này, tuyên bố rằng nó không đáp ứng yêu cầu ở trang 300 của tài liệu đặc tả chi tiết kỹ thuật. bạn đã xem lại tài liệu và cũng đồng {. Điều tốt nhất nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101447, 'Giải thích rằng hợp đồng đã sai và nên được thay đổi', false, 92868);
