INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92870, 'Một PM mới đang bắt đầu tạo ra bản hợp đồng tuyên bố công việc. Một bên có liên quan muốn thêm 1 vài hạng mục vào bản hợp đồng tuyên bố công việc. Một bên có liên quan khác chỉ muốn mô tả các yêu cầu chức năng. dự án rất quan trọng với công ty của PM, nhưng một người bán sẽ làm việc này. Bạn sẽ khuyên PM này điều gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101455, 'Bản hợp đồng tuyên bố công việc nên chung chung(general) để cho phép người bán có quyết định của riêng mình', false, 92870);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101456, 'Bản hợp đồng tuyên bố công việc nên chung chung để cho phép các hiệu chỉnh sau này', false, 92870);
