INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92871, 'Một khách hàng đưa cho bạn bản hợp đồng tuyên bố công việc cho một dự án 8 tháng khá phức tạp và có 1 vài điểm chưa biết. Khách hàng yêu cầu bạn chỉ làm việc (just “get it done”) và chỉ muốn gặp bạn vào cuối tháng thứ 8 khi bạn bàn giao dự án hoàn thiện. trong tình huống này, điều tốt nhất nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101459, 'Hoàn thành dự án như được yêu cầu, nhưng thỉnh thoảng xác minh phạm vi với khách hàng trong suốt dự án', true, 92871);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101460, 'Hoàn thành dự án chỉ trong 8 tháng mà không hề liên lạc với khách hàng trong khoảng thời gian này', false, 92871);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101461, 'Hỏi ban lãnh đạo để thỉnh thoảng xác nhận với khách hàng', false, 92871);
