INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101466, 'Chú { thêm vào ban lãnh đạo các bên có liên quan', true, 92872);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92873, 'Dự án phát triển phần mềm không phát triển tốt. có hơn 30 bên có liên quan, và không ai đồng ý với mục tiêu dự án. Một bên có liên quan tin rằng dự án có thể có được 30% cải thiện trong khi một bên khác tin rằng có thể lên tới 50%. PM thì là 10% cải thiện là thực tế hơn. Cách giải quyết tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101467, 'Tiếp tục phát triển dự án và tìm kiếm thêm thông tin sau đó để giải quyết vấn đề', false, 92873);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101468, 'Lấy số liệu trung bình và sử dụng làm mục tiêu', false, 92873);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101469, 'Thực hiện một phân tích khả thi', true, 92873);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101470, 'Hỏi nhà tài trợ để có quyết định cuối cùng', false, 92873);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92874, 'Một đội dự án đã hoàn thành, và khách hàng đã chấp nhận, phạm vi dự án đã hoàn thành. Tuy nhiên, các bài học rút ra do phòng ban quản lý dự án yêu cầu vẫn chưa dc hoàn thành. Trạng thái của dự án là ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101471, 'Dự án chưa hoàn thành do dự án cần phải lên kế hoạch lại', false, 92874);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101472, 'Dự án chưa hoàn thành cho tới khi toàn bộ dự án và sản phẩm bàn giao là hoàn thành và được chấp nhận', true, 92874);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101473, 'Dự án là hoàn thành do khách hàng đã chấp nhận sản phẩm bàn giao', false, 92874);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101474, 'Dự án hoàn thành do dự án đã đến ngày kết thúc (reach the due date)', false, 92874);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92875, 'Bạn đang ở giai đoạn giữa dự án của một sản phẩm mới phát triển cho 1công ty công khai giao dịch, bạn biết được người PM trước đã chi trả 3000000$ mà không được phê chuẩn theo chính sách công ty. Thật may mắn, CPI=1.2. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101475, 'Liên lạc với người quản lý của bạn', true, 92875);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101476, 'Đặt khoản chi đó vào một tài khoản của bên thứ 3 (escrow account) để làm bằng chứng', false, 92875);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101477, 'Che giấu khoản chi này trong phần tập trung chi phí lớn nhất sẵn có (the largest cost center available)', false, 92875);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101478, 'Từ chối khoản chi này', false, 92875);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92876, 'Trong cuộc họp với một vài bên có liên quan, PM được yêu cầu thêm công việc vào phạm vi dự án. PM đã sử dụng thông tin phù hợp với dự án trước khi tôn chỉ dự án được k{ và nhớ rằng nhà tài trợ đã từ chối rõ ràng các khoản vốn cho phạm vi được đề cập bởi các bên có liên quan. Điều tốt nhất mà PM nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101479, 'Cho nhà tài trợ biết các yêu cầu của các bên có liên quan', false, 92876);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101480, 'Đánh giá ảnh hướng của các phạm vi thêm vào', false, 92876);
