INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92877, 'Khi kiểm tra lịch của một nhân viên để lên lịch họp, bạn nhìn thấy cô ấy đã đặt lịch gặp với 1 bên có liên quan chính nhưng bạn đã không được thông báo. Cách thăm dò tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101483, 'Từ chối đề cập vấn đề này với nhân viên đó nhưng vẫn tiếp tục theo dõi các hành động của cô ta.', false, 92877);
