INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101486, 'Nói chuyện về việc này với cô ấy', true, 92877);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92878, 'PM đang có một thời gian khó khăn khi giữ cho dự án phát triển đúng lịch trình. Dự án yêu cầu 220 người để hoàn thành. Tất cả các vấn đề của dự án đã được giải quyết và PM hài lòng, SPI=0.67, CPI=1.26, có 23 hoạt động trong đường tới hạn và độ dài PERT của dự án là 26. Trong điều kiện này, báo cáo trạng thái hàng tháng nên báo cáo rằng:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101487, 'Dự án vẫn hoạt động tốt', false, 92878);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101488, 'Dự án sẽ bị chậm tiến độ', false, 92878);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101489, 'Chi phí dự án thấp hơn ngân sách', false, 92878);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101490, 'Các vấn đề và các tùy chọn', true, 92878);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92879, 'Nhân viên của bạn đã chậm 3 ngày so với lịch báo cáo. 5 phút trước khi cuộc họp mà chủ đề của báo cáo sẽ được thảo luận thì cô ấy mới đưa cho bạn báo cáo. Bạn nhận thấy có 1 vài lỗi nghiêm trọng trong đó, bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101491, 'Hủy cuôc họp và lên lịch họp lại sau khi báo cáo đã được sửa chữa', true, 92879);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101492, 'Tới buổi họp và nói với mọi người tham gia là có lỗi trong báo cáo', false, 92879);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101493, 'Bắt buộc nhân viên phải thuyết trình và những người tham gia khác im lặng tìm lỗi', false, 92879);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101494, 'Hủy cuộc họp và tự viết lại báo cáo', false, 92879);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92880, 'Một người quản lý có trách nhiệm cho 1 dự án có được sự hỗ trợ từ người lãnh đạo cấp cao. Từ khi bắt đầu, bạn đã không đồng ý với ng quản lý này về việc dự án nên tiến hàng ntn và các sản phẩm bàn giao là gì. Bạn và cô ấy đã bất đồng quan điểm rất nhiều vấn đề trong quá khứ. Phòng ban của bạn được giao nhiệm vụ cung cấp 1 vài gói công việc quan trọng do dự án. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101495, 'Cung cấp cho cô ta những gì cô ấy cần', true, 92880);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101496, 'Thông báo với quản lý của bạn về mối lo âu về sự hỗ trợ của cô ấy', false, 92880);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101497, 'Nói chuyện với cô ta vào lúc bắt đầu dự án và cố gắng mô tả tại sao bạn phản đối và tìm ra 1 cách để giải quyết vấn đề', false, 92880);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101498, 'Hỏi để được thoát ra khỏi dự án', false, 92880);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92881, 'Một dự án lớn và phức tạp về xây dựng trong một công ty nc ngoài yêu cầu sự kết hợp để di chuyển các thiết bị yêu cầu qua 1 con phố đông đúc. Để chắc chắn thiết bị được vận chuyển an toàn, các mối liên hệ của bạn ở nc này thông báo rằng bạn phải trả cho các cảnh sát địa phương 1 khoản để thuận tiện cho việc vận chuyển. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101499, 'Không trả do đó là tiền hối lộ', false, 92881);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101500, 'Loại trừ công việc', false, 92881);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101501, 'Trả khoản phí', true, 92881);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101502, 'Không trả phí nếu đấy không phải là 1 phần của ước lượng dự án', false, 92881);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92882, 'Một cuộc thương lượng lớn với 1 nhà thầu phụ tiềm năng đã được lên lịch vào ngày mai, bạn phát hiện ra có 1 cơ hội tốt mà dự án sẽ bị hoãn. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101503, 'Không giành nhiều thời gian chuẩn bị cho cuộc thương lượng', false, 92882);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101504, 'Cắt giảm thời gian thương lượng', false, 92882);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101505, 'Chỉ thương lượng các hạng mục chunhs', false, 92882);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101506, 'Hoãn cuộc thương lượng', true, 92882);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92883, 'Bạn được phân công quản lý 1 dự án đã hoàn thành được 1 nửa theo lịch trình. Sau đánh giá bao quát, bạn phát hiện ra dự án đang đi chậm hơn lịch trình(far behind schedule), và dự án có thể sẽ kéo dài gấp đôi thời gian ước tính ban đầu của PM trước. tuy nhiên, nhà tài trợ đã được nói là dự án đang đúng lịch trình. Hành đông tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101507, 'Cố gắng cấu trúc lại lịch trình để đáp ứng với thời hạn cuối cùng của dự án', false, 92883);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101508, 'Báo cáo đánh giá của bạn với nhà tài trợ', true, 92883);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101509, 'Chuyển lại dự án cho PM cũ', false, 92883);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101510, 'Tiếp tục thực hiện với lịch trình được PM cũ lên kế hoạch và báo cáo điều này vào điểm mốc bị lỡ đầu tiên (first missed milestone)', false, 92883);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92884, 'Bạn đang đi được ½ chặng đường qua 1 buổi giới thiệu máy bay mạng lớn (major network rollout). Có 300 địa điểm trong US và 20 ở UK. Một người bán phần mềm vừa phát hành một phần mềm lớn nâng cao chất lượng cho 1 vài thiết bị được cài đặt. việc nâng cao chất lượng cung cấp cho khách hàng chức năng họ yêu cầu mà không có sẵn tại thời điểm dự án bắt đầu. trong điều kiệnnày, hành động nào là tốt nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
