INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92887, 'Bạn luôn được ban lãnh đạo yêu cầu cắt giảm ước tính dự án 10% sau khi bạn đưa nó cho họ. phạm vi của dự án mới là k rõ ràng và có hơn 30 bên có liên quan. Ban lãnh đạo mong muốn giảm thời gian giải lao 25% như 1 kết quả của dự án. Điều nào dưới đây là hành động tốt nhất trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
