INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92889, 'Dự án đang đi được nửa đường khi bạn phát hiện có 1 ng bán phần mềm cho dự án của bạn có khó khăn lớn trong việc giữ nhân viên do bất đồng lao động. nhiều dự án khác trong công ty của bạn cũng sử dụng các dịch vụ của công ty. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
