INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92895, 'Bạn là PM cho 1 dự án đa quốc gia mới và đội dự án của bạn bao gồm nhân viên đến từ 4 quốc gia. Phần lớn nhân viên chưa bao h làm việc trong 1 dự án kiểu như thế này, nhưng dự án có sự hỗ trợ lớn từ ban lãnh đạo cấp cao. Điều tốt nhất để chắc chắn rằng sự khác biệt văn hóa không ảnh hưởng tới dự án là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
