INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92900, 'Khách hàng trong một dự án nói với PM rằng anh ta đã hết tiền chi trả cho dự án. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101575, 'Thay đổi lịch trình các công việc để thực hiện thời gian muộn hơn so với lịch trình cũ để khách hàng có thêm nguồn vốn', false, 92900);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101576, 'Bắt đầu kết thúc các hoạt động quản trị', true, 92900);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101577, 'Dừng công việc', false, 92900);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101578, 'Cắt giảm nhân sự 1 phần đội dự án(release part of the team)', false, 92900);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92901, 'Bạn là PM cho 1 dự án lớn trong hợp đồng với chính phủ. Hợp đồng 2 năm, nhiều triệu $ đã được k{ 6 tháng trước. bạn không được kéo theo trong thương lượng hợp đồng hay thiết lập các thủ tục cho việc quản l{ các thay đổi, nhưng bạn đang tràn ngập với các thay đổi từ khách hàng và từ những người trong tổ chức của bạn. thông thường, ai sẽ có trách nhiệm cho việc xem xét chính thức các thay đổi lớn đối với dự án/hợp đồng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101579, 'Ban kiểm soát thay đổi', true, 92901);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101580, 'Ban ký hợp đồng/pháp lý', false, 92901);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101581, 'PM', false, 92901);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101582, 'Lãnh đạo cấp cao', false, 92901);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92902, 'Phòng kĩ thuật muốn mục tiêu dự án cải thiện 10%. Phòng IT muốn nguồn lực của phòng k bị sử dụng nhiều hơn 5% vào dự án. Ban lãnh đạo, cũng là thủ trưởng của bạn, muốn đội dự án giảm thuế pháp l{ (tax liability). Điều tốt nhất bạn nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101583, 'Xây dựng 1 kế hoạch đáp ứng tất cả các mục tiêu trên', false, 92902);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101584, 'Mọi người cùng bàn bạc và đồng ý 1 mục tiêu', false, 92902);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101585, 'Tính đến mục tiêu của phòng kỹ thuật và phòng IT nhưng đáp ứng ít đối với mục tiêu của ban lãnh đạo(holding a further meeting)', true, 92902);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101586, 'Chỉ tính đến mục tiêu của ban lãnh đạo.', false, 92902);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92903, '4 giám đốc dự án(PM) ngồi ăn trưa với nhau và thảo luận về dự án của họ. phần lớn thời gian họ phàn nàn về việc quản l{ và điều hành dự án khó khăn như thế nào. Một số lời phàn nàn là về các cổ đông và các thay đổi mà họ tạo ra cho dự án. Người khác thì phàn nàn về sự khó khăn trong việc thúc đẩy nhân viên hợp tác và làm việc. 1 người PM muốn tập trung vào tất cả các lợi ích của ma trận tổ chức mà họ đều làm ra. Anh ta sẽ đề cập tới vấn đề nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101587, 'Cải thiện quyền quản lý và kiểm soát nguồn lực của PM', true, 92903);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101588, 'Có hơn một người tham gia quản lý dự án', false, 92903);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101589, 'Truyền thông dễ dàng hơn', false, 92903);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101590, 'Báo cáo dễ dàng hơn.', false, 92903);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92904, '2 PM vừa nhận ra họ đang ở trong một ma trận tổ chức yếu và quyền lực của họ trong vai trò là PM bị hạn chế. Một người nhận ra anh ta thật sự là người giải quyết công việc dự án (project expediter), người còn lại nhận ra rằng anh ta là điều phối viên của dự án (project coordinator). Vậy người tiến hành và điều phối viên của dự án khác nhau ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101591, 'Người giải quyết công việc dự án không thể đưa ra các quyết định', true, 92904);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101592, 'Người giải quyết công việc dự án có thể đưa ra nhiều quyết định hơn điều phối viên dự án', false, 92904);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101593, 'Người giải quyết công việc báo cáo cho quản lý cấp cao hơn', false, 92904);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101594, 'Người giải quyết công việc có một số thẩm quyền riêng', false, 92904);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92905, 'Trong một tổ chức hướng dự án (tổ chức trong đó k có các công việc thường nhật mà toàn là dự án), đội dự án có đặc điểm gì:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101595, 'Báo cáo cho một vài thủ trưởng', false, 92905);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101596, 'Không có sự trung thành đối với dự án', false, 92905);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101597, 'Báo cáo với người quản lý có trách nhiệm và thẩm quyền (functional manager)', false, 92905);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101598, 'Thường xuyên có mặt trong dự án, không có phòng ban chức năng(will not always have a home)', true, 92905);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92906, 'Một PM đang cố gắng hoàn thành dự án phát triển phần mềm, nhưng không thể tập trung và quan tâm nhiều tới dự án. Nguồn nhân lực được tập trng vào hoàn thành các công việc liên quan tới các tiến trình sản xuất phần mềm, và PM có ít thẩm quyền để phân công nguồn lực một cách hợp lý. Loại hình tổ chức nào mà người PM này đang làm việc?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101599, 'Tổ chức bao gồm các phòng ban chức năng.', true, 92906);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101600, 'Ma trận. đối với tổ chức loại này, thành viên đội dự án phải báo cáo với 2 thủ trưởng: 1 là PM và quản lý bộ phận chức năng.', false, 92906);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101601, 'Tổ chức mà PM là người giải quyết công việc', false, 92906);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101602, 'Tổ chức mà PM là người điều hành', false, 92906);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92907, 'Một PM có ít kinh nghiệm quản lý dự án. Nhưng anh ta được phân công làm PM cho một dự án mới. do anh ta sẽ làm việc trong một tổ chức ma trận (matrix organization) để hoàn thành dự án của mình, anh ta có thể trông đợi việc truyền thông trong dự án của mình có đặc điểm:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101603, 'Đơn giản', false, 92907);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101604, 'Truyền thông mở và thúc đẩy', false, 92907);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101605, 'Phức tạp', true, 92907);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101606, 'Khó tự động hóa', false, 92907);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92908, '2 nhân viên trong đội dự án đang nói chuyện với nhau và phàn nàn về việc rất nhiều người đang yêu cầu nhân viên đó phải làm một số việc. nếu anh ta làm việc trong một tổ chức bao gồm các phòng ban chức năng (functional organization), ai sẽ có quyền để đưa ra chỉ dẫn cho các thành viên dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101607, 'Người quản lý dự án PM', false, 92908);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101608, 'Người quản lý bộ phận chức năng functional manager', true, 92908);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101609, 'Đội dự án', false, 92908);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101610, 'Ma trận kiểm soát chặt tight matrix', false, 92908);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92909, 'Ai có nhiều thẩm quyền nhất trong một tổ chức hướng dự án (projectized organization)', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101611, 'Người quản lý dự án PM', true, 92909);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101612, 'Người quản lý bộ phận chức năng functional manager', false, 92909);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101613, 'Đội dự án', false, 92909);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101614, 'Đội dự án đều có quyền như nhau', false, 92909);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92910, 'Tính chất nào dưới đây không phải là tính chất của một dự án', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101615, 'Tạm thời', false, 92910);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101616, 'Có thời gian bắt đầu và kết thúc xác định', false, 92910);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101617, 'Có các hoạt động liên quan tới nhau', false, 92910);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101618, 'Lặp lại công việc dự án mỗi tháng. (repeat itself every month)', true, 92910);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92911, 'Các bên liên quan quản lý dự án ngoại trừ việc:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101619, 'Đưa cho các bên liên quan một ít $ (giving stakeholders extras)', true, 92911);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101620, 'Xác định các bên liên quan', false, 92911);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101621, 'Xác định yêu cầu của các bên liên quan', false, 92911);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101622, 'Quản l{ các mong đợi của các bên liên quan', false, 92911);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92912, 'Một người quản l{ và giám đốc kĩ thuật thảo luận về một thay đổi trong gói công việc chính. Sau khi thảo luận, người quản lý liên lạc với bạn và yêu cầu bạn hoàn thành các thủ tục giấy tờ để thực hiện việc thay đổi đó. Đây là ví dụ về:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101623, 'Sự chú ý việc quản lý vào quản lý phạm vi', false, 92912);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101624, 'Lập kế hoạch quản lý', false, 92912);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101625, 'Trách nhiệm của người giải quyết công việc dự án', true, 92912);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101626, 'Một sự thay đổi hệ thống điều khiển.', false, 92912);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92913, 'Dự án đang trong quá trình lập kế hoạch nhóm. 3 bên có liên quan yêu cầu giám đốc dự án cung cấp một số thông tin về phương pháp quản lý dự án mới của công ty, phương pháp này lấy từ đâu và tại sao nó lại khác biệt với cách họ quản lý các dự án. 3 bên có liên quan đều là bạn của người quản lý dự án, toàn bộ nhóm dự án đều đã làm việc với nhau trong nhiều năm. Dự án sử dụng một vài điều khoản mới như “hành động hiệu chỉnh” (corective action), điều này làm cho một số bên có liên quan lo lắng, họ không chắc chắn nếu cách thức quản lý dự án sẽ thay đổi cùng với các điều khoản mới. người quản lý dự án nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101627, 'Đưa ra lời khuyên cho các bên có liên quan rằng PM sẽ giữ lại các điều khoản này trong truyền thông trong dự án.', false, 92913);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101628, 'Cung cấp một danh sách các điều khoản mới và định nghĩa của nó', false, 92913);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101629, 'Thông báo cho phòng quản lý dự án', true, 92913);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101630, 'Chắc chắn rằng PM sẽ duy trì thẩm quyền của mình như một người quản lý dự án, mặc dù PM và các bên có liên quan là bạn.', false, 92913);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92914, 'Một PM đang quản lý dự án thứ 2 của mình. Dự án đã bắt đầu được 1 tháng sau khi dự án thứ nhất bắt đầu. dự án đầu tiên của PM này là một dự án nhỏ, tuy nhiên đang mở rộng từng ngày. Mỗi ngày trôi qua, người PM này bắt đầu cảm thấy cần sự giúp đỡ. Gần đây, anh ta đã nghe có tin rằng năm ngoái cũng có một dự án gần giống với dự án thứ 2 của anh ta. Anh ta nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101631, 'Liên lạc với người PM của dự án kia và yêu cầu hỗ trợ', false, 92914);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101632, 'Sử dụng bản ghi và hướng dẫn từ phòng quản lý dự án', true, 92914);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101633, 'Chờ đợi xem nếu dự án bị ảnh hưởng bởi sự mở rộng phạm vi dự án', false, 92914);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101634, 'Chắc chắn rằng phạm vi dự án phải được các bên có liên quan đồng ý và phê duyệt', false, 92914);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92915, 'Dự án đang tiến hành tốt, ngoại trừ số lượng các thay đổi đã được tạo ra. Dự án được thực hiện và chia ra 7 ban khác nhau trong công ty và sẽ cải thiện đáng kể hiệu năng của các phòng ban này khi nó được thực hiện. có 14 quy trình quản lý dự án được lựa chọn để sử dụng trong dự án này. PM là một chuyên gia kĩ thuật và được training về truyền thông và quản lý nhân lực. điều nào dưới đây là nguyên nhân của vấn đề của dự án (số lượng các thay đổi)?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101635, 'PM không được huấn luyện để hiểu rõ môi trường công ty', false, 92915);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101636, 'Dự án nên được giám sát quản lý nhiều hơn để có kết quả tốt và đem lại lợi nhuận cho công ty', false, 92915);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101637, 'Dự án nên sử dụng thêm nhiều tiến trình quản lý dự án hơn', false, 92915);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101638, 'Một vài bên liên quan chưa được xác định', true, 92915);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92916, 'Vòng đời dự án và vòng đời sản phẩm khác nhau. Trong vòng đời dự án có đặc điểm gì khác khi so sánh với vòng đời sản phẩm?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101639, 'Không kết hợp phương pháp luận', false, 92916);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101640, 'Là khác biệt trong từng ngành sản xuất khác nhau', true, 92916);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101641, 'Có thể sinh ra nhiều dự án khác nhau', false, 92916);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101642, 'Miêu tả các hành động quản lý dự án', false, 92916);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92917, 'Các bên có liên quan có thể được xác định trong quy trình nào của việc quản lý dự án ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
