INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92928, 'Bảng phân rã công việc WBS và từ điển WBS đều được hoàn thành. Đội dự án bắt đầu xác định các rủi ro. Nhà tài trợ liên lạc với PM để yêu cầu làm ma trận trách nhiệm. dự án có ngân sách là 100000$ với 14 nhân lực đến từ 3 quốc gia. Dự án có một rủi ro nhỏ và PM đã quản lý rất nhiều dự án giống dự án này. Việc phải làm tiếp theo là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
