INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101690, 'Hoàn thành quản lý rủi ro và ma trận trách nhiệm', false, 92928);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92929, 'Một PM không có nhiều thời gian để lên kế hoạch trước khi ngày bắt buộc khởi động dự án đang tới. Do đó anh ta muốn lập kế hoạch hiệu quả nhất có thể. Anh ta nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101691, 'Chắc chắn nên có tuyên bố phạm vi dự án sơ bộ đã hoàn thành và sau đó tiến hành làm WBS', false, 92929);
