INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92930, 'PM chắc chắn rằng sản phẩm của dự án phải hoàn thiện theo kế hoạch quản lý dự án. Anh ta đang ở giai đoạn nào của dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101695, 'Lên kế hoạch', false, 92930);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101696, 'Thực thu', false, 92930);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101697, 'Kiểm soát', false, 92930);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101698, 'Kết thúc', true, 92930);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92931, 'Một PM nhận được cuộc gọi từ nhân viên dự án, thông báo rằng đã có sự khác nhau giữa tốc độ của một hệ thống trong dự án và tốc độ đề ra. PM ngạc nhiên bởi vì quản lý hiệu năng không được xác định trong giai đoạn lập kế hoạch. Nếu PM sau đó có thể ước tính được khi nào sẽ có phản hồi của sự khác nhau này, thì anh ta đang ở giai đoạn nào của quản lý dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101699, 'Khởi tạo', false, 92931);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101700, 'Thực thi', false, 92931);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101701, 'Kiểm soát', true, 92931);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101702, 'Kết thúc', false, 92931);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92932, 'Một nhân viên dự án thông báo cho PM rằng hoạt động bao gồm một gói công việc hiện nay không còn thích hợp nữa. điều này là tốt nhất cho PM khi anh ta đang ở trong một phần nào của giai đoạn phát triển dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101703, 'Hành động hiệu chỉnh', false, 92932);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101704, 'Kết hợp điều khiển thay đổi', false, 92932);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101705, 'Kiểm soát', true, 92932);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101706, 'Kết thúc dự án', false, 92932);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92933, 'Trong buổi họp đội dự án, một nhân viên dự án hỏi về đơn vị đo đạc nào được sử dụng trong dự án để kiểm soát hiệu năng. nhân viên này cảm thấy một vài thước đo có liên quan tới công việc của anh ta đang không chính xác. Dự án được xem xét tốt nhất trong phần nào của giai đoạn phát triển dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101707, 'Kết thúc', false, 92933);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101708, 'Kiểm soát', false, 92933);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101709, 'Thực thi', true, 92933);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101710, 'Khởi tạo', false, 92933);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92934, 'Trong khi hoàn thành gói công việc, nhà tài trợ yêu cầu PM báo cáo dự án đang được diễn tiến ntn. Trong quá trình chuẩn bị báo cáo, PM yêu cầu tất cả nhân viên dự án họ đã làm được bao nhiêu % công việc của mình. Có một nhân viên rất khó khăn trong việc quản lý từ đầu. khi trả lời câu hỏi của PM, anh ta nói rằng chưa hoàn thành gì cả. Mệt mỏi vì được trả lời như vậy, PM báo cáo với thủ trưởng của đội dự án là các nhân viên không có tinh thần hợp tác. Vấn đề thật sự ở đây là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101711, 'PM không có đủ nguồn lực cho dự án', false, 92934);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101712, 'PM không tạo ra hệ thống tưởng thưởng xứng đáng cho nhân viên để nâng cao tinh thần hợp tác của họ', false, 92934);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101713, 'PM nên có buổi họp với thủ trưởng của đội dự án khi lần đầu tiên nhân viên dự án có vấn đề', false, 92934);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101714, 'PM không có gói công việc', true, 92934);
