INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92946, 'Một bên có liên quan đặc biệt có tiếng trong việc tạo ra thay đổi trong dự án. Cách PM tiếp cận với bên có liên quan này tại thời điểm bắt đầu dự án nào là tốt nhất trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
