INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92950, 'Người PM trước của dự án của bạn đã quản lý dự án mà không có tổ chức dự án. Có sự thiếu hụt trong kiểm soát quản lý và không có sản phẩm chuyển giao nào được xác định rõ. Lựa chọn nào dưới đây là tốt nhất cho bạn để tổ chức dự án tốt hơn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
