INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101778, 'Xây dựng bản mô tả sản phẩm của dự án', false, 92950);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92951, 'Bạn đang kiểm soát dự án trong giai đoạn lên kế hoạch và phát hiện ra có 6 cá nhân đã k{ vào tôn chỉ dự án. Điều nào dưới đây có liên quan nhất với bạn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
