INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92952, 'Tôn chỉ dự án cho một dự án của được phê chuẩn để lê kế hoạch và bạn vừa được phân công là PM. Nhận ra rằng lên kế hoạch dự án là nỗ lực xuyên suốt dự án, việc nào sau đây bạn nên kết hợp nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
