INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101790, 'Xây dựng một hệ thống kiểm soát dự án.', true, 92953);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92954, 'Một PM được trang bị để lãnh đạo một dự án kỹ thuật cao trong khu vực với những người ít thông thạo về lĩnh vực này. PM ủy quyền xây dựng lịch làm việc, ước tính chi phí, lựa chọn hành động và phân công hành động cho nhiều thành viên trong đội dự án, và chỉ làm việc như người xem xét và điều phối các hoạt động của dự án. Kết quả của cách tiếp cận này giống như:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101791, 'Một đội chức năng suốt toàn bộ dự án ở mức độ cao, là điển hình của sự sáng tạo và trách nhiệm', false, 92954);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101792, 'Một đội hỗn loạn lúc ban đầu, nhưng sau đó sẽ trở nên gắn kết và làm việc hiệu quả', false, 92954);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101793, 'Một đội không thực sự có hiệu quả, nhưng luôn làm việc cùng nhau do môi trường làm việc mà PM đem lại', false, 92954);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101794, 'Một đội có hiệu năng thấp, nhuệ khí thấp, dễ xung đột và tốc độ thay thế nhân viên cao', true, 92954);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92955, 'Bạn đang trong quá trình thực hiện các thay đổi quan trọng cho một sản phẩm đã có, khi bạn biết rằng nguồn lực đã hứa vào lúc khởi động dự án hiện tại đang không có thì điều tốt nhất bạn nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101795, '. Chỉ ra làm thế nào mà các nguồn lực đã được cam kết cho dự án của bạn lúc ban đầu', false, 92955);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101796, 'Lập lại kế hoạch dự án mà không có các nguồn lực đó', false, 92955);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101797, 'Giải thích, trình bày ảnh hưởng nếu nguồn nhân lực đã cam kết không có.', true, 92955);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101798, 'Phá dự án, k làm nữa', false, 92955);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92956, 'Bạn được phân công để quản lý việc phát triển của website đầu tiên của một tổ chức. website này sẽ rất phức tạp và có tính tương tác cao, và đội dự án của bạn cũng như khách hàng chưa có kinh nghiệm gì trong việc phát triển website. Thời hạn bàn giao sản phẩm rất gấp gáp. Bất kz một sự chậm trễ nào sẽ tiêu tốn $ của công ty bạn cũng như khách hàng. Bạn có một nhà tài trợ dự án và có bản hợp đồng bàn giao, tôn chỉ dự án và kế hoạch quản lý dự án đều đã có chữ ký. Bên phía khách hàng đã giữ lại đầy đủ các thông báo của quá trình thực hiện dự án thông qua báo cáo trạng thái và biên bản họp. dự án đang trong đúng lịch trình, trong ngân sách và việc xem xét lại cuối cùng(chỉ mang tính hình thức) cũng đã được lên lịch. Đột nhiên, bạn nghe rằng toàn bộ nỗ lực có thể bị hủy bởi vì sản phẩm đang phát triển là hoàn toàn không được chấp nhận. điều gì là nguyên nhân của vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101799, 'Một bên có liên quan không được liên quan thỏa đáng trong dự án(not adequately involved)', true, 92956);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101800, 'Tôn chỉ dự án và kế hoạch dự án không được giải thích kỹ lưỡng hoặc không được xem xét lại một cách đầy đủ từ phía khách hàng', false, 92956);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101801, 'Hợp đồng truyền thông không đầy đủ và không cung cấp các thông tin yêu cầu cho các bên có liên quan', false, 92956);
