INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92957, 'PM nhận được 1 thay đổi từ khách hàng và thay đổi này không ảnh hưởng tới lịch hoạt động của dự án và dễ dàng để hoàn thành. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
