INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92959, 'Bạn là PM vừa được phân công để kiểm soát một dự án(người PM cũ của dự án này vừa rời khỏi công ty). Người PM cũ nói với bạn rằng dự án đang trong đúng lịch trình, nhưng chỉ khi anh ta thúc giục liên tục các nhân viên làm việc. điều đầu tiên bạn sẽ làm trong cương vị 1 PM mới là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
