INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92965, 'Một PM đang quản lý một hợp đồng có giá sẵn (fixed price contract). Cô ấy nghĩ rằng một thay đổi lớn từ yêu cầu của khách hàng sẽ ảnh hưởng tới lịch trình dự án. Cô ấy nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
