INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92966, 'Trong khi hoàn thành một dự án, một PM nhận ra rằng anh ta cần giảm bớt chi phí dự án. Sau khi nghiên cứu các lựa chọn của mình, anh ta thực hiện thay đổi dưới đây. Lựa chọn nào sẽ làm giảm chi phí dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101839, 'Thay đổi thành phần A từ thành phần B. thành phần A có chi phí cao hơn nhưng có vòng đời chi phí ít hơn B', false, 92966);
