INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101841, 'Di chuyển hành động B và H để thực hiện cùng lúc, và chấp nhận tăng 30% rủi ro mà 5 nguồn lực cần thiết sẽ được thêm vào sau đó', false, 92966);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101842, 'Bỏ một kiểm tra từ kế hoạch quản lý dự án', true, 92966);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92967, 'Dự án này được tuyên bố (chartered?) để xác định cách thức mới để mở rộng vòng đời sản phẩm của một sản phẩm của công ty bậc trung. Người PM tới từ một ban kỹ thuật và đội dự án là từ ban sản phẩm và ban tiếp thị. Tuyên bố phạm vi dự án sơ bộ và kế hoạch dự án đã hoàn thành khi một bên có liên quan thông báo với đội dự án là: có một cách tốt hơn để hoàn thành một gói công việc. họ cung cấp văn bản xem xét kỹ thuật từ ban của họ, văn bản này chứng minh cách thức mới để hoàn thành công việc sẽ thực sự nhanh hơn cách thức cũ. PM đã từng có kinh nghiệm tương tự với phòng ban này trong dự án khác, và hi vọng là sẽ xảy ra trong dự án này. PM nên làm gì đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101843, 'Liên hệ với phòng ban và phàn nàn về sự thiếu hụt thời hạn cuối cùng(deadline) cho đệ trình phạm vi(submission of scope)', false, 92967);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (101844, 'Tìm kiếm xem thay đổi về lịch trình này sẽ ảnh hưởng tới chi phí để hoàn thành gói dự án và chất lượng sản phẩm của gói dự án', true, 92967);
