INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92977, 'Phòng kỹ thuật vừa phát hiện ra một vấn đề với hệ thống tính toán chi phí và đã yêu cầu phòng hệ thống để phân tích điều gì sai và sửa chữa nó. Bạn là một PM đang làm việc với chương trình tính toán chi phí trong một dự án khác. Ban lãnh đạo đã xác định yêu cầu thay đổi đối với ban kiểm soát thay đổi là thêm vào dự án của bạn một công việc mới. dự án đã có của bạn có hiệu suất chi phí (CPI) là 1.2 và chỉ số thực hiện theo lịch (SPI) là 1.3 nên bạn cần thêm phòng để thêm công việc mà không làm chậm trễ dự án của bạn hay làm tăng chi phí của dự án này. Sau một vài phân tích, bạn xác định rằng công việc mới và công việc đã có không ảnh hưởng lẫn nhau và có thể làm đồng thời. 2 công việc yêu cầu các kỹ năng khác nhau. Điều tốt nhất nên làm là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
