INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92984, 'Chương trình được lên kế hoạch nhiều năm trước khi có một giới thiệu lớn của công nghệ mới. trong khi lên kế hoạch cho dự án mới để bắt đầu trong chương trình này, PM đã mở rộng kế hoạch quản lý phạm vi dự án do dự án trở nên phức tạp hơn. Mức độ không chắc chắn trong phạm vi là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
