INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92986, 'Một PM mới được các chuyên gia quản lý dự án có kinh nghiệm cố vấn. anh ta thấy rằng thật khó để tìm đủ thời gian quản lý dự án do dự án và phạm vi sản phẩm đang ngày càng phức tạp. các chuyên gia đề cập tới các công cụ đơn giản cho quản lý dự án như WBS, có thể được sử dụng trong quá trình thực hiện dự án để giúp đỡ việc quản lý. Vậy WBS dùng để làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
