INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (92990, 'Bạn vừa tham gia vào phòng quản lý dự án sau 5 năm làm việc trong dự án. Một trong những điều bạn muốn giới thiệu với công ty là sự cần thiết của bảng WBS. Một vài PM đã tức giận do bạn đang đòi hỏi họ phải làm thêm việc. Điều nào dưới đây là tốt nhất khi bạn muốn thuyết phục họ sử dụng WBS?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
