INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93017, '. Một PM đang cố gắng để sắp xếp tất cả các hành động trong dự án và đã xác định được: hoạt động 1 có thể thực hiện ngay lập tức và ước tính sẽ kéo dài trong 1 tuần. Hoạt động 2 sẽ bắt đầu sau khi hoạt động 1 hoàn thành và ước tính kéo dài trong 4 tuần. Hoạt động 3 có thể bắt đầu sau khi hoạt động 2 hoàn thành và ước tính kéo dài trong 5 tuần. Hoạt động 4 có thể bắt đầu sau khi hoạt động 1 hoàn thành và ước tính kéo dài trong 8 tuần. Hoạt động 3 và 4 phải được hoàn thành trước khi kết thúc dự án. Vậy đường tới hạncủa dự án này kéo dài trong bao lâu?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
