INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93020, 'Một PM đang trong giai đoạn thực thi của một dự án xây dựng lớn khi anh khám phá ra thời gian cần thiết để hoàn thành dự án dài hơn thời gian hiện có. Điều tốt nhất nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
