INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93021, 'Trong khi lên kế hoạch dự án, bạn ước tính thời gian cần thiết cho mỗi hoạt động và thêm ước tính để tạo ra ước lượng dự án. Bạn cam kết hoàn thành dự án đúng hạn. Trong tình huống này, điều gì Sai?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102059, 'Đội dự án không tạo ra ước tính và việc ước tính sẽ tốn thời gian nếu sử dụng phương pháp này', false, 93021);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102060, 'Đội dự án không tạo ra ước tính và sơ đồ mạng k được sử dụng', true, 93021);
