INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93022, 'Trong khi định nghĩa hoạt động, một nhân viên xác định rằng 1 hoạt động cần được thực hiện. Tuy nhiên, 1 nhân viên khác tin rằng hoạt động đó không phải là 1 phần của dự án như anh ta hiểu trong tuyên bố phạm vi dự án. PM tốt nhất nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
