INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93032, 'Bạn là một PM cho một dự án phát triển sản phẩm mới có 4 cấp trong bảng WBS, và được sắp xếp bằng phương pháp sơ đồ mũi tên. Ước tính thời gian đã được nén và một lịch trình đã được tạo ra. Hành động quản lý thời gian nào nên được làm tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
