INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93062, 'Bạn có 4 dự án và phải chọn 1. Dự án A đang được thực hiện hơn 6 năm và có giá trị thực NPV là 70000$. Dự án B đang được thực hiện hơn 3 năm và có NPV là 30000$. Dự án C đang được thực hiện hơn 5 năm và có NPV là 40000$. Dự án D đang dc thực hiện hơn 1 năm và NPV là 60000$. Bạn sẽ chọn dự án nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102223, 'Dự án A', true, 93062);
