INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93063, 'Dự án A có tỷ suất hoàn vốn nội bộ (internal rate of return –IRR) là 21%. Dự án B có IRR= 7%. Dự án C có IRR= 31%. Dự án D có IRR= 19%. Dự án tốt nhất là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102227, 'Dự án A', false, 93063);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102228, 'Dự án B', false, 93063);
