INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102230, 'Dự án D', false, 93063);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93064, 'Là một PM, bạn được giới thiệu các thông tin sau về giá trị thực NPV của một vài dự án. Bạn sẽ lựa chọn dự án nào trong số các dự án dưới đây?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102231, 'Dự án A với NPV là 95000$', false, 93064);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102232, 'Dự án B với NPV là 120000$', true, 93064);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102233, 'Dự án C với NPV là 20000$', false, 93064);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102234, 'Dự án D với NPV là -30000$', false, 93064);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93065, 'Công ty của bạn có thể chấp nhận 1 trong 3 dự án sau: dự án A có NPV là 30000$ và cần 6 năm để hoàn thành, dự án B có NPV là 60000$ và cần 3 năm để hoàn thành, dự án C có NPV là 90000$ và cần 4 năm để hoàn thành. Dựa vào các thông tin trên, bạn sẽ chọn dự án nào để thực hiện?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102235, '3 dự án có giá trị như nhau', false, 93065);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102236, 'Dự án A', false, 93065);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102237, 'Dự án B', false, 93065);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102238, 'Dự án C', true, 93065);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93066, 'Người bán nói với bạn rằng các hoạt động của bạn gây ra việc tăng chi phí của họ. bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102239, 'Đề nghị thay đổi đối với chi phí dự án', false, 93066);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102240, 'Có buổi họp với ban lãnh đạo để xem nên làm gì', false, 93066);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102241, 'Hỏi người bán về các thông tin hỗ trợ', true, 93066);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102242, 'Từ chối mọi hành động sai', false, 93066);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93067, 'Dự đoán chi phí chỉ ra rằng bạn sẽ bị vượt quá chi phí vào giai đoạn cuối của dự án. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102243, 'Loại trừ các rủi ro trong ước tính và ước tính lại', true, 93067);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102244, 'Gặp nhà tài trợ để tìm ra công việc nào nên được làm sớm hơn', false, 93067);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102245, 'Cắt giảm chất lượng', false, 93067);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102246, 'Giảm phạm vi', false, 93067);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93068, 'Một dự án phát triển cửa hàng mới yêu cầu việc mua bán của nhiều thiết bị, máy móc và đồ đạc. Phòng ban có trách nhiệm cho việc phát triển vừa tập trung quy trình mua bán bên ngoài và tiêu chuẩn hóa hệ thống đặt hàng mới. Những thủ tục trên có trong tài liệu nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102247, 'Tuyên bố phạm vi dự án', false, 93068);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102248, 'WBS', false, 93068);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102249, 'Kế hoạch quản lý nhân lực', false, 93068);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102250, 'Chính sách của tổ chức', true, 93068);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93069, 'Vào giai đoạn đầu của dự án, bạn có buổi thảo luận với nhà tài trợ về các kỹ thuật ước lượng nên được sử dụng. Bạn muốn có đánh giá của chuyên gia, nhưng nhà tài trợ phản đối và muốn dùng ước tính tương tự. Tốt nhất nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102251, 'Đồng ý với ước tính tương tự như một đánh giá của chuyên gia', true, 93069);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102252, 'Đề nghị đánh giá vòng đời như một thỏa hiệp', false, 93069);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102253, 'Xác định tại sao nhà tài trợ muốn một ước tính chính xác như thế', false, 93069);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102254, 'Cố gắng thuyết phục nhà tài trợ đồng { các đánh giá của chuyên gia do nó chính xác hơn', false, 93069);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93070, 'Bạn vừa hoàn thành giai đoạn khởi tạo của một dự án nhỏ và đang bước sang giai đoạn lên kế hoạch khi một bên có liên quan tới dự án hỏi bạn về ngân sách dự án và đường chuẩn chi phí (cost baseline). Bạn nên nói gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102255, 'Ngân sách dự án có thể được tìm thấy trong tôn chỉ dự án mới vừa hoàn thành', false, 93070);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102256, 'Ngân sách dự án và đường chuẩn sẽ không được kết thúc và được chấp nhận cho đến khi giai đoạn lên kế hoạch hoàn tất', true, 93070);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102257, 'Kế hoạch quản lý dự án sẽ không bao gồm ngân sách dự án và đường chuẩn, đây là một dự án nhỏ', false, 93070);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102258, 'Có thể hoàn thành một ước tính trước khi kế hoạch quản lý dự án được tạo ra', false, 93070);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93071, 'PM được chỉ định ước tính chi phí chung để chia nhỏ các hoạt động để thiết lập một đường chuẩn cho việc đo đạc hiệu năng dự án. Đây là quy trình gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102259, 'Quản lý chi phí', false, 93071);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102260, 'Ước tính chi phí', false, 93071);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102261, 'Dự thảo ngân sách', true, 93071);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102262, 'Kiểm soát chi phí', false, 93071);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93072, 'Bạn được hỏi để chuẩn bị ngân sách để hoàn thành một dự án. Dự án này vừa bắt đầu năm ngoái và bị hoãn trong 6 tháng. Điều nào dưới đây không có trong ngân sách?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102263, 'Chi phí cố định', false, 93072);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102264, 'Chi phí ngầm', true, 93072);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102265, 'Chi phí trực tiếp', false, 93072);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102266, 'Chi phí biến động (VC – variable costs)', false, 93072);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93073, 'Để cung cấp một dự án mới cho phòng ban của mình, bạn cần di chuyển tài nguyên từ một dự án sang một dự án khác. Do phòng ban của bạn đang làm việc hết công suất, di chuyển tài nguyên sẽ chăncs chắn trì hoãn dự án mà bạn chuyển tài nguyên. Điều này làm ảnh hưởng tiêu cực ít nhất đến dự án nào dưới đây ếu bạn di chuyển tài nguyên từ dự án này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102267, 'Dự án A với tỷ lệ chi phí lợi ích là 0.8, không có tôn chỉ dự án, có 4 nguồn lực', true, 93073);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102268, '. Dự án B với NPV là 60000$, 12 nguồn lực, và chi phí biến động giữa 1000$ tới 2000$ một tháng', false, 93073);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102269, 'Dự án C với chi phí cơ hội là 300000$, không có hệ thống kiểm soát dự án, tỷ suất hoàn vốn nội bộ IRR là 12%', false, 93073);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102270, 'Dự án D với chi phí gián tiếp là 20000$ và 13 nguồn lực', false, 93073);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93074, 'Một dự án sản xuất có chỉ số thực hiện lịch trình SPI là 0.89 và chỉ số thực hiện chi phí CPI là 0.91. Thông thường, giải thích nào tốt nhất cho tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102271, 'Phạm vi dự án đã thay đổi', false, 93074);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102272, 'Một nhà cung cấp không kinh doanh nữa và một nhà cung cấp khác cần được tìm thấy', false, 93074);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102273, 'Các thiết bị thêm vào cần thiết phải mua', false, 93074);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102274, 'Hoạt động đường giới hạn thực hiện lâu hơn và cần nhiều giờ lao động để hoàn thành', true, 93074);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93075, 'Mặc dù các bên có liên quan nghĩ rằng có đủ tiền trong ngân sách, dự án thực hiện được 1 nửa và CPI là 0.7. Để xác định nguyên nhân cốt lõi, các bên có liên quan kiểm tra dự án và phát hiện ra ngân sách chi phí dự án đã bị ước tính một cách tương tự. mặc dù các ước tính hoạt động thêm vào ước tính dự án, các bên có liên quan nghĩ rằng có gì đó bị bỏ sót trong khi hoàn thành ước tính. Điều bị bỏ sót ấy là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102275, 'Chi phí ước tính được nên được sử dụng để đo CPI', false, 93075);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102276, 'SPI nên được sử dụng, k phải CPI', false, 93075);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102277, 'Ước tính từ dưới lên nên được sử dụng', true, 93075);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102278, 'Thông tin lịch sử không được tính đến', false, 93075);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93076, 'Bạn là một PM của công ty tư vấn lớn. cấp trên của bạn vừa hỏi ý kiến của bạn trong một quyết định về dự án nào công ty nên theo đuổi. Dự án A có tỷ suất hoàn vốn nội bộ IRR là 12%. Dự án B được dự đoán có tỷ lệ chi phí lợi ích BCR là 1.3. Dự án C có chi phí cơ hội là 75000$. Dự án D có thời gian thu hồi vốn là 6 tháng. Bạn sẽ chọn dự án nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102279, 'Dự án A', true, 93076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102280, 'Dự án B', false, 93076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102281, 'Dự án C', false, 93076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102282, 'Dự án D', false, 93076);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93077, 'You are about to take over a project from another project manager and find out the following information about the project. Activity Z has an early start ES of day 15 and a late start LS of day 20. Activity Z is a difficult activity. Cost performance index CPI is 1.1. Schedule performance index SPI is 0.8. There are 11 stakeholders on the project. Based on this information, which of the following would you be the Most concerned about?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102283, 'Schedule', true, 93077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102284, 'Float', false, 93077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102285, 'Cost', false, 93077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102286, 'The number of available resources', false, 93077);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93078, 'Sự khác nhau giữa đường chuẩn chi phí và ngân sách chi phí là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102287, 'Quản lý tài nguyên dự trữ', true, 93078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102288, 'Dự trữ phát sinh', false, 93078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102289, 'Ước tính chi phí dự án', false, 93078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102290, 'Tài khoản chi phí (cost account?)', false, 93078);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93079, 'Bạn cung cấp ước tính chi phí dự án cho nhà tài trợ dự án. Anh ta không hài lòng với ước tính, do anh ta nghĩ rằng giá có thể thấp hơn. Anh ta bảo bạn cắt giảm 15% ước tính dự án. Bạn nên làm gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102291, 'Bắt đầu dự án và liên tục tiết kiệm chi phí dự án(look for cost saving)', false, 93079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102292, 'Nói với đội dự án để cắt giảm 15% từ ước tính của họ', false, 93079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102293, 'Thông báo với nhà tài trợ về các hoạt động bị cắt giảm', true, 93079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102294, 'Thêm các nguồn tài nguyên với chi phí theo giờ thấp ( low hourly rates)', false, 93079);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93080, 'Khi một sản phẩm hay dịch vụ hoàn tất và đáp ứng yêu cầu của khách hàng tức là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102295, 'Chất lượng hoàn thiện', true, 93080);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102296, 'Chi phí của chất lượng là cao', false, 93080);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102297, 'Chi phí của chất lượng là thấp', false, 93080);
