INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93103, 'Đội dự án vừa tạo ra kế hoạch mô tả cách họ thực hiện chính sách chất lượng. Nó giải quyết cấu trúc hướng tổ chức, trách nhiệm, thủ tục và các thông tin khác về kế hoạch cho chất lượng. nếu thay đổi này trong quá trình thực hiện dự án, kế hoạch nào dưới đây sẽ thay đổi theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102387, 'Đảm bảo chất lượng', false, 93103);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102388, 'Quản lý chất lượng', false, 93103);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102389, 'Quản lý dự án', true, 93103);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102390, 'Kiểm soát chất lượng', false, 93103);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93104, 'Bạn là một PM cho một dự án hệ thống thông tin lớn khi một người từ phòng chất lượng đến và nói về bắt đầu kiểm tra chất lượng dự án của bạn. Đội dự án, đã chịu áp lực phải hoàn thành dự án nhanh nhất có thể, cảm thấy khó chịu về kiểm tra này. Bạn nên giải thích với đội rằng mục đích của kiểm tra chất lượng là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102391, 'A. Một phần của giám định ISO 9000', false, 93104);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102392, 'Để kiểm tra nếu khách hàng đang theo sát quy trình chất lượng.', false, 93104);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102393, 'C. Để xác định các chính sách không phù hợp', true, 93104);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102394, 'Để kiểm tra tính chính xác nếu chi phí được đội dự án xem xét', false, 93104);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93105, 'Bạn đang trong dự án xây dựng thiết bị mới. Các kết cấu đã được đặt vào vị trí và các ống dẫn nhiệt cũng sẽ được đặt đúng chỗ, khi đó người quản lý cấp cao thông báo với bạn rằng anh ta đang lo lắng dự án không đáp ứng được tiêu chuẩn chất lượng. Bạn nên làm gì trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102395, 'A. Cam đoan với người quản lý cấp cao rằng trong khi lên kế hoạch chất lượng đã xác định dự án sẽ đáp ứng được tiêu chuẩn chất lượng', false, 93105);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102396, 'Ước tính tương tự sẽ có kết quả trong tương lai', false, 93105);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102397, 'C. Đào tạo đội đảm bảo chất lượng', false, 93105);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102398, 'Kiểm tra kết quả từ các kế hoạch quản lý chất lượng trong quá khứ', true, 93105);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93106, 'Bạn được hỏi để lựa chọn công cụ và kỹ thuật để thực hiện chương trình đảm bảo chất lượng để bổ sung cho các hoạt động kiểm soát chất lượng đã có. Bạn nên chọn điều nào dưới đây?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102399, 'Kiểm tra chất lượng', true, 93106);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102400, 'Lấy mẫu thống kê', false, 93106);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102401, 'Biểu đồ Pareto', false, 93106);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102402, 'Phân tích xu hướng', false, 93106);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93107, 'Dự án cài đặt phần mềm mới đang thực hiện. PM đang làm việc với phòng ban đảm bảo chất lượng để cải thiện sự tin tưởng của mọi người rằng dự án sẽ đáp ứng các tiêu chuẩn chất lượng. điều nào dưới đây họ phải có trước khi bắt đầu quá trình này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102403, 'Các vấn đề chất lượng', false, 93107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102404, 'Cải thiện chất lượng', false, 93107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102405, 'Hệ thống đo đạc kiểm soát chất lượng', true, 93107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102406, 'Làm lại công việc (rework)', false, 93107);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93108, 'Dự án bạn đang làm việc có gia tăng chi phí hiệu quả, tăng hiệu suất và tăng tinh thần, chí khí(morale). Điều gì có thể là nguyên nhân cho các thay đổi này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102407, 'Mục tiêu dự án được đáp ứng khi thực hiện', false, 93108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102408, 'Tăng chất lượng', true, 93108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102409, 'Ban lãnh đạo tập trung vào chính sách ngăn chặn', false, 93108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102410, 'Tưởng thưởng (reward) cho nỗ lực của các các nhân', false, 93108);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93109, 'Một PM vừa đảm nhiệm dự án từ một PM khác trong giai đoạn thực thi dự án. Người PM trước đó đã tạo ra ngân sách dự án, xác định các yêu cầu truyền thông và đang chuẩn bị hoàn thành gói công việc. Người PM mới nên làm điều gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102411, 'A. Kết hợp thực hiện các gói công việc', false, 93109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102412, 'B. Xác định các tiêu chuẩn chất lượng', true, 93109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102413, 'C. Bắt đầu xác định rủi ro', false, 93109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102414, 'Thực hiện kế hoạch quản lý dự án', false, 93109);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93110, 'Một dự án đang phải đối mặt với 1 thay đổi lớn đối với sản phẩm đầu ra. Nếu PM phải quyết định tiêu chuẩn chất lượng nào là có liên quan tới thay đổi, PM sẽ', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102415, 'Quản lý chất lượng', false, 93110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102416, 'Thực hiện đảm bảo chất lượng', false, 93110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102417, 'Lên kế hoạch chất lượng', true, 93110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102418, 'Thực hiện kiểm soát chất lượng', false, 93110);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93111, 'Vào cuối dự án, PM xác định dự án sẽ thêm 4 vùng chức năng và 3 vùng hiệu năng. Khách hàng bày tỏ sự hài lòng với dự án. Sự thành công của dự án có nghĩa là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102419, 'Dự án không đủ tiêu chuẩn thành công', false, 93111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102420, 'Dự án không thành công vì nó thực hiện thêm những điều khách hàng muốn mà k được trả thêm tiền (gold plating)', true, 93111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102421, 'Dự án không thành công do khách hàng hài lòng nghĩa là họ phải trả thêm tiền cho công việc', false, 93111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102422, 'Dự án thành công do đội đã có cơ hội học các vùng chức năng mới và khách hàng hài lòng', false, 93111);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93112, 'Trong giai đoạn thực thi dự án, một nhân viên đội dự án thông báo với PM rằng một gói công việc không đáp ứng được tiêu chuẩn chất lượng, và cô ta tin rằng gói công việc này không thể đáp ứng được. PM họp với các bên có liên quan để phân tích tình huống. PM này đang ở trong quy trình quản lý chất lượng nào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102423, 'Thực hiện đảm bảo chất lượng', false, 93112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102424, 'Kiểm soát dự án', false, 93112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102425, 'Thực hiện kiểm soát chất lượng', true, 93112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102426, 'Lên kế hoạch chất lượng', false, 93112);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93113, 'PM chú ý rằng các hoạt động dự án đang được hoàn thành bởi 1 phòng ban đều làm việc không đáng kể so với kế hoạch. Đến thời hạn, không có hoạt động hay gói công việc nào đi đúng đường tới hạn, cũng như nó ảnh hưởng tới kế hoạch chuỗi tới hạn. PM khó chịu vì vấn đề này. Khi 4/5 hoạt động trong đường tới hạn phải được phòng ban này thực hiện. sau khi gọi 3 cuộc, cuối cùng, PM quyết định trái với người lãnh đạo của phòng ban này và xác định điều gì đang xảy ra. Cuộc hội thoại này lâu do cả 2 nói 2 ngôn ngữ khác nhau và họ cố gắng giao tiếp bằng tiếng Pháp(ngôn ngữ chung). Để giúp việc giao tiếp đơn giản hơn, PM thường xuyên yêu cầu người lãnh đạo của phòng ban này nhắc lại những gì đã nói. Anh ta nói với nhân viên của mình tuân theo chính sách của công ty và yêu cầu 2 mức kiểm thử. Trong quá trình hội thoại, anh ta cũng nhận xét khiến cho người PM tin rằng chính sách bao gồm quá nhiều công việc. Đây là lần thứ 4 PM nghe những nhận xét như thế. PM nên làm gì tốt nhất?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102427, 'Thời gian trễ trong các đường khác', false, 93113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102428, 'Sự xuất hiện đường tời hạn mới.', true, 93113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102429, 'Các nguồn lực được chỉ định cho các nhiệm vụ khác trên đường tới hạn', false, 93113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102430, 'Nhiệm vụ dài nhất còn lại trong kế hoạch', false, 93113);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93114, 'Điều chỉnh các nhiệm vụ được phân bổ khác nhau trong dự án để duy trì khối lượng nguồn lực phù hợp được gọi là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102431, 'Tạo ra kế hoạch quản lý truyền thông tốt hơn và yêu cầu chỉ một ngôn ngữ chính thức trong dự án và phải có người dịch ngay lập tức', false, 93114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102432, 'Liên lạc với ai đó trong phòng ban, người này cũng nói ngôn ngữ mẹ đẻ của PM tốt để xác nhận ý kiến của người lãnh đạo phòng ban đó', false, 93114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102433, 'Tìm xem nếu hành động tiếp theo có nên ước tính lại không', false, 93114);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102434, 'Làm việc với hiệu quả gia tăng của tổ chức thực hiện bằng cách khuyến khi sự cải thiện của chính sách bằng cách sử dụng các câu hỏi', true, 93114);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93115, 'Một PM bị tràn ngập với các vấn đề trong dự án của anh ấy. Anh ta xác định nguyên nhân gốc rễ của vấn đề theo thứ tự để xác định nên tập trung vào đâu. Công cụ nào dưới đây là tốt nhất để anh ta sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
