INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102441, 'Sơ đồ Ishikawa', false, 93116);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102442, 'Sơ đồ điều khiển', true, 93116);
