INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93119, 'Hiệu ứng hào quang (halo affect) liên quan tới xu hướng:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
