INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93120, 'Một chướng ngại vật đối với đội dự án trong một tổ chức hướng ma trận là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
