INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93121, 'Các điều dưới đây là mối quan tâm đặc trưng của thành viên đội dự án hướng ma trận (matrixed team members), ngoại trừ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
