INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93127, 'Bạn được phân công làm PM cho một dự án truyền thông lớn. Dự án được hoàn thành trong 1 năm và đã đi được nửa đường. Đội dự án bao gồm 5 người bán và 20 nhân viên của công ty bạn. Bạn muốn biết ai là người có trách nhiệm với công việc trong dự án. Bạn sẽ tìm thấy các thông tin này ở đâu?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
