INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93128, 'Trong giai đoạn lập kế hoạch dự án ở một tổ chức hướng ma trận, PM xác định rằng sẽ cần thêm nguồn nhân lực. PM sẽ yêu cầu các nguồn lực này từ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
