INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93129, 'Một PM phải công bố lịch trình dự án. Các hoạt động, ngày bắt đầu, kết thúc và các nguồn lực đã được xác định. Người PM nên làm gì tiếp theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
