INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93130, 'Trong mỗi buổi họp đội dự án, PM hỏi mỗi thành viên đội dự án mô tả công việc họ đang làm và PM phân công các công việc mới cho mỗi thành viên. Thời gian kéo dài của buổi họp tăng do có nhiều công việc khác nhau được phân công. Điều này có thể xảy ra do tất cả các nguyên nhân dưới đây, ngoại trừ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102495, 'Sự thiếu bảng WBS', false, 93130);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102496, 'Sự thiếu ma trận gán trách nhiệm', false, 93130);
