INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93131, 'Bạn là một PM đứng đầu một dự án liên chức năng trong môi trường ma trận yếu. không có thành viên nào trong đội dự án báo cáo với bạn một cách hữu dụng và bạn không có khả năng để trực tiếp tưởng thưởng cho sự làm việc của họ. dự án khó, kéo theo ràng buộc nghiêm ngặt về thời gian và các thách thức trong quản lý chất lượng. Loại hình sức mạnh quản lý dự án nào dưới đây sẽ có hiệu quả nhất trong tình huống này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
