INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102502, 'Luật chính thức (formal)', false, 93131);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93132, 'Một nhân viên dự án không làm việc tốt trong dự án do cô ấy thiếu kinh nghiệm trong công việc phát triển hệ thống. không có sẵn ai có đủ điều kiện để làm việc này. Đối với PM, giải pháp nào là tốt nhất ?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
