INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93133, 'Một dự án có một vài đội. Đội C đã một lần không kịp deadline trong quá khứ. Điều này là nguyên nhân khiến đội D phải hủy đường tới hạn một vài lần. Với tư cách là ng lãnh đạo của đội D, bạn nhận được thông tin rằng deadline tiếp theo có thể sẽ không kịp. bạn nên gặp và trao đổi với:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102507, 'Người quản lý của đội D', false, 93133);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102508, 'Chỉ riêng PM', false, 93133);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102509, 'PM và ban lãnh đạo', false, 93133);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102510, 'PM và đội trưởng đội C', true, 93133);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93134, 'Dự án mới làm hứng khởi cả PM và đội dự án. Đây là lần đầu tiên người PM được phân công vai trò là PM. Đội có cảm giác họ có khả năng hoàn thành công việc mà chưa bao giờ làm trước đó. Đội gồm 29 người góp phần mô tả sản phẩm và đội gồm 9 chuyên gia nhiều kinh nghiệm chuyên môn. Trong quá trình lên kế hoạch, 3 nhân viên có chuyên môn cao đã không đồng ý về phạm vi của 2 sản phẩm. một ng chỉ ra rằng bản nháp WBS nên thêm 2 gói công việc. một người nói rằng gói công việc liên quan không nên được thực hiện. người thứ 3 đồng ý với 2 người trên. PM nên giải quyết xung đột này ntn?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102511, 'PM nên lắng nghe sự khác biệt trong quan điểm, xác định lựa chọn tốt nhất và thực hiện nó', false, 93134);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102512, 'PM nên trì hoãn các thảo luận, gặp gỡ riêng từng người và xác định cách tiếp cận tốt nhất.', false, 93134);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102513, 'PM nên lắng nghe sự khác biệt trong quan điểm, khuyến khích các thảo luận logic và tạo điều kiện cho thỏa thuận', true, 93134);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102514, 'PM nên giúp đội dự án tập trung vào khía cạnh thích hợp trong ý kiến của họ và xây dựng sự thống nhất bằng cách sử dụng kỹ thuật', false, 93134);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93135, 'Dự án vừa bắt đầu và bao gồm nhân lực từ 14 phòng ban khác nhau. Tôn chỉ dự án được k{ bởi một người và bao gồm hơn 30 yêu cầu chính phải được đáp ứng trong dự án. Nhà tài trợ thông báo với PM rằng SPI phải được giữ trong khoảng 0.95 và 1.1. một vài phút điều tra dẫn đến xác định được 34 bên có liên quan, và mục tiêu lịch trình đã có ràng buộc. PM vừa mới được tuyển dụng. loại quyền lực quản lý dự án nào dưới đây là tốt nhất để giúp PM có được sự hợp tác từ những người khác?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102515, 'Luật chính thức', true, 93135);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102516, 'Tư vấn, tham khảo (referent)', false, 93135);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102517, 'Luật phạt', false, 93135);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102518, 'Chuyên môn', false, 93135);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93136, 'PM đang cố gắng giải quyết tranh chấp giữa 2 nhân viên dự án. Một ng nói rằng hệ thống nên được tích hợp trước khi kiểm thử, và người còn lại có ý kiến rằng ủng hộ việc mỗi hệ thống nên được kiểm thử trước khi tích hợp. Dự án bao gồm hơn 30 người, và 12 hệ thống cần phải tích hợp. nhà tài trợ yêu cầu rằng việc tích hợp phải được thực hiện đúng thời điểm. tuyên bố nào của PM là tốt nhất để giải quyết mâu thuẫn này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102519, 'Làm theo cách của PM', false, 93136);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102520, 'Mọi người hãy bình tĩnh để hoàn thành công việc', false, 93136);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102521, 'Hãy giải quyết vấn đề này một lần nữa vào tuần sau khi mọi người đều bình tĩnh', false, 93136);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102522, 'Hãy thực hiện các kiểm thử giới hạn trước khi thực hiện và kết thúc kiểm thử sau khi cài đặt', true, 93136);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93137, 'Một PM đang trong giai đoạn thực thi dự án khi một bên có liên quan đề nghị một thay đổi lớn. thay đổi này sẽ dẫn đến sửa chữa lớn lần thứ 3 của dự án. Vào cùng thời điểm, PM khám phá ra một gói công việc lớn của được hoàn thành do một thủ trưởng đã chuyển nhân viên của anh ta sang một dự án khác có mức độ ưu tiên cao hơn. Ai là người thích hợp nhất để PM xác định các vấn đề này cùng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102523, 'Đội dự án', false, 93137);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102524, 'Người quản lý cấp cao', false, 93137);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102525, 'Khách hàng', false, 93137);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102526, 'Nhà tài trợ', true, 93137);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93138, 'Làm việc trong một dự án đang thực hiện khi PM chợt nghe 2 nhân viên cãi nhau về tập hợp các hướng dẫn. PM điều tra và khám phá rằng các hướng dẫn cho việc xây dựng móng bên tông đang được đổ được dịch sai giữa 2 ngôn ngữ khác nhau đang được sử dụng trong dự án. Điều nào dưới đây là tốt nhất đối với PM để làm đầu tiên?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102527, 'Lấy hướng dẫn được dịch bởi một bên tin cậy và nhiều kinh nghiệm', false, 93138);
