INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102529, 'Làm đội dự án chú ý tới vấn đề này và hỏi họ tìm kiếm các lỗi khác của bản dịch', false, 93138);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102530, 'Thông báo với nhà tài trợ về vấn đề trong báo cáo dự án tiếp theo.', false, 93138);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93139, 'Kỹ thuật giải quyết xung đột có thể được sử dụng trong dự án bao gồm: đối đầu, làm bình lặng (smoothing), vũ lực và:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
