INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93155, 'Một dự án lớn về viễn thông trong 1 năm đã đi được nửa đường khi bạn tiếp quản vị trí PM từ 1 ng khác. Dự án kéo theo 3 người bán khác nhau và một đội dự án gồm 30 người. bạn muôn xem các yêu cầu truyền thông dự án và kỹ thuật nào được sử dụng để giúp đỡ trong truyền thông. Bạn sẽ tìm thấy nó ở đâu?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
