INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102610, 'Mức độ và tông giọng của mỗi người(nói từ từ hay quát vào mặt nhau J) ) vàcách nói riêng của mỗi người.', true, 93158);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93159, 'Một PM có một đội dự án bao gồm các nhân viên từ 4 quốc gia. Dự án rất quan trọng đối với công ty, và PM có liên quan tới thành công của dự án. Thời gian của dự án là chấp nhận được. Loại phương pháp truyền thông nào anh ta nên sử dụng?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102611, 'Lời nói không chính thức', false, 93159);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102612, 'Văn bản chính thức', true, 93159);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102613, 'Lời nói chính thức', false, 93159);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102614, 'Văn bản không chính thức', false, 93159);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93160, 'Nhân tố nào có ảnh hưởng lớn nhất tới chi phí lao động theo ước tính trên đơn vị cho dự án.', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102615, 'Thông tin lịch sử', false, 93160);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102616, 'Sử dụng các nhà cung cấp bên ngoài.', false, 93160);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102617, 'Các quy trình kiểm soát thay đổi.', false, 93160);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102618, 'Các yêu cầu mức độ kỹ năng nguồn nhân lực', true, 93160);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93161, 'Buổi họp tiến trình dự án không diễn ra tốt đẹp. mọi người nói tất cả mọi lúc, có nhiều ngừoi không tham gia vào và có nhiều chủ đề được thảo luận ngẫu nhiên. Luật nào dưới đây cho buổi họp hiệu quả đã không được tuân theo?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102619, 'Sự tập trung lịch sự và cân nhắc của mỗi cá nhân, sự điều khiển ai sẽ được nói', false, 93161);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102620, 'Lịch trình buổi họp', false, 93161);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102621, 'Họp có mục đích, với những người phù hợp tham gia vào buổi họp', false, 93161);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102622, 'Tạo ra và công bố một vấn đề và một tập các luật để điều khiển buổi họp', true, 93161);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93162, 'Bạn vừa được phân công là PM cho một dự án sản xuất lớn. dự án 1 năm này đã thực hiện được 1 nửa. nó kéo theo 5 người bán và 20 thành viên trong công ty tham gia vào đội dự án. Bạn muốn xem xét lại thật nhanh dự án đang tiến triển tới đâu. Báo cáo nào dưới đây là có ích nhất để tìm những thông tin như vậy?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102623, 'Trạng thái công việc(work status)', false, 93162);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102624, 'Tiến trình (progress)', true, 93162);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102625, 'Dự báo(forecast)', false, 93162);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102626, 'Truyền thông', false, 93162);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93163, 'Một nhân viên đang tham quan nhà máy sản xuất của một trong những nhà cung cấp. Điều nào dưới đây là quan trọng nhất phải làm trong bất kz cuộc gọi nào mà PM sẽ gọi cho anh ta?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102627, 'A. Yêu cầu nhân viên lặp lại những gì PM nói', true, 93163);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102628, 'Xem xét lại danh sách thông tin liên lạc của tất cả các bên có liên quan', false, 93163);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102629, 'Yêu cầu nhân viên tìm kiếm các yêu cầu thay đổi', false, 93163);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102630, 'Xem xét lại lịch họp sắp tới', false, 93163);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93164, 'Một PM tình cờ nghe được cuộc hội thoại giữa 2 bên có liên quan đang nói về sự không hài lòng của họ về ảnh hưởng của dự án tới phòng ban của họ. bên có liên quan A hỏi dự án đang đúng tiến độ không và bên B trả lời là 1.05. bên A hỏi PM có biết sự liên quan của việc này tới bên B không, bên B trả lời anh ta không chắc chắn. Điều tốt nhất là PM nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102631, 'Chắc chắn rằng các bên có liên quan nhìn thấy PM đang tình cờ nghe và yêu cầu họ chuyển các câu hỏi cho PM bằng văn bản', false, 93164);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102632, 'Thuyết trình với tất cả các bên có liên quan về trạng thái của dự án', false, 93164);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102633, 'Gửi cho 2 bên có liên quan này bản copy về nhật ký vấn đề (issue log) và hỏi xem có nhận xét gì nữa không', false, 93164);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102634, 'Sắp xếp 1 cuộc họp với cả 2 bên có liên quan này để nghe họ nói về bất kz vấn đề liên quan nào mà họ có.', true, 93164);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93165, 'Một PM đã quản lý 4 dự án cho công ty và đang được cân nhắc để tham gia vào phòng quản lý dự án. Đây là những điều đã rút ra được sau quá trình đáng giá năng lực của anh ta: dự án đầu tiên của PM này có biến động chi phí CV = -500, sử dụng 2 nguồn lực then chốt, cần phải làm lại tôn chỉ dự án trong giai đoạn thực thi và được xếp hạng ưu tiên thứ 14 trong công ty. Dự án thứ 2 kết thúc với biến động lịch trình là +100, được hoàn thành với lịch trình nén rộng (vastly compressed schedule) và nhận được thư giới thiệu từ nhà tài trợ, nhưng sản phẩm của dự án không được sử dụng. Dự án thứ 3 có số lượng thay đổi hơn 23% so với dự kiến, có SPI=0.90 và 35 mục trong nhật ký vấn đề (issue log) khi dự án hoàn thành. Mỗi dự án có ngân sách chi phi là 1000$ và khoảng 20 tới 28% thay đổi nhiều hơn so với các dự án khác cùng quy mô. Phòng quản lý dự án quyết định không cân nhắc người PM này vào phòng nữa. Điều nào dưới đây mô tả tốt nhất tại sao PM lại không được vào?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102635, 'PM chỉ quản lý các dự án có mức độ ưu tiên thấp và anh ta phải nén lịch trình, cho thấy anh ta không đủ kỹ năng để làm việc trong phòng quản lý dự án', false, 93165);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102636, 'Nhật ký lỗi không nên được sử dụng trong những dự án có quy mô này, cho thấy PM không đủ kiến thức để làm việc trong phòng quản lý dự án', false, 93165);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102637, 'PM không thu hút hiệu quả các bên có liên quan, cho thấy anh ta không đủ kiến thức để làm việc trong phòng quản lý dự án', true, 93165);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102638, 'PM có 2 nguồn lực then chốt trong đội của mình và vẫn cần phải làm lại tôn chỉ dự án, cho thấy anh ta không đủ kỷ luật để làm việc trong phòng quản lý dự án', false, 93165);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93166, 'Mọi thứ đang hoạt động tốt trong giai đoạn giữa của một dự án. Hệ thống cấp phép công việc cho phép mọi người biết thời gian bắt đầu công việc và nhật ký lỗi đã giúp theo dõi các yêu cầu của các bên có liên quan. Tỷ suất chi phí có ích được cải thiện và nhà tài trợ bày tỏ sự đánh giá cao của mình cho những nỗ lực của đội dự án bằng cách tổ chức một buổi tiệc quan trọng cho đội. PM đã nhận được 1 cuộc gọi từ 1 thành viên dự án nói rằng kết quả từ việc hoàn thành hoạt động trước đã bị chậm 2 ngày. L{ do nào dưới đây là tốt nhất giải thích tại sao điều này xảy ra?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102639, 'PM tập trung vào yêu cầu của nhà tài trợ', false, 93166);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102640, 'Ban lãnh đạo chức năng không được tính đến trong kế hoạch quản lý truyền thông', true, 93166);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102641, 'Hoạt động tiếp sau nên được theo dõi, không phải hoạt động trước đó', false, 93166);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102642, 'Những người cần thiết không được mời đến buổi tiệc quan trọng', false, 93166);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93167, 'Có nhiều gói công việc đã hoàn thành tốt đẹp trong dự án và nhà tài trợ đã có một vài sự đánh giá cao cho sự cải thiện. Dự án đang trong đúng lịch trình để đáp ứng hạn chót gấp gáp (aggressive schedule) khi hành động sau của hoạt động đường tới hạn gặp phải một trở ngại lớn (suffer a major setback). Hoạt động này có 14 ngày trễ (14days of float) và được 4 ng hoàn thành. Có 2 nhân viên khác có kỹ năng trợ giúp hoạt động này, nếu cần thiết. PM nhận được 1 cuộc gọi rằng 3 nhân viên khác đang cố gắng rời khỏi dự án do họ không cảm thấy rằng dự án có thể thành công. Khi PM tiếp tục theo đuổi vấn đề này, cô ấy khám phá ra rằng những nhân viên này có vấn đề mà chưa được xác định trc đó. Điều nào dưới đây là tốt nhất để cải thiện dự án?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102643, 'Các nhân viên dự án ngay lập tức cố gắng giải quyết hoạt động đang gặp vấn đề', false, 93167);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102644, 'Điều tra xem tại sao lịch trình dự án lại gấp gáp', false, 93167);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102645, 'Tìm xem ai có thể thay thế 3 nhân viên đó', false, 93167);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102646, 'Tạo nhật ký lỗi', true, 93167);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93168, 'Dự án có 13 nhân viên và chịu ảnh hưởng từ 15 phòng ban trong tổ chức. Do dự án đã hoàn thành được 20% thời hạn dự án và có báo cáo hiệu năng thành công từ 5 phòng ban, PM tổ chức 1 buổi tiệc. PM mời các bên có liên quan từ tất cả các phòng ban, cung cấp những đánh giá tốt về một cơ hội truyền thông phi chính thức để truyền tải những điều tốt tới những phòng ban chưa tham gia vào dự án. Tại buổi tiệc, PM đi 1 vòng để khám phá và tìm các thông tin có liên quan tới 1 trng những phòng ban đang nói về việc thiết lập nhiều buổi họp chính thức hơn trong dự án. Điều tốt nhất PM nên làm đầu tiên là:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102647, 'Ghi lại những ấn tượng sâu sắc của buổi tiệc vào các bài học thu được từ dự án', false, 93168);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102648, 'Xem lại phương pháp phân phối thông tin trong dự án', true, 93168);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102649, 'Tổ chức một buổi họp với tất cả các bên có liên quan để thảo luận các mối bận tâm của họ', false, 93168);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102650, 'Chắc chắn rằng ban lãnh đạo có bản copy của kế hoạch quản lý truyền thông đểanh ta có thể nhớ những mối bận tâm này nên được gửi tới PM', false, 93168);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93169, 'Một dự án lớn đang thực hiện khi một nhân viên đội dự án xem lại báo cáo trạng thái dự án. Anh ta thấy rằng dự án hiện tại đang thực hiện chậm lịch trình. Khi tìm kiếm sâu hơn, anh ta chú ý rằng sự chậm trễ là nguyên nhân của hoạt động của anh ta bị dời lịch trong thời gian anh ra nước ngoài và không thể thực hiện được hoạt động này. Đây là mối bận tâm lớn do anh ta cam kết dự án sẽ thành công và anh ta không muốn là nguyên nhân của sự chậm trễ hơn của dự án. Điều tốt nhất nên làm là gì?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102651, 'Liên lạc với PM ngay lập tức để cung cấp cho PM lịch trình', false, 93169);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102652, 'Thêm các thông tin này vào báo cáo lần tới của anh ta', false, 93169);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102653, 'Yêu cầu vấn đề này được thêm vào nhật ký lỗi của dự án', false, 93169);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102654, 'Khuyến nghị hành động hiệu chỉnh', true, 93169);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93170, 'Dự án của bạn đang có một thời gian khó khăn trong việc có được phê chuẩn chính thức của kế hoạch quản lý dự án do có nhiều yêu cầu của các bên có liên quan chưa được phê chuẩn để liên quan trong dự án. Các bên có liên quan cãi nhau và làm chậm tiến độ dự án khi họ cứ tổ chức buổi họp này tới buổi họp khác về các yêu cầu của họ. Dự án cuối cùng cũng được phê chuẩn và đã bắt đầu từ 6 tháng trước. Tất cả những điều sau sẽ là những hành động ngăn chặn tốt, ngoại trừ:', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102655, 'Giữ một file về những yêu cầu nào chưa được bao gồm trong dự án', false, 93170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102656, 'Chắc chắn rằng quy trình kiểm soát thay đổi không được sử dụng như một phươngtiện để thêm vào những yêu cầu vào dự án', false, 93170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102657, 'Duy trì nhật ký lỗi', false, 93170);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102658, 'Tổ chức các buổi họp với các bên có liên quan để vượt qua những công việcìnhchưa được thêm vào dự án', true, 93170);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (93171, 'PM đang hi vọng một sản phẩm sẽ được đệ trình (submit) bằng email từ một nhân viên vào ngày hôm nay. Vào cuối ngày, PM liên lạc với nhân viên đó để thông báo rằng PM chưa nhận được email. Nhân viên này xin lỗi và nói rằng anh ra không thể email về sản phẩm, và nó sẽ được gửi thông qua thư thay vì email. Nhân viên này tiếp tục giải thích rằng anh ta đã thông báo với PM điều này sẽ xảy ra trong một cuộc điện thoại khi PM đang du lịch. PM nói:”chúng ta có nói chuyện không khi mà tôi đã nói với anh là tôi không nghe thấy anh nói gì vì sóng yếu?” người nhân viên trả lời: “Có”. Điều gì sẽ ngăn chặn vấn đề này?', 'SINGLE_CHOICE', 90031, 9998, 'PUBLIC', 'MEDIUM');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102659, 'Sử dụng ngôn ngữ truyền đạt cụ thể (paralingual communication)', false, 93171);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (102660, 'Thêm vào nhật ký lỗi sau cuộc gọi đó', false, 93171);
