INSERT INTO _question (id, text, type, category_id, created_id, approval_status, question_level) VALUES (300005, 'Nguyên nhân cơ bản làm cho tư bản cố định hao mòn hữu hình là gì?', 'SINGLE_CHOICE', 99001, 9997, 'PRIVATE', 'MEDIUM');
